-- Questions whose whole objective left the exam: inactive, with no objective.
update cert_questions q
set is_active = false, sub_objective_id = null, updated_at = now()
from cert_sub_objectives s
join cert_domains d on d.id = s.domain_id and d.certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101')
where q.sub_objective_id = s.id and s.code like 'v14-%';

-- Correction.
update cert_questions set
  options = (select jsonb_agg(jsonb_set(e.elem, '{is_correct}', to_jsonb(e.ord - 1 = 0)) order by e.ord) from jsonb_array_elements(options) with ordinality as e(elem, ord)),
  correct_index = 0,
  explanation = 'The trident, three prongs ending in a circle, a triangle and a square, is the USB logo, printed beside USB ports such as Type-A. Thunderbolt ports are marked with a lightning bolt with an arrowhead, HDMI ports carry the HDMI logo, and eSATA ports their own eSATA marking.',
  updated_at = now()
where id = 'd566c5ee-a962-4ee6-927d-958b8918ae33';

-- Correction.
update cert_questions set
  options = '[{"text":"The motherboard does not support more than 16 GB","is_correct":false},{"text":"The new and existing modules run at different speeds or timings","is_correct":true},{"text":"DDR4 modules cannot be mixed with other DDR4 modules","is_correct":false},{"text":"The PSU wattage is insufficient for additional RAM","is_correct":false}]'::jsonb,
  correct_index = 1,
  explanation = 'Instability after adding RAM usually means the modules don''t agree: the new 8 GB sticks and the old 4 GB sticks run at different speeds, timings or voltages, and the system settles on settings one set doesn''t handle reliably. Use matched modules, or set the memory to the slower kit''s speed and timings. The board clearly supports 24 GB, since it booted with it; DDR4 modules can be mixed in principle; and RAM draws far too little power for the PSU to be the cause.',
  updated_at = now()
where id = 'aa0b59bf-7de4-4cc2-a7c9-644b8fce56d6';

-- New questions for what 220-1201 added.
insert into cert_questions (certification_id, domain_id, sub_objective_id, question_text, options, correct_index, explanation, difficulty, is_active, is_diagnostic_eligible)
select (select id from certifications where slug = 'a-plus-core1-220-1101'), n.domain_id, n.id, v.question_text, v.options::jsonb, v.correct_index, v.explanation, v.difficulty, true, true
from (values
  ('1.2', 'A user who types all day wants a laptop that lets them move the pointer without lifting their hands from the home row of the keyboard. Which built-in pointing device should the technician look for?', '[{"text":"Trackpad","is_correct":false},{"text":"Drawing pad","is_correct":false},{"text":"Track point","is_correct":true},{"text":"Digitizer","is_correct":false}]', 2, 'A track point is the small pressure-sensitive nub between the G, H and B keys: the user pushes it with a fingertip to move the pointer, and buttons just below the space bar act as clicks, so the hands stay on the keys. A trackpad sits below the keyboard, so a hand has to leave the keys to use it. A drawing pad is a separate tablet for pen input, and a digitizer is the touch-sensing layer of a screen.', 1),
  ('1.3', 'A user''s phone plan keeps going over its data cap, although the phone is connected to the home Wi-Fi most evenings. The technician finds the Wi-Fi signal is weak in the bedroom, where the user streams video at night. Which phone feature is MOST likely using the cellular data?', '[{"text":"Bluetooth pairing with the user''s wireless headphones","is_correct":false},{"text":"Location services tracking the phone by GPS satellites","is_correct":false},{"text":"Airplane mode with Wi-Fi turned back on for the night","is_correct":false},{"text":"Switching to cellular data when Wi-Fi is weak","is_correct":true}]', 3, 'Phones can move traffic to cellular data on their own when the Wi-Fi signal is poor (Wi-Fi Assist on iPhone, and similar switch-to-mobile-data settings on many Android phones), so streaming in a room with weak Wi-Fi quietly uses the plan. Turning that setting off, or improving Wi-Fi coverage, stops it. Bluetooth headphones don''t use cellular data, GPS only receives satellite signals, and airplane mode turns the cellular radio off.', 2),
  ('1.3', 'On a flight, a user wants to use the aircraft''s Wi-Fi while making sure the phone doesn''t connect to any cellular network. What should the technician tell the user to do?', '[{"text":"Turn on airplane mode, then switch Wi-Fi back on","is_correct":true},{"text":"Turn off Wi-Fi and keep cellular data turned on","is_correct":false},{"text":"Remove the SIM card, then restart the phone","is_correct":false},{"text":"Turn on the personal hotspot before takeoff","is_correct":false}]', 0, 'Airplane mode switches off the cellular radio, and both iPhone and Android phones let the user turn Wi-Fi (and Bluetooth) back on while airplane mode stays on. Leaving cellular data on keeps the phone on the cellular network. Removing the SIM doesn''t switch the radio off, since the phone still looks for networks to allow emergency calls, and it does nothing for an eSIM. A hotspot shares the phone''s connection with other devices.', 1),
  ('1.3', 'A user''s new phone has no SIM card tray. The carrier has emailed a QR code for moving the user''s existing phone number to the new phone. What should the technician do?', '[{"text":"Order a nano-SIM card from the carrier and insert it","is_correct":false},{"text":"Turn on Wi-Fi calling so the number moves over Wi-Fi","is_correct":false},{"text":"Scan the QR code to add the carrier''s eSIM profile","is_correct":true},{"text":"Enter the SIM PIN that came with the old phone''s card","is_correct":false}]', 2, 'An eSIM is a SIM built into the phone that the carrier programs remotely; scanning the carrier''s QR code (or using the carrier''s app) downloads the eSIM profile that holds the number and plan. A phone with no tray can''t take a physical nano-SIM. Wi-Fi calling only routes calls for a line that is already active, and a SIM PIN unlocks a SIM that''s already installed; neither adds a line to the phone.', 2),
  ('1.3', 'A user entered the wrong SIM PIN three times, and the phone now asks for a PUK code. What should the technician do?', '[{"text":"Factory reset the phone to clear the SIM lock","is_correct":false},{"text":"Get the SIM''s PUK from the carrier and enter it","is_correct":true},{"text":"Keep entering likely codes until one works","is_correct":false},{"text":"Move the SIM card to another phone to bypass the lock","is_correct":false}]', 1, 'Three wrong PIN entries lock the SIM itself, and only its PIN unlock key (PUK), which the carrier keeps for that SIM, can unlock it and set a new PIN. Guessing is risky, because ten wrong PUK entries usually disable the SIM for good, and it then has to be replaced. A factory reset doesn''t touch the SIM''s lock, and the lock moves with the card to any other phone.', 2),
  ('1.3', 'A user traveling abroad for a month wants an inexpensive local data plan but still wants to receive calls and texts on their home number. The phone supports one physical SIM and one eSIM. What is the BEST setup?', '[{"text":"Swap the home SIM card for a local SIM card","is_correct":false},{"text":"Turn on data roaming on the home line for the trip","is_correct":false},{"text":"Turn off cellular data and rely on the hotspot feature","is_correct":false},{"text":"Add a local eSIM plan and use it for cellular data","is_correct":true}]', 3, 'A dual-SIM phone can keep the home line active for calls and texts while a second line, here a local eSIM plan, carries the cellular data. Swapping SIM cards takes the home number off the phone, and data roaming on the home line keeps the number but runs up roaming charges instead of using the cheap local plan. With cellular data off, the hotspot has no connection to share.', 3),
  ('1.3', 'Employees will use their own Android phones for work email and files. The company wants to manage only its own apps and data and to have no access to personal photos, apps or browsing. Which MDM configuration should the technician set up?', '[{"text":"Corporate-owned, fully managed enrollment","is_correct":false},{"text":"No enrollment, with mail settings entered by hand","is_correct":false},{"text":"BYOD enrollment with a separate work profile","is_correct":true},{"text":"Kiosk mode locked to the company''s email app","is_correct":false}]', 2, 'A bring-your-own-device (BYOD) enrollment keeps company apps and data in a separate work profile that IT manages, while personal apps, photos and browsing stay outside IT''s view, and removing the work profile takes only company data away. A fully managed enrollment gives the company control of the whole phone, which suits company-owned devices. Skipping enrollment leaves company data unmanaged, and kiosk mode locks the entire phone to one app.', 2),
  ('1.3', 'A company buys phones for its delivery drivers. IT must control every setting, allow only approved apps, and erase the entire phone if it''s lost. Which MDM device configuration fits these phones?', '[{"text":"Corporate configuration with full device management","is_correct":true},{"text":"BYOD configuration with a work profile","is_correct":false},{"text":"BYOD configuration with app protection only","is_correct":false},{"text":"Personal accounts with a passcode the driver picks","is_correct":false}]', 0, 'Company-owned phones can be enrolled in a corporate configuration, where MDM manages the whole device: all settings, which apps can be installed, and a full remote wipe. BYOD configurations deliberately limit IT to work apps and data, so they can''t lock down the entire phone or erase all of it. Personal accounts with a passcode give IT no management at all.', 2),
  ('1.3', 'An MDM compliance report flags a salesperson''s phone as noncompliant with the reason ''Device is rooted.'' The salesperson had installed unofficial software to remove the carrier''s restrictions. What will the compliance policy typically do?', '[{"text":"Nothing, since rooting only affects the user''s personal apps","is_correct":false},{"text":"Repair the operating system and remove root access","is_correct":false},{"text":"Raise the phone''s data plan to an unlimited tier","is_correct":false},{"text":"Block company email and apps until the phone complies","is_correct":true}]', 3, 'A rooted (or jailbroken) phone has had its built-in protections removed, so MDM policy enforcement marks it noncompliant and blocks company email, apps and data until it''s back in a supported state, usually by restoring the official OS. Rooting weakens security for everything on the phone, not just personal apps; MDM can''t undo it remotely; and the data plan has nothing to do with compliance.', 2),
  ('1.3', 'An MDM compliance report lists a salesperson''s tablet as noncompliant with the reason ''OS version below minimum,'' and the tablet can no longer open company apps. Which action will resolve the issue?', '[{"text":"Clear the cache and data of each company app","is_correct":false},{"text":"Install the latest operating system update","is_correct":true},{"text":"Turn on location services for the company apps","is_correct":false},{"text":"Remove the SIM card and insert it again","is_correct":false}]', 1, 'Policy enforcement lets MDM require a minimum operating system version so devices have current security fixes; installing the update makes the tablet meet the policy, and access returns. Clearing app data, turning on location services and reseating the SIM change nothing about the OS version the policy checks.', 2),
  ('1.3', 'A company wants each new employee''s phone to get the company mail account and the approved cloud storage app as soon as it''s enrolled, without anyone typing server settings. How should the technician deliver them?', '[{"text":"Email each user a PDF with the server settings","is_correct":false},{"text":"Push the mail profile and managed apps from the MDM","is_correct":true},{"text":"Let users install whichever cloud storage app they like","is_correct":false},{"text":"Set up each phone''s mail as a POP3 account","is_correct":false}]', 1, 'MDM can push business applications and settings to enrolled devices: a mail profile with the server settings already filled in, plus the approved cloud storage app, installed and managed by IT. A PDF of settings still leaves users to configure accounts by hand, letting users choose their own storage app puts company files outside IT''s control, and POP3 only downloads mail, without syncing folders, calendars or contacts.', 2),
  ('1.3', 'Field technicians use a company-managed cloud storage app to upload photos of every job. Their phones keep going over the data cap, mostly because of these uploads, although each technician is on the office Wi-Fi every evening. What should IT configure?', '[{"text":"Set the cloud storage app to upload only over Wi-Fi","is_correct":true},{"text":"Turn off photo uploads in the cloud storage app","is_correct":false},{"text":"Switch the phones'' company mail to POP3 accounts","is_correct":false},{"text":"Turn on data roaming so uploads use other networks","is_correct":false}]', 0, 'Business cloud storage apps can be set, by the user or through the MDM''s app configuration, to upload over Wi-Fi only, so the day''s photos sync on the office network each evening instead of using cellular data. Turning off uploads stops the business process, POP3 affects mail rather than file uploads, and roaming adds charges without reducing the data used.', 2),
  ('2.2', 'A new tri-band router broadcasts on 2.4 GHz, 5 GHz and 6 GHz. A recent phone connects on 6 GHz, but a laptop whose adapter is labeled Wi-Fi 6 (802.11ax) never does. What is the reason?', '[{"text":"The 6 GHz network accepts only WPA2 security","is_correct":false},{"text":"Routers hide 6 GHz networks from laptops by default","is_correct":false},{"text":"The laptop sits too close to the router to use 6 GHz","is_correct":false},{"text":"The laptop''s adapter supports only 2.4 GHz and 5 GHz","is_correct":true}]', 3, 'Wi-Fi 6 (802.11ax) adapters only work in the 2.4 GHz and 5 GHz bands; joining a 6 GHz network takes a Wi-Fi 6E or Wi-Fi 7 adapter. The 6 GHz band actually requires WPA3, not WPA2. Routers don''t hide the band from one type of device, and being close to the router doesn''t stop a 6 GHz connection.', 2),
  ('2.2', 'A technician sets up a tri-band router with one network name on all three bands, secured with WPA2-Personal so older devices can join. Wi-Fi 6E laptops still connect only on 5 GHz. Which change will let them use the 6 GHz band?', '[{"text":"Set the 6 GHz channel width to 20 MHz","is_correct":false},{"text":"Secure the 6 GHz network with WPA3-Personal","is_correct":true},{"text":"Turn off the 2.4 GHz band on the router","is_correct":false},{"text":"Switch all three bands to WPA2-Enterprise","is_correct":false}]', 1, 'The 6 GHz band requires WPA3 (or Enhanced Open for open networks), and WPA2 isn''t allowed there, so a WPA2 network can''t run on 6 GHz. Many routers use a separate WPA3 network on 6 GHz while the older bands keep WPA2 or WPA2/WPA3 for older devices. Channel width doesn''t change the security rule, turning off 2.4 GHz doesn''t enable 6 GHz, and WPA2-Enterprise is still WPA2.', 3),
  ('2.2', 'Compared with the 5 GHz band, which statement about the 6 GHz band is true?', '[{"text":"It has room for wider channels but a shorter range","is_correct":true},{"text":"It reaches farther and passes through walls more easily","is_correct":false},{"text":"It works with any 802.11ac (Wi-Fi 5) device or adapter","is_correct":false},{"text":"It only allows narrow 20 MHz channels, like 2.4 GHz","is_correct":false}]', 0, '6 GHz adds up to 1,200 MHz of spectrum in some countries, including the US and Canada, so there''s room for many 80 MHz and 160 MHz channels with no older devices crowding them. Higher frequencies lose more signal through walls, so range is shorter than on 5 GHz, not longer. Only Wi-Fi 6E and Wi-Fi 7 devices can use the band, and its channels go far wider than 20 MHz.', 2),
  ('2.2', 'A new smart thermostat can''t find the office Wi-Fi during setup, although phones and laptops connect fine. The thermostat supports only 2.4 GHz, and the access point broadcasts the network on 5 GHz only. What should the technician do?', '[{"text":"Move the 5 GHz network to a DFS channel","is_correct":false},{"text":"Widen the 5 GHz channel to 160 MHz","is_correct":false},{"text":"Turn on the 2.4 GHz band for the network","is_correct":true},{"text":"Change the security from WPA3 to WEP","is_correct":false}]', 2, 'Many smart-home devices have 2.4 GHz radios only, so they can''t see a network broadcast only on 5 GHz; turning on the 2.4 GHz band, often as a separate network name for such devices, lets the thermostat join. DFS channels and channel width are still 5 GHz, which the thermostat can''t use, and WEP is obsolete and insecure, so it should never be the fix.', 1),
  ('2.2', 'In a crowded apartment building, a user''s 5 GHz access point uses a 160 MHz channel width. A Wi-Fi analyzer shows several neighboring networks overlapping that range, and the connection keeps dropping. Which change would MOST likely improve reliability?', '[{"text":"Raise the access point''s transmit power to maximum","is_correct":false},{"text":"Move the 5 GHz radio over to channel 6 instead","is_correct":false},{"text":"Disable the 2.4 GHz band on the access point","is_correct":false},{"text":"Narrow the width to 40 or 80 MHz on a clear channel","is_correct":true}]', 3, 'A 160 MHz channel spans eight 20 MHz channels, so in a crowded building it almost certainly overlaps neighboring networks. A narrower width needs less clear spectrum, so the AP can sit where nothing overlaps it, at the cost of some peak speed. Maximum transmit power adds interference without fixing the overlap, channel 6 is a 2.4 GHz channel, and disabling 2.4 GHz doesn''t change the 5 GHz channel.', 2),
  ('2.2', 'Users on a 5 GHz network near an airport say the Wi-Fi drops briefly several times a week. Each time, the access point''s log shows ''Radar detected, changing channel.'' What should the technician do?', '[{"text":"Widen the channel to 160 MHz to add more capacity","is_correct":false},{"text":"Use a non-DFS channel, such as 36–48 or 149–165","is_correct":true},{"text":"Turn off WPA3 so clients reconnect more quickly","is_correct":false},{"text":"Hide the SSID so the network isn''t seen by radar","is_correct":false}]', 1, 'Many 5 GHz channels (52–144 in the US) are shared with radar under dynamic frequency selection (DFS) rules, and an AP must leave the channel when it detects radar, which drops clients. A channel outside that range, such as 36–48 or 149–165, avoids those forced moves. Most 160 MHz channels include DFS channels, so widening makes it worse, and the security setting and SSID broadcast have nothing to do with radar.', 3),
  ('2.3', 'A company''s inventory application runs on 40 desktops, and every desktop reads and updates the same stock records at the same time. The vendor says the records must live on a central server that answers the application''s queries. Which server role does the vendor mean?', '[{"text":"File server","is_correct":false},{"text":"Authentication server","is_correct":false},{"text":"Web server","is_correct":false},{"text":"Database server","is_correct":true}]', 3, 'A database server stores structured records and answers queries from many clients at once, managing simultaneous changes so one user''s update doesn''t overwrite another''s. A file server shares whole files rather than answering queries, an authentication server checks who users are, and a web server delivers web pages and apps over HTTP or HTTPS.', 1),
  ('2.3', 'Customers can open a company''s online store, but every product page shows ''Unable to load items.'' The web server''s log shows that its connections to the server holding the product and order records are timing out. Which server should the technician check next?', '[{"text":"The database server","is_correct":true},{"text":"The DHCP server","is_correct":false},{"text":"The mail server","is_correct":false},{"text":"The authentication server","is_correct":false}]', 0, 'Many web applications split the work: the web server builds the pages, and a database server stores and returns the records, here the products and orders. The web server is up, but its queries to the database server are timing out, so that''s the one to check. DHCP hands out IP addresses, a mail server handles email, and an authentication server checks who users are; none of them holds the store''s records.', 2),
  ('2.3', 'Several office PCs suddenly can''t sign in to the Windows domain, and the error mentions the time. Their clocks are eight minutes ahead of the domain controller''s. What is the BEST long-term fix?', '[{"text":"Set each PC''s clock by hand to match the domain controller","is_correct":false},{"text":"Renew each PC''s DHCP lease, then restart the PC","is_correct":false},{"text":"Sync the PCs'' clocks with the domain''s NTP source","is_correct":true},{"text":"Flush each PC''s DNS resolver cache and restart","is_correct":false}]', 2, 'Domain sign-in uses Kerberos, which by default rejects clocks more than five minutes apart, so the PCs must keep matching the domain''s time. Network Time Protocol (NTP) synchronizes clocks automatically and keeps correcting drift. Setting clocks by hand only fixes today, and neither the DHCP lease nor the DNS cache affects the system clock.', 2),
  ('2.3', 'While investigating an incident, a technician lines up log entries from a firewall, two switches and a server, but the same events show up several minutes apart on different devices. What should be configured so future logs line up?', '[{"text":"A larger log storage limit on the syslog server","is_correct":false},{"text":"SNMP traps on every device","is_correct":false},{"text":"A static IP address on every device","is_correct":false},{"text":"All devices using the same NTP server","is_correct":true}]', 3, 'Log timestamps only line up when every device''s clock is right, and pointing all devices at the same Network Time Protocol (NTP) server keeps them synchronized. More storage keeps more entries but doesn''t correct their times, SNMP traps send alerts without fixing clocks, and static IP addresses have nothing to do with timekeeping.', 2),
  ('2.4', 'A network printer has a manually configured address, 192.168.1.50, that falls inside the DHCP scope. Twice this month a laptop leased the same address and caused a conflict. The printer must keep its manual setting. What should the technician do on the DHCP server?', '[{"text":"Add 192.168.1.50 as an exclusion","is_correct":true},{"text":"Create a reservation for the laptop","is_correct":false},{"text":"Shorten the lease duration","is_correct":false},{"text":"Delete the scope and create it again","is_correct":false}]', 0, 'An exclusion tells the DHCP server never to lease an address or range, which protects addresses set by hand on devices like printers. A reservation for the laptop fixes the laptop''s address but still lets another client lease .50, a shorter lease only changes how often clients renew, and a re-created scope would hand out .50 again.', 2),
  ('2.4', 'A DHCP scope covers 192.168.20.100 through 192.168.20.199. Addresses .100 through .109 are excluded, and two addresses outside that range are reserved for printers. How many addresses can the server lease to other clients?', '[{"text":"88","is_correct":true},{"text":"90","is_correct":false},{"text":"98","is_correct":false},{"text":"100","is_correct":false}]', 0, 'The scope holds 100 addresses (.100 to .199). The exclusion removes 10 of them, and the two reserved addresses are only leased to the printers they''re reserved for, which leaves 88 for everyone else. 90 forgets the reservations, 98 forgets the exclusion, and 100 forgets both.', 3),
  ('2.4', 'A company is moving its help desk to a hosted service at the provider''s host name acme.helpdesk.example.net, whose IP addresses can change without notice. Users should reach it as support.example.com. Which DNS record should the technician create for support.example.com?', '[{"text":"An A record with the provider''s current IP address","is_correct":false},{"text":"A CNAME record pointing to the provider''s host name","is_correct":true},{"text":"An MX record pointing to the provider''s host name","is_correct":false},{"text":"A TXT record holding the provider''s host name","is_correct":false}]', 1, 'A canonical name (CNAME) record makes one host name an alias for another, so support.example.com always follows whatever addresses the provider''s name resolves to. An A record would pin the name to today''s IPv4 address, which breaks when the provider changes it; an MX record names a domain''s mail servers; and a TXT record holds text, such as an SPF policy, rather than pointing anywhere.', 2),
  ('2.4', 'A technician runs nslookup for www.example.com. The output shows the line ''Name: web-prod.example.net'' with an IP address, followed by ''Aliases: www.example.com''. Which type of record is www.example.com?', '[{"text":"A (IPv4 address)","is_correct":false},{"text":"AAAA (IPv6 address)","is_correct":false},{"text":"CNAME (alias)","is_correct":true},{"text":"MX (mail exchanger)","is_correct":false}]', 2, 'The lookup followed an alias: www.example.com is a CNAME record pointing to the canonical name web-prod.example.net, which holds the address, so nslookup lists the name it started with under Aliases. An A or AAAA record would return an address for www.example.com directly, and an MX record names mail servers rather than a host''s address.', 2),
  ('2.5', 'A technician reserves an IP address for a user''s phone using the Wi-Fi MAC address shown on the phone''s About screen. On the office Wi-Fi, the phone still doesn''t receive the reserved address. What is the MOST likely cause?', '[{"text":"The phone''s physical MAC address changes after every restart","is_correct":false},{"text":"DHCP reservations only work for wired devices","is_correct":false},{"text":"The phone uses a private, randomized MAC on that network","is_correct":true},{"text":"The reservation needs the phone''s IMEI number instead","is_correct":false}]', 2, 'Current phones present a private, randomized MAC address to each Wi-Fi network by default, rather than the adapter''s physical MAC address shown on the About screen, so the DHCP server never sees the address in the reservation. Turning off the private address for that network, or reserving the address the phone actually uses there, fixes it. The physical (burned-in) MAC doesn''t change, reservations work for wireless clients, and DHCP identifies clients by MAC address, not IMEI.', 2),
  ('2.5', 'A technician finds an unknown device on the network with the MAC address 00-1A-2B-3C-4D-5E. Which part of the address can be looked up to find the device''s manufacturer?', '[{"text":"00","is_correct":false},{"text":"00-1A-2B","is_correct":true},{"text":"3C-4D-5E","is_correct":false},{"text":"4D-5E","is_correct":false}]', 1, 'A physical MAC address is 48 bits, written as six bytes. The first three bytes, 00-1A-2B here, are the organizationally unique identifier (OUI) assigned to the manufacturer, and the last three identify the individual interface. The last bytes alone say nothing about the vendor, and the first byte alone is only part of the OUI.', 1),
  ('3.1', 'Which statement BEST describes a Mini LED display?', '[{"text":"Each pixel makes its own light, so no backlight is needed","is_correct":false},{"text":"A panel that reflects room light instead of a backlight","is_correct":false},{"text":"An LCD lit by a fluorescent tube behind the panel","is_correct":false},{"text":"An LCD lit by thousands of tiny LEDs in dimming zones","is_correct":true}]', 3, 'Mini LED is still an LCD, but its backlight is made of thousands of very small LEDs grouped into many zones that dim independently, giving brighter highlights and deeper blacks than a conventional LED-backlit LCD. Pixels that make their own light describe OLED, reflecting room light describes reflective screens such as e-paper, and a fluorescent tube (CCFL) is the backlight of older LCDs, the kind that needs an inverter.', 1),
  ('3.1', 'A video editor wants a bright HDR monitor with deep contrast but will leave static timelines and toolbars on screen ten hours a day and is worried about burn-in. Which display technology fits BEST?', '[{"text":"OLED","is_correct":false},{"text":"TN LCD with an edge-lit backlight","is_correct":false},{"text":"Mini LED","is_correct":true},{"text":"IPS LCD with an edge-lit backlight","is_correct":false}]', 2, 'Mini LED''s many local dimming zones give high brightness and strong contrast for HDR, and because the light comes from a backlight rather than the pixels themselves, static toolbars don''t burn in the way they can on OLED. OLED has excellent contrast but is the technology most prone to burn-in, and edge-lit TN and IPS panels can''t dim parts of the screen independently, which limits their HDR contrast.', 2),
  ('3.1', 'A technician compares two monitors that both run at 1920×1080: one is 24 inches and the other is 32 inches. Viewed from the same distance, which statement is true?', '[{"text":"The 32-inch monitor has the higher pixel density, so text looks sharper","is_correct":false},{"text":"The 24-inch monitor has the higher pixel density, so text looks sharper","is_correct":true},{"text":"Both have the same pixel density because the resolution is the same","is_correct":false},{"text":"The 32-inch monitor shows more of a document at once","is_correct":false}]', 1, 'Pixel density, in pixels per inch (PPI), depends on how many pixels are spread across how much screen. The same 1920×1080 pixels on 24 inches (about 92 PPI) sit closer together than on 32 inches (about 69 PPI), so the smaller screen looks sharper. Equal resolution doesn''t mean equal density, and both monitors show exactly the same amount of a document; the larger one just draws it bigger.', 2),
  ('3.1', 'A user replaced a 24-inch 1920×1080 monitor with a 27-inch 3840×2160 model, and at 100% scaling the icons and text now look tiny. What explains this?', '[{"text":"The new monitor''s pixel density is much higher","is_correct":true},{"text":"The new monitor has a lower refresh rate","is_correct":false},{"text":"The new monitor uses a narrower color gamut","is_correct":false},{"text":"The video cable doesn''t support the new resolution","is_correct":false}]', 0, 'The new monitor packs about 163 pixels per inch against about 92 on the old one, so anything drawn with a fixed number of pixels comes out much smaller. Raising Windows display scaling, for example to 150%, restores a comfortable size while keeping the sharper text. Refresh rate and color gamut don''t change the size of items, and a cable that couldn''t carry the resolution would show a lower resolution or no picture, not smaller text.', 2),
  ('3.1', 'A monitor''s specifications list ''165 Hz.'' What does this number describe?', '[{"text":"How long a pixel takes to change from one color to another","is_correct":false},{"text":"How many frames per second the graphics card renders","is_correct":false},{"text":"How many pixels the screen has per inch","is_correct":false},{"text":"How many times per second the display redraws the image","is_correct":true}]', 3, 'Refresh rate, measured in hertz (Hz), is how many times per second the display redraws its image, so a 165 Hz monitor can show up to 165 new frames each second for smoother motion. The time a pixel takes to change color is response time, in milliseconds; frames per second is what the graphics card produces; and pixels per inch is pixel density.', 1),
  ('3.1', 'A gamer connects a new 144 Hz monitor using the DisplayPort cable that came in the box, but motion looks no smoother than on the old 60 Hz monitor. Windows'' advanced display settings show 60 Hz. What should the technician do FIRST?', '[{"text":"Replace the DisplayPort cable with an HDMI cable","is_correct":false},{"text":"Lower the screen resolution to 1280×720","is_correct":false},{"text":"Select 144 Hz in Windows'' display settings","is_correct":true},{"text":"Turn off the monitor''s adaptive sync feature","is_correct":false}]', 2, 'A high-refresh monitor often runs at 60 Hz until the higher rate is selected, in Windows under Settings > System > Display > Advanced display or in the graphics driver''s control panel. The bundled DisplayPort cable can carry 144 Hz, so swapping cables isn''t the first step, and lowering the resolution or turning off adaptive sync doesn''t select a higher refresh rate.', 2),
  ('3.1', 'A gamer''s 144 Hz monitor shows horizontal tearing whenever a game''s frame rate swings between about 70 and 140 frames per second. Which feature, supported by both the monitor and the graphics card, would fix this?', '[{"text":"A wide color gamut mode such as DCI-P3","is_correct":false},{"text":"Adaptive sync, so the refresh rate follows the frame rate","is_correct":true},{"text":"A panel with a higher pixel density at the same size","is_correct":false},{"text":"Dynamic contrast that adjusts the backlight to each scene","is_correct":false}]', 1, 'Tearing happens when the graphics card delivers a new frame partway through the monitor''s fixed refresh cycle, so parts of two frames show at once. Adaptive sync (variable refresh rate, sold as AMD FreeSync and NVIDIA G-SYNC) makes the monitor refresh whenever a frame is ready, within its supported range, which removes the tearing. Color gamut, pixel density and dynamic contrast don''t change when the screen refreshes.', 3),
  ('3.1', 'After a user connects a new 2560×1440 monitor, text looks slightly blurry. Windows shows the resolution as 1920×1080. What should the technician do?', '[{"text":"Increase the refresh rate to the highest setting","is_correct":false},{"text":"Turn on the monitor''s dynamic contrast mode","is_correct":false},{"text":"Lower the resolution to 1600×900 to sharpen text","is_correct":false},{"text":"Set the native resolution, 2560×1440","is_correct":true}]', 3, 'An LCD has a fixed grid of pixels, its native resolution, and looks sharpest when the computer sends exactly that resolution. At 1920×1080 the monitor has to scale the picture up to fill 2560×1440 pixels, which softens text. A higher refresh rate or dynamic contrast doesn''t stop the scaling, and an even lower resolution makes the blur worse.', 2),
  ('3.1', 'A customer wants a monitor marketed as 4K UHD. Which screen resolution will it have?', '[{"text":"1920×1080","is_correct":false},{"text":"2560×1440","is_correct":false},{"text":"3840×2160","is_correct":true},{"text":"7680×4320","is_correct":false}]', 2, '4K UHD is 3840×2160, four times the pixels of 1920×1080 (Full HD), which is why it looks sharper at the same size. 2560×1440 is QHD, often called 1440p, and 7680×4320 is 8K UHD.', 1),
  ('3.1', 'A monitor''s specifications list ''98% DCI-P3.'' Which display attribute does this describe?', '[{"text":"Contrast ratio","is_correct":false},{"text":"Color gamut","is_correct":true},{"text":"Refresh rate","is_correct":false},{"text":"Pixel density","is_correct":false}]', 1, 'Color gamut is the range of colors a display can reproduce, usually given as how much of a standard color space, such as sRGB, DCI-P3 or Adobe RGB, it covers. Contrast ratio compares the brightest white with the darkest black, refresh rate counts redraws per second, and pixel density counts pixels per inch.', 1),
  ('3.1', 'A photographer prepares images for a print shop that works in the Adobe RGB color space. On the current monitor, some greens and cyans look duller than they turn out in print. Which attribute matters MOST when choosing a replacement monitor?', '[{"text":"A wide color gamut covering most of Adobe RGB","is_correct":true},{"text":"A refresh rate of 144 Hz or more","is_correct":false},{"text":"A response time of 1 ms or less","is_correct":false},{"text":"A curved screen with a wider field of view","is_correct":false}]', 0, 'Adobe RGB includes greens and cyans that a standard sRGB monitor can''t display, so the photographer needs a wide-gamut monitor that covers most of Adobe RGB to see those colors before printing. Refresh rate and response time affect motion, not which colors can be shown, and a curved screen changes the shape, not the colors.', 2),
  ('3.2', 'A user connects a laptop to a USB-C monitor with a USB-C cable from a phone charger. The laptop charges from the monitor, but there''s no picture. The laptop''s USB-C port supports DisplayPort Alt Mode. What is the MOST likely cause?', '[{"text":"The monitor''s input source must be set to HDMI","is_correct":false},{"text":"USB-C can''t carry video and power at the same time","is_correct":false},{"text":"The cable supports only USB 2.0 data and charging","is_correct":true},{"text":"The laptop''s display driver needs to be rolled back","is_correct":false}]', 2, 'Video over USB-C (DisplayPort Alt Mode) uses a cable''s high-speed wire pairs, and many cables bundled with chargers only have the USB 2.0 pair and power wires, so they charge but can''t carry video. A full-featured USB-C cable rated for USB 3.x, USB4 or Thunderbolt fixes it. The HDMI input isn''t connected to anything, one USB-C cable can carry video and power together, and a driver rollback can''t add missing wires.', 2),
  ('3.2', 'A user connects a laptop to a 4K TV through a USB-C to HDMI adapter. The picture appears, but the mouse pointer and videos look choppy, and Windows shows 3840×2160 at 30 Hz. The laptop and the TV both support 4K at 60 Hz. What should the technician do?', '[{"text":"Use an adapter that supports 4K at 60 Hz (HDMI 2.0)","is_correct":true},{"text":"Set the TV''s color mode to sRGB to cut bandwidth","is_correct":false},{"text":"Turn on overscan in the TV''s picture size settings menu","is_correct":false},{"text":"Charge the laptop through a different USB-C port","is_correct":false}]', 0, 'Many USB-C to HDMI adapters only output HDMI 1.4 signals, which carry 3840×2160 at no more than 30 Hz, so motion looks choppy; an adapter rated for HDMI 2.0 and 4K at 60 Hz, with a cable rated for it, fixes it. The TV''s color mode and overscan don''t change the signal the adapter sends, and which port charges the laptop has nothing to do with the video.', 3),
  ('3.2', 'A USB-C to DisplayPort cable works when connecting a laptop''s USB-C port to a DisplayPort monitor. When a technician uses the same cable to connect a desktop''s DisplayPort output to a monitor with only a USB-C input, there''s no picture. What is the MOST likely cause?', '[{"text":"The desktop''s graphics card can''t output video at 4K","is_correct":false},{"text":"USB-C monitor inputs accept only HDMI video signals","is_correct":false},{"text":"The cable only carries video from USB-C to DisplayPort","is_correct":true},{"text":"The desktop needs a Thunderbolt firmware update first","is_correct":false}]', 2, 'Most USB-C to DisplayPort cables are one-way: they take DisplayPort Alt Mode from a USB-C source and deliver it to a DisplayPort display, so they can''t carry a DisplayPort output into a USB-C input. That direction needs a cable or adapter made for it, such as one sold as bidirectional. A resolution limit wouldn''t leave a working link blank, USB-C monitor inputs take DisplayPort Alt Mode rather than HDMI, and a DisplayPort output doesn''t depend on Thunderbolt firmware.', 3),
  ('3.4', 'A technician tries to install a 2.5-inch SAS SSD in a desktop whose motherboard has only SATA ports, but the drive''s connector won''t fit the SATA cable. What should the technician do?', '[{"text":"File down the connector so it fits the SATA cable","is_correct":false},{"text":"Install a SAS host bus adapter or RAID controller","is_correct":true},{"text":"Set the SATA ports to AHCI mode in UEFI","is_correct":false},{"text":"Use a Molex-to-SATA power adapter","is_correct":false}]', 1, 'Serial Attached SCSI (SAS) drives need a SAS controller. Their connector is keyed with a bridge between the data and power sections, so it won''t plug into a SATA cable, and SATA ports can''t run SAS drives anyway, although SAS controllers do accept SATA drives. Filing the connector would damage it without making it work, AHCI is a SATA controller mode, and a power adapter doesn''t change the data interface.', 2),
  ('3.4', 'Which drive interface is built for enterprise servers, connects through a host bus adapter or RAID controller, and offers dual ports so a drive stays reachable if one path fails?', '[{"text":"SAS","is_correct":true},{"text":"SATA","is_correct":false},{"text":"eSATA","is_correct":false},{"text":"mSATA","is_correct":false}]', 0, 'Serial Attached SCSI (SAS) is the server interface: drives connect through SAS host bus adapters or RAID controllers, and enterprise SAS drives have two ports that can be cabled to two controllers for redundancy. SATA, eSATA and mSATA drives have a single port and are aimed at desktops, external enclosures and laptops.', 2),
  ('3.5', 'A customer wants a compact desktop that holds a graphics card, a capture card and a network card, each in its own expansion slot. Which is the smallest motherboard form factor that can do this?', '[{"text":"Mini-ITX","is_correct":false},{"text":"microATX","is_correct":true},{"text":"ATX","is_correct":false},{"text":"E-ATX","is_correct":false}]', 1, 'microATX boards measure up to 9.6 × 9.6 inches and have up to four expansion slots, enough for three cards in a smaller case than ATX needs. Mini-ITX boards (6.7 × 6.7 inches) have a single expansion slot, while ATX (12 × 9.6 inches, up to seven slots) and the even larger E-ATX would fit the cards but need bigger cases.', 2),
  ('3.5', 'A technician wants to move a microATX motherboard into an ATX tower case. What should the technician expect?', '[{"text":"It won''t fit, since microATX boards need a microATX case","is_correct":false},{"text":"It fits only with a riser adapter for the expansion slots","is_correct":false},{"text":"It fits, using the standoffs that match the board''s holes","is_correct":true},{"text":"It fits only after switching to a smaller power supply","is_correct":false}]', 2, 'microATX is a smaller version of ATX with compatible mounting holes, rear I/O placement and power connectors, so it installs in an ATX case on the standoffs that line up with its holes; any extra standoffs should be removed so they can''t short the board. It doesn''t need its own case size, a riser or a different power supply.', 2),
  ('3.5', 'A desktop shuts itself off after about ten minutes, even while sitting at the UEFI setup screen with no operating system loaded. Where can the technician check the CPU temperature and fan speeds without an OS?', '[{"text":"Task Manager''s Performance tab in Windows","is_correct":false},{"text":"Device Manager''s list of processor devices","is_correct":false},{"text":"The POST beep codes heard at startup","is_correct":false},{"text":"The hardware monitor page in UEFI setup","is_correct":true}]', 3, 'UEFI setup includes temperature monitoring, usually on a hardware monitor or PC health page that shows CPU and system temperatures and fan speeds, so heat can be checked with no OS running. Task Manager and Device Manager need Windows to be running, and POST beep codes report startup failures, not temperatures.', 2),
  ('3.5', 'After reinstalling a CPU cooler, a technician sees in the UEFI hardware monitor that the idle CPU is at 95°C and the CPU fan reads 0 RPM. What is the MOST likely cause?', '[{"text":"The CMOS battery is failing and losing settings","is_correct":false},{"text":"The RAM is running in single-channel mode","is_correct":false},{"text":"The cooler''s fan isn''t plugged into CPU_FAN","is_correct":true},{"text":"Secure Boot was turned off during the reinstall","is_correct":false}]', 2, 'A CPU fan reading 0 RPM while the idle CPU sits at 95°C points to a fan that isn''t running, most often because its cable wasn''t plugged back into the CPU_FAN header after the reinstall. A weak CMOS battery loses settings and the clock, single-channel memory lowers performance, and Secure Boot controls which boot loaders run; none of them heats the CPU or stops the fan.', 3),
  ('3.5', 'A school wants to stop students from opening UEFI setup on lab PCs and changing settings such as the boot order. The PCs must still start Windows without anyone typing a password. What should the technician configure?', '[{"text":"A BIOS (supervisor) password","is_correct":true},{"text":"A boot (power-on) password","is_correct":false},{"text":"Secure Boot","is_correct":false},{"text":"TPM security features in UEFI setup","is_correct":false}]', 0, 'A BIOS password, also called a supervisor or setup password, is required to change firmware settings, so students can''t alter the boot order, while the PCs still start normally. A boot password would stop every startup until someone types it, Secure Boot only blocks unsigned boot loaders without locking settings, and the TPM stores keys and measurements rather than protecting setup.', 2),
  ('3.5', 'A technician is authorized to reset a desktop PC whose BIOS password nobody remembers. On most desktop motherboards, which method clears it?', '[{"text":"Reinstall Windows from a USB drive","is_correct":false},{"text":"Update the graphics driver from the vendor","is_correct":false},{"text":"Boot into Safe Mode and reset the password","is_correct":false},{"text":"Use the board''s clear-CMOS or password jumper","is_correct":true}]', 3, 'Most desktop boards clear a forgotten BIOS password by clearing the CMOS settings with a jumper (or button), and some business models have a separate password jumper; either is used with the power cord unplugged, as the manual describes, and the firmware settings then need to be set again. Reinstalling Windows, updating a driver and Safe Mode all work inside the OS and can''t change a firmware password. Many laptops keep the password in secure memory and need the manufacturer''s process instead.', 2),
  ('3.6', 'A PC''s components draw 450 W from a power supply that is 90% efficient at that load. About how much power does the power supply draw from the wall outlet?', '[{"text":"500 W","is_correct":true},{"text":"495 W","is_correct":false},{"text":"450 W","is_correct":false},{"text":"405 W","is_correct":false}]', 0, 'Efficiency is output divided by input, so the input is 450 W ÷ 0.9 = 500 W, and the other 50 W is lost as heat inside the power supply. 495 W adds only 10% of the output, which understates the loss; 450 W ignores the loss; and 405 W subtracts 10% when the input must be more than the output.', 2),
  ('3.6', 'A PC draws about 300 W under its usual load, and the technician is choosing between 80 PLUS Gold power supplies. Which rating keeps the power supply nearest its most efficient range while leaving headroom?', '[{"text":"350 W","is_correct":false},{"text":"600 W","is_correct":true},{"text":"1,200 W","is_correct":false},{"text":"1,600 W","is_correct":false}]', 1, 'Power supply efficiency peaks around half load, which is one reason 80 PLUS tests at 20%, 50% and 100%: a 600 W unit at about 300 W runs near 50% with room for spikes. A 350 W unit runs close to its limit with little headroom, while 1,200 W and 1,600 W units would run at about a quarter or less of their rating, where efficiency falls off.', 3),
  ('3.7', 'A printer manufacturer publishes a security bulletin about a flaw in the printer''s built-in web management page and releases a fix. What should the technician update?', '[{"text":"The printer driver on every PC","is_correct":false},{"text":"The printer''s firmware","is_correct":true},{"text":"The print server''s operating system","is_correct":false},{"text":"The web browser on every PC","is_correct":false}]', 1, 'The web management page runs on the printer itself, so the fix comes as a firmware update: the software stored on the device, installed from the manufacturer through the printer''s web page, a USB drive or a management tool. Drivers run on the PCs and only prepare print jobs, the print server''s OS doesn''t run the printer''s web page, and browser updates don''t change the code running on the printer.', 2),
  ('3.7', 'A company''s mail service now requires TLS 1.2 for sending. Since the change, an older multifunction printer can''t send scan-to-email messages, while PCs send mail normally. The printer''s settings offer no TLS 1.2 option. What should the technician do?', '[{"text":"Install a newer printer driver on the PCs","is_correct":false},{"text":"Set the printer''s scan resolution to 300 dpi","is_correct":false},{"text":"Send scan-to-email on port 25 without encryption","is_correct":false},{"text":"Update the printer''s firmware to add TLS 1.2","is_correct":true}]', 3, 'Scan-to-email runs on the printer itself, so the printer''s firmware is what needs TLS 1.2 support; manufacturers added it to many older models through firmware updates. PC drivers play no part in scan-to-email, scan resolution has nothing to do with encryption, and a service that requires TLS 1.2 would refuse an unencrypted connection.', 3),
  ('3.7', 'A design studio''s PDFs, full of complex vector artwork and embedded fonts, print with misplaced shapes and substituted fonts through the printer''s PCL driver. The printer also supports PostScript. What should the technician do?', '[{"text":"Install an older PCL 5 driver","is_correct":false},{"text":"Install the printer''s PostScript driver","is_correct":true},{"text":"Switch to a generic text-only driver","is_correct":false},{"text":"Set the print quality to draft mode","is_correct":false}]', 1, 'PostScript describes each page in a device-independent way and renders complex graphics and fonts precisely, which makes it the usual choice for design and publishing work; PCL is efficient for everyday office printing, but complex artwork can come out differently from one printer to another. An older PCL version doesn''t fix the rendering, a generic text-only driver drops graphics and fonts altogether, and draft quality only lowers resolution.', 2),
  ('3.8', 'A dot matrix printer prints four-part carbonless invoices. The top copy is dark and clear, but the bottom copy is too faint to read. What should the technician do FIRST?', '[{"text":"Replace the laser printer''s toner cartridge","is_correct":false},{"text":"Set the head gap lever for four-part forms","is_correct":true},{"text":"Clean the thermal printer''s heating element","is_correct":false},{"text":"Replace the impact printer''s ribbon","is_correct":false}]', 1, 'Impact printers make the copies by striking through every layer of multipart paper, so the print head gap, set with the paper thickness lever, has to match the form; when it doesn''t, the strike can be too weak to mark the lower copies. Toner belongs to laser printers and a heating element to thermal printers. A worn ribbon fades the top copy, which is printing well here.', 2),
  ('3.8', 'On a warehouse''s impact printer, the top sheet of the multipart delivery forms has grown steadily lighter over the past month, while the copies beneath it are as clear as ever. Which maintenance should the technician perform?', '[{"text":"Replace the ribbon","is_correct":true},{"text":"Apply a laser maintenance kit","is_correct":false},{"text":"Replace the special thermal paper","is_correct":false},{"text":"Calibrate the inkjet printheads","is_correct":false}]', 0, 'The top sheet of a multipart form gets its ink from the printer''s ribbon, while the copies beneath are made by the pressure of the print head through the layers. A top sheet that fades gradually while the copies stay clear means the ribbon is running dry, so replace it. Maintenance kits are for laser printers, thermal paper is for thermal printers, and impact printers have no inkjet printheads.', 2),
  ('3.8', 'A busy office''s laser printer displays ''Perform printer maintenance'' after printing about 200,000 pages. Print quality is still acceptable. What should the technician do?', '[{"text":"Replace the toner and ignore the message","is_correct":false},{"text":"Clean the printheads with the printer''s utility","is_correct":false},{"text":"Replace the ribbon and adjust the head gap","is_correct":false},{"text":"Install the maintenance kit and reset the counter","is_correct":true}]', 3, 'Laser printers count pages and ask for maintenance at a set interval; the manufacturer''s maintenance kit replaces wear parts such as the fuser and the feed, pickup and transfer rollers, and resetting the page counter clears the message until the next interval. A new toner cartridge doesn''t replace those parts, and printheads and ribbons belong to inkjet and impact printers.', 2),
  ('3.8', 'While replacing a laser printer''s toner cartridge, a technician spills toner inside the printer. How should the technician clean it up?', '[{"text":"Blow it out with compressed air","is_correct":false},{"text":"Use a vacuum made to capture toner","is_correct":true},{"text":"Use a standard household vacuum","is_correct":false},{"text":"Wipe it up with a soaking wet cloth","is_correct":false}]', 1, 'Toner is an extremely fine powder, so spills are cleaned with a toner vacuum, whose filter traps particles that small, and small traces with a dry, lint-free cloth. Compressed air spreads toner through the printer and into the room, a household vacuum''s filter lets the fine particles straight back into the air, and a wet cloth turns the toner into a smeary paste and puts moisture inside the printer.', 2),
  ('3.8', 'An inkjet printer that sat unused for two months now prints pages with thin white streaks, and its nozzle check pattern shows gaps in the black and cyan lines. The cartridges are new. What should the technician do FIRST?', '[{"text":"Replace the fuser assembly","is_correct":false},{"text":"Apply a laser maintenance kit","is_correct":false},{"text":"Replace the printer''s feed rollers","is_correct":false},{"text":"Run the printhead cleaning utility","is_correct":true}]', 3, 'Ink dries in the printhead nozzles when an inkjet printer sits unused, and the gaps in the nozzle check show which ones are clogged; the built-in cleaning cycle flushes ink through them, and another nozzle check confirms the fix. A fuser and a maintenance kit belong to laser printers, and feed rollers move paper rather than putting ink on it.', 2),
  ('3.8', 'An inkjet printer often fails to pick up paper from its tray and sometimes pulls in two sheets at once. The paper is the right type and loaded correctly, and the rubber feed rollers look shiny and dusty. What should the technician do?', '[{"text":"Run the printhead alignment utility","is_correct":false},{"text":"Clean the feed rollers as the manufacturer directs","is_correct":true},{"text":"Replace both ink cartridges with new ones","is_correct":false},{"text":"Set the paper thickness lever for multipart forms","is_correct":false}]', 1, 'Feed rollers grip each sheet by friction, and paper dust and glazing make them slip, so pages fail to feed or go through together. Cleaning them, typically with a lint-free cloth lightly dampened with water as the manufacturer directs, or replacing them if they''re worn, restores the grip. Printhead alignment and new cartridges affect print quality, not paper handling, and the paper thickness lever for multipart forms is on impact printers.', 2),
  ('3.8', 'A receipt printer that uses direct thermal paper prints a thin, blank vertical line through every receipt. The paper roll is new and loaded correctly. What should the technician do?', '[{"text":"Clean the heating element with isopropyl alcohol","is_correct":true},{"text":"Replace the printer''s ink ribbon with a new roll","is_correct":false},{"text":"Replace the toner cartridge and print a test page","is_correct":false},{"text":"Run an inkjet nozzle check, then a cleaning cycle","is_correct":false}]', 0, 'A direct thermal printer marks the paper with a row of tiny heating dots, and residue or debris on that heating element keeps some of them from touching the paper, which leaves a blank line. Cleaning the cooled element with isopropyl alcohol, using a cleaning pen or swab, and removing debris is routine thermal printer maintenance; if the line stays, a dot may have burned out. Direct thermal printers use no ribbon, toner or ink.', 2),
  ('3.8', 'A direct thermal label printer has started feeding labels crookedly and jamming, and print is patchy along one edge. The technician finds adhesive residue and paper dust built up on the platen roller. What should the technician do?', '[{"text":"Install a wider ribbon for the labels","is_correct":false},{"text":"Apply the laser printer maintenance kit","is_correct":false},{"text":"Clean the platen roller and remove the debris","is_correct":true},{"text":"Switch to a higher-quality inkjet label stock","is_correct":false}]', 2, 'The platen roller is part of a thermal printer''s feed assembly: it pulls the media through and presses it against the heating element, so adhesive and dust on it cause skewed feeding, jams and uneven print. Cleaning it with the manufacturer''s recommended cleaner, usually isopropyl alcohol, and removing the debris is routine thermal printer maintenance. Direct thermal printers use no ribbon, maintenance kits are for laser printers, and inkjet label stock isn''t made for thermal printing.', 2),
  ('3.8', 'Every line printed by a dot matrix printer has a thin horizontal gap at the same height, even after the technician installed a new ribbon and cleaned the print head. What should the technician do?', '[{"text":"Load a different brand of multipart paper","is_correct":false},{"text":"Set the paper thickness lever to a thinner setting","is_correct":false},{"text":"Clean the platen with isopropyl alcohol","is_correct":false},{"text":"Replace the print head","is_correct":true}]', 3, 'Each pin in a dot matrix print head prints one row of dots, so a gap at the same height in every line means one pin isn''t firing; with a new ribbon and a clean head, the head itself has failed and needs replacing. Different paper doesn''t bring back a missing row of dots, the thickness lever changes how hard every pin strikes rather than one, and the platen only supports the paper.', 2),
  ('4.1', 'Which statement BEST describes a container?', '[{"text":"A full virtual computer that runs its own guest OS","is_correct":false},{"text":"A physical server dedicated to running a single app","is_correct":false},{"text":"An isolated app package sharing the host''s kernel","is_correct":true},{"text":"A desktop streamed to users from the data center","is_correct":false}]', 2, 'A container bundles an application with the libraries and settings it needs and runs it isolated from other containers, but all containers on a host share the host operating system''s kernel, so they''re small and start in seconds. A virtual machine runs its own complete guest OS, a dedicated physical server isn''t virtualized at all, and a desktop streamed from a data center is virtual desktop infrastructure (VDI).', 1),
  ('4.1', 'A developer wants an application, with exactly the same library versions, to run identically on a laptop, a test server and a cloud host, start in seconds, and not need a separate guest OS for each copy. Which technology fits BEST?', '[{"text":"Type 1 hypervisor virtual machines","is_correct":false},{"text":"Containers","is_correct":true},{"text":"Virtual desktop infrastructure","is_correct":false},{"text":"A dual-boot installation","is_correct":false}]', 1, 'A container image packages the application with its exact dependencies, so it runs the same anywhere a container engine is installed, and containers start in seconds because they share the host''s kernel instead of booting their own OS. Virtual machines each need a full guest OS, VDI delivers whole desktops to users, and dual booting only chooses which OS starts.', 2),
  ('4.1', 'A technician tries to run a Windows container on a Linux server''s container engine, and it won''t start. Linux containers on the same server run fine. Why?', '[{"text":"Containers can only run on public cloud servers","is_correct":false},{"text":"The server needs a Type 2 hypervisor first","is_correct":false},{"text":"The Linux server''s TPM must be cleared to run it","is_correct":false},{"text":"It uses the host''s kernel, and this host runs Linux","is_correct":true}]', 3, 'Containers don''t carry their own kernel; they use the host''s, so a Windows container needs a Windows host and a Linux container needs a Linux kernel. (Docker Desktop runs Linux containers on Windows by running a lightweight Linux VM behind the scenes.) Containers run on laptops and on-premises servers as well as in the cloud, a Type 2 hypervisor isn''t what runs containers, and the TPM has nothing to do with it.', 3),
  ('4.1', 'After installing VMware ESXi on a new server, a technician sees only a basic console screen showing the host''s IP address, with no desktop. How are virtual machines typically created and managed on this Type 1 hypervisor?', '[{"text":"From a web browser or management console on another computer","is_correct":true},{"text":"From a desktop OS installed on top of ESXi first","is_correct":false},{"text":"By installing VirtualBox on the server to create them","is_correct":false},{"text":"Only from the server''s console, using a keyboard and mouse","is_correct":false}]', 0, 'A Type 1 hypervisor like ESXi runs directly on the hardware with no general-purpose desktop; its console mainly shows the host''s address and basic settings, and VMs are created and managed remotely, through a web browser or a management console. Installing a desktop OS on top would defeat the point of a bare-metal hypervisor, VirtualBox is a Type 2 hypervisor that needs a host OS, and the local console can''t build VMs.', 2),
  ('4.1', 'A technician installs a Type 1 hypervisor on an older desktop to build a test lab, but the installer stops with ''no network adapters found,'' even though the onboard network card works in Windows. What is the MOST likely reason?', '[{"text":"Type 1 hypervisors can''t use network adapters","is_correct":false},{"text":"The hypervisor has no driver for that network card","is_correct":true},{"text":"The network card must be disabled in UEFI first","is_correct":false},{"text":"Windows must stay installed to supply the driver","is_correct":false}]', 1, 'A Type 1 hypervisor runs directly on the hardware, so it has to bring its own drivers, and many support only the hardware on their vendor''s compatibility list; a consumer network chip that works in Windows may have no driver in the hypervisor. Check the compatibility list or add a supported network card. Type 1 hypervisors certainly use network adapters, disabling the card hides it completely, and it''s Type 2 hypervisors that rely on a host OS and its drivers.', 3),
  ('4.1', 'Whenever the operating system on a developer''s laptop crashes, all of the virtual machines running on the laptop stop too. What explains this?', '[{"text":"The VMs all share a single guest OS kernel","is_correct":false},{"text":"The VM files are stored on a separate drive","is_correct":false},{"text":"A Type 2 hypervisor depends on the host OS","is_correct":true},{"text":"A Type 1 hypervisor has no host OS to depend on","is_correct":false}]', 2, 'A Type 2 hypervisor runs as an application on the host operating system, so when that OS crashes, the hypervisor and every VM it runs stop with it. A Type 1 hypervisor doesn''t depend on a general-purpose host OS, so it doesn''t explain what happened; each VM has its own guest kernel rather than a shared one; and where the VM files are stored doesn''t make the VMs stop.', 2),
  ('4.2', 'A company''s cloud bill jumped after customers began downloading large training videos that the company stores with its public cloud provider. The amount of data stored hasn''t changed. Which charge MOST likely grew?', '[{"text":"Ingress charges for data uploaded into the cloud","is_correct":false},{"text":"Charges for running on a dedicated host","is_correct":false},{"text":"Multitenancy fees for sharing hardware","is_correct":false},{"text":"Egress charges for data leaving the cloud","is_correct":true}]', 3, 'Cloud providers meter data transfer, and data leaving the cloud for the internet (egress) is usually billed per gigabyte, so more downloads mean a bigger bill even though storage hasn''t grown. Data coming in (ingress) is typically free, nothing in the scenario adds a dedicated host, and providers don''t bill a separate fee for multitenancy.', 2),
  ('4.2', 'A company keeps its backups in a public cloud provider''s storage service. Every night it uploads 200 GB, and twice a month it downloads about 50 GB to the office to test restores. Under typical public cloud pricing, which transfers add data transfer charges to the bill?', '[{"text":"Only the restore downloads to the office","is_correct":true},{"text":"Only the nightly uploads","is_correct":false},{"text":"Both, at the same rate per gigabyte","is_correct":false},{"text":"Neither, because cloud data transfer is always free","is_correct":false}]', 0, 'Providers meter traffic in both directions but typically bill for egress, data leaving the cloud, while ingress, data coming in, is free. So the restore downloads add transfer charges and the nightly uploads don''t. The two directions aren''t usually priced the same, and egress is far from free.', 2),
  ('4.2', 'A company''s Microsoft 365 admin center refers to the organization''s ''tenant.'' Which cloud characteristic does this term reflect?', '[{"text":"Elasticity","is_correct":false},{"text":"Dedicated resources","is_correct":false},{"text":"Multitenancy","is_correct":true},{"text":"File synchronization","is_correct":false}]', 2, 'In a multitenant service, one provider''s infrastructure and software serve many customers, called tenants, and each tenant''s users, data and settings are kept logically separate from every other tenant''s. Elasticity is scaling with demand, dedicated resources would mean hardware used by one customer only, and file synchronization keeps copies of files the same across devices.', 2),
  ('4.2', 'A company''s compliance rules and a per-server software license require that its cloud VMs never run on the same physical servers as other customers'' VMs. What should the company request from the provider?', '[{"text":"Shared resources in a public cloud","is_correct":false},{"text":"Dedicated resources, such as a dedicated host","is_correct":true},{"text":"Elasticity, so the VMs can scale with demand","is_correct":false},{"text":"Metered utilization with limits on egress traffic","is_correct":false}]', 1, 'Dedicated resources set physical hardware, such as a dedicated host, aside for one customer, which satisfies rules against sharing servers with other customers and suits licenses counted per physical server. Shared resources put many customers on the same hardware, which is exactly what the rules forbid, and elasticity and metered utilization describe scaling and billing, not isolation.', 2),
  ('4.2', 'Which is a typical trade-off of choosing dedicated resources instead of shared resources in a public cloud?', '[{"text":"Lower cost, since no one else shares the hardware","is_correct":false},{"text":"No ability to run virtual machines on it","is_correct":false},{"text":"No way to encrypt the data stored on it","is_correct":false},{"text":"Higher cost for hardware no other customer uses","is_correct":true}]', 3, 'Shared resources spread the cost of hardware across many customers, which makes them cheaper; dedicated resources reserve hardware for one customer, which costs more but gives physical isolation. Dedicated hosts still run virtual machines, and encryption is available either way.', 2),
  ('5.1', 'A Mac restarts on its own, and after it starts up again it shows the message ''Your computer restarted because of a problem.'' What happened?', '[{"text":"macOS had a kernel panic and restarted to recover","is_correct":true},{"text":"An app stopped responding and showed the spinning wait cursor","is_correct":false},{"text":"The Mac failed its power-on self-test","is_correct":false},{"text":"A scheduled software update installed overnight","is_correct":false}]', 0, 'That message is how macOS reports a kernel panic, a crash in the core of the operating system serious enough to force a restart; repeated panics point to faulty or newly added hardware, a peripheral, or incompatible software. A spinning wait cursor means one app is busy or hung, not a system crash; a failed self-test stops the Mac before macOS loads; and an update doesn''t report a problem.', 2),
  ('5.1', 'A Windows PC showed a full-screen stop error (''Your device ran into a problem and needs to restart'') and restarted before the user could note the stop code. Where can the technician find the code?', '[{"text":"Device Manager","is_correct":false},{"text":"Task Manager''s Startup tab","is_correct":false},{"text":"The System log in Event Viewer","is_correct":true},{"text":"The boot order menu in UEFI firmware setup","is_correct":false}]', 2, 'When Windows starts again after a stop error, it records a BugCheck event with the stop code in the System log, and it saves a memory dump for deeper analysis. The stop error screen is blue on Windows 10 and black on current Windows 11 versions. Device Manager lists hardware, Task Manager''s Startup tab manages startup apps, and the boot order menu chooses boot devices; none of them records the stop code.', 2),
  ('5.1', 'On a Mac, one app shows the spinning rainbow wait cursor and won''t respond, but other apps work normally. What should the technician do FIRST?', '[{"text":"Reinstall macOS using macOS Recovery","is_correct":false},{"text":"Force quit the app (Command-Option-Esc)","is_correct":true},{"text":"Run Apple Diagnostics on the memory","is_correct":false},{"text":"Reset the Mac''s firmware password first","is_correct":false}]', 1, 'The spinning wait cursor, often called the pinwheel, means an app is busy or hung, not that macOS has crashed; since the rest of the system responds, force quitting that app comes first. Reinstalling macOS and running hardware diagnostics are steps for system-wide problems, not one hung app, and the firmware password has nothing to do with an app freezing.', 1),
  ('5.2', 'After a firmware update reset a workstation''s UEFI settings to their defaults, it reports ''no bootable device.'' Its two drives formed a RAID 1 array on the motherboard''s RAID controller, and setup now lists them as two separate disks with no array. What should the technician do?', '[{"text":"Create a new RAID 1 array from the two disks","is_correct":false},{"text":"Replace both drives with new ones","is_correct":false},{"text":"Replace the CMOS battery on the board","is_correct":false},{"text":"Set the SATA mode back from AHCI to RAID","is_correct":true}]', 3, 'Resetting UEFI to defaults often switches the SATA controller from RAID mode to AHCI, which hides the array and shows its members as plain disks. Setting the mode back to RAID brings back the existing array with its data. Creating a new array can overwrite the data, the drives haven''t failed, and the settings were reset by the update, not by a failing battery.', 3),
  ('5.2', 'A server''s RAID controller failed. After the technician installs an identical replacement, the RAID 5 array is missing, and the controller''s setup utility reports a ''foreign configuration'' on all of the drives. What should the technician do?', '[{"text":"Import the foreign configuration","is_correct":true},{"text":"Clear the foreign configuration and create a new array","is_correct":false},{"text":"Initialize the drives so the controller can use them","is_correct":false},{"text":"Remove one drive at a time to force a rebuild","is_correct":false}]', 0, 'The array''s layout is stored on the drives themselves, and a new controller sees it as a foreign configuration; importing it rebuilds the array definition from that metadata with the data intact. Clearing the configuration and creating a new array, or initializing the drives, wipes the layout and can destroy the data, and pulling drives would degrade a healthy array.', 3),
  ('5.2', 'A file server starts emitting a continuous, high-pitched beep. The operating system is still running, and the RAID management utility shows the virtual disk as degraded. What is making the sound, and what should the technician do next?', '[{"text":"The motherboard''s POST speaker; reseat RAM","is_correct":false},{"text":"The RAID controller; replace the failed drive","is_correct":true},{"text":"The power supply; replace its failing fan","is_correct":false},{"text":"The UPS; check whether the power went out","is_correct":false}]', 1, 'Many hardware RAID controllers, like many NAS units, sound an audible alarm when an array becomes degraded. With the utility showing a degraded virtual disk, the next step is to identify the failed drive from the utility or its status LED, replace it and let the array rebuild. POST beeps come at startup, not while the OS runs, nothing points to the power supply, and a UPS alarm signals power problems, not a degraded disk.', 2),
  ('5.2', 'A NAS in a small office is beeping, and its status page reads ''RAID 5 volume degraded: Disk 3 failed.'' The office manager wants to mute the alarm and replace the disk at next month''s maintenance window. What should the technician advise?', '[{"text":"Waiting is fine, because RAID 5 survives two more failures","is_correct":false},{"text":"Muting the alarm also repairs the volume","is_correct":false},{"text":"The data is already lost, so restore from backup today","is_correct":false},{"text":"Redundancy is gone; replace Disk 3 now and confirm backups","is_correct":true}]', 3, 'A degraded RAID 5 volume still works but has lost its only redundancy, so one more disk failure would destroy it; the alarm is a warning to replace the failed disk promptly and make sure backups are current. RAID 5 tolerates just one failed disk, muting stops the sound without repairing anything, and the data is still intact while the volume is degraded.', 2),
  ('5.3', 'A technician connects a PC to a large TV over HDMI for a conference room. The edges of the desktop, including the taskbar, are cut off. What should the technician do?', '[{"text":"Replace the HDMI cable with a longer, thicker one","is_correct":false},{"text":"Lower the refresh rate to 30 Hz","is_correct":false},{"text":"Turn off overscan in the TV''s settings","is_correct":true},{"text":"Rotate the display orientation to portrait","is_correct":false}]', 2, 'Many TVs overscan by default, enlarging the picture slightly so its edges fall outside the screen, which crops a computer''s desktop. Setting the TV''s picture size to its full-pixel mode (names include Just Scan, Screen Fit and PC mode), or adjusting scaling in the graphics driver, shows the whole image. A different cable, a lower refresh rate or portrait orientation doesn''t change how the TV scales the picture.', 2),
  ('5.3', 'A user works with a laptop and an external monitor side by side. App windows and text look much larger on the laptop screen than on the monitor, which makes dragging windows between them awkward. Both run at their native resolutions. What should the technician adjust?', '[{"text":"Each display''s Scale setting in Windows","is_correct":true},{"text":"The external monitor''s refresh rate","is_correct":false},{"text":"The laptop screen''s color profile","is_correct":false},{"text":"Both displays'' resolution, set to 1024×768","is_correct":false}]', 0, 'Windows sets display scaling (Scale, as a percentage) separately for each display, so one screen can draw items much larger than another. Adjusting each display''s Scale until items look about the same size fixes it. Refresh rate and color profile don''t change size, and dropping both displays to 1024×768 makes everything blurry and out of proportion on widescreen panels.', 2),
  ('5.3', 'During 3D games, a PC''s display breaks up into colored blocks and checkerboard patterns after 10 to 15 minutes, getting worse as the graphics card''s temperature climbs. The desktop looks normal. What is the MOST likely cause?', '[{"text":"The screen resolution doesn''t match the monitor''s native one","is_correct":false},{"text":"The graphics card is overheating or its memory is failing","is_correct":true},{"text":"The monitor has developed burn-in from the game''s interface","is_correct":false},{"text":"The monitor''s power cable has worked loose from its socket","is_correct":false}]', 1, 'Distortion that appears only under 3D load and worsens as the graphics card heats up points to the card itself: usually overheating from clogged fans or heat sinks, or failing video memory. Check its cooling and temperatures, and replace the card if the artifacts continue. A wrong resolution or burn-in would show on the desktop too and wouldn''t track temperature, and a loose power cable turns a monitor off rather than drawing colored blocks.', 2),
  ('5.3', 'After a laptop was closed on a pen, a warped, rainbow-colored patch appears in the same spot on its screen whatever is displayed. An external monitor connected to the laptop shows a clean image. What should the technician do?', '[{"text":"Update the laptop''s graphics driver","is_correct":false},{"text":"Lower the laptop''s screen resolution","is_correct":false},{"text":"Replace the laptop''s LCD panel","is_correct":true},{"text":"Degauss the laptop''s display","is_correct":false}]', 2, 'Pressure from the pen damaged the LCD''s layers, which leaves a distorted, discolored patch that stays in one place whatever is on screen. The clean image on the external monitor shows the graphics hardware and driver are fine, so the panel needs replacing. A driver update or a lower resolution can''t repair physical damage, and degaussing was for CRT monitors, not LCDs.', 2),
  ('5.4', 'A user tries to install a 2 GB game on a phone and gets a message that there isn''t enough storage. What should the technician suggest FIRST?', '[{"text":"Factory reset the phone to clear old files","is_correct":false},{"text":"Turn on airplane mode during the download","is_correct":false},{"text":"Dim the screen while the app installs","is_correct":false},{"text":"Remove unused apps and media to free space","is_correct":true}]', 3, 'The install fails because the phone lacks free storage, so removing or offloading unused apps and moving photos and videos to cloud storage or a computer makes room. A factory reset erases everything and is a last resort, and neither airplane mode nor screen brightness affects storage.', 1),
  ('5.4', 'On a company-managed phone, the app store is missing, and the user can''t install a note-taking app they need for work. The phone is enrolled in MDM. What is the MOST likely reason?', '[{"text":"An MDM restriction blocks public app installs","is_correct":true},{"text":"The phone''s internal storage is full","is_correct":false},{"text":"The phone''s cellular data plan has run out","is_correct":false},{"text":"Low power mode has paused all app downloads","is_correct":false}]', 0, 'MDM policies can hide the app store and block users from installing apps, with approved apps delivered through the company portal instead, so the user should request the app from IT. Full storage shows an out-of-space message rather than removing the store, an exhausted data plan doesn''t make the store disappear, and low power mode can pause background downloads but doesn''t remove the store or block installs.', 2),
  ('5.4', 'A user can''t install a banking app because the app store says it requires a newer version of the operating system. The phone''s settings show that an OS update is available. What should the technician do?', '[{"text":"Download the app''s install file from a website","is_correct":false},{"text":"Install the OS update, then install the app","is_correct":true},{"text":"Clear the app store''s cache","is_correct":false},{"text":"Reset the phone''s network settings","is_correct":false}]', 1, 'The app''s minimum OS requirement is higher than the version on the phone, and an update is available, so installing it lets the app install. Sideloading a banking app from a website is a security risk, and clearing the store''s cache or resetting network settings doesn''t change the OS version.', 2),
  ('5.4', 'A user''s active stylus hasn''t been used for several weeks and now doesn''t respond at all, while finger touch works normally on the tablet. What should the technician check FIRST?', '[{"text":"Whether the digitizer needs replacing","is_correct":false},{"text":"Whether the screen needs touch recalibration","is_correct":false},{"text":"Whether the stylus battery needs charging","is_correct":true},{"text":"Whether the tablet''s storage is full","is_correct":false}]', 2, 'An active stylus has electronics powered by a battery, which drains over weeks of sitting unused, so charging it, or replacing its battery, is the first check. With finger touch working normally, a failed digitizer or bad calibration is much less likely, and storage space has nothing to do with stylus input.', 1),
  ('5.4', 'An iPad user turned off Bluetooth to save battery. Since then their Apple Pencil doesn''t work, although finger touch is fine. What should the technician do?', '[{"text":"Turn Bluetooth back on and reconnect the Pencil","is_correct":true},{"text":"Replace the iPad''s screen and digitizer","is_correct":false},{"text":"Turn on Wi-Fi so the Pencil can reconnect","is_correct":false},{"text":"Reset all of the iPad''s settings to factory defaults","is_correct":false}]', 0, 'Apple Pencil connects to the iPad over Bluetooth, so with Bluetooth off the iPad stops responding to it; turning Bluetooth back on, and pairing again if needed, restores it. Finger touch shows the screen works, Wi-Fi plays no part in the Pencil''s connection, and a full settings reset is unnecessary.', 2),
  ('5.4', 'A user bought an active stylus advertised for a different brand of tablet. It doesn''t work at all on the user''s tablet, although a basic rubber-tipped stylus does. What is the MOST likely cause?', '[{"text":"The tablet''s touch screen is cracked","is_correct":false},{"text":"The tablet needs a screen protector","is_correct":false},{"text":"The rubber-tipped stylus drained the tablet''s battery","is_correct":false},{"text":"Its pen technology isn''t one the tablet supports","is_correct":true}]', 3, 'Active styluses use different pen technologies that mostly aren''t interchangeable, and each works only with screens built for it, so a stylus made for another brand often does nothing at all. A basic rubber-tipped stylus works on any capacitive touch screen, which also shows the screen isn''t damaged. A screen protector doesn''t add pen support, and a passive stylus draws no power.', 2),
  ('5.4', 'An older iPhone has become noticeably slow, especially when opening apps. Its battery health screen reports that performance management has been applied after an unexpected shutdown. What will MOST likely restore its performance?', '[{"text":"Deleting old text messages","is_correct":false},{"text":"Replacing the battery","is_correct":true},{"text":"Turning off location services","is_correct":false},{"text":"Resetting the network settings","is_correct":false}]', 1, 'When a worn battery can''t deliver peak power, iOS applies performance management to prevent unexpected shutdowns, which slows the phone; a new battery removes the need for it. Deleting messages, turning off location services and resetting network settings don''t address the weak battery that is limiting performance.', 2),
  ('5.4', 'A phone runs smoothly at first, but after 20 minutes of gaming in a thick case on a hot day it becomes very warm and the game starts to stutter. What is the MOST likely cause?', '[{"text":"Thermal throttling of the processor","is_correct":true},{"text":"A SIM card that has started to fail","is_correct":false},{"text":"Display burn-in from the game''s controls","is_correct":false},{"text":"An app license that expired mid-game","is_correct":false}]', 0, 'Phones slow their processors when they get hot, to protect the chip and battery, so long gaming sessions in a thick case on a hot day lead to stuttering. Letting the phone cool, removing the case and closing background apps help. A SIM card doesn''t affect processing speed, burn-in is a lasting image on the screen, and an expired license would stop the app rather than slow it.', 2),
  ('5.5', 'After a router upgrade, the office Wi-Fi was set to WPA3-Personal only. Most devices connect, but an older laptop fails to join even with the correct passphrase. Without replacing hardware, what should the technician do?', '[{"text":"Give the laptop a static IP address","is_correct":false},{"text":"Turn off DHCP on the router","is_correct":false},{"text":"Use WPA2/WPA3 transition mode on 2.4 and 5 GHz","is_correct":true},{"text":"Start the laptop in Safe Mode with Networking","is_correct":false}]', 2, 'An older adapter or driver that doesn''t support WPA3 can''t complete WPA3 authentication, however correct the passphrase. WPA2/WPA3 transition mode lets WPA3 devices use WPA3 while older ones still join with WPA2 (6 GHz stays WPA3-only), and a newer Wi-Fi driver may add WPA3 support. A static IP, turning off DHCP and Safe Mode don''t affect authentication.', 2),
  ('5.5', 'At 8:00 a.m., every user on a company''s 802.1X (WPA2-Enterprise) Wi-Fi suddenly fails to authenticate, although the wired network works. The RADIUS server''s log shows its server certificate expired overnight. What should the technician do?', '[{"text":"Move the access points to a different channel","is_correct":false},{"text":"Renew the RADIUS server''s certificate","is_correct":true},{"text":"Reset every user''s password","is_correct":false},{"text":"Increase the DHCP lease time","is_correct":false}]', 1, 'In 802.1X, clients check the RADIUS server''s certificate before sending their credentials, so an expired server certificate makes authentication fail for everyone at once. Renewing it, and making sure clients trust the new one, restores access. A channel change affects interference, not authentication, the users'' passwords are fine, and DHCP only happens after a client has authenticated.', 3),
  ('5.5', 'A user changed their domain password this morning. Since then their account keeps getting locked out, even though they type the new password correctly on their PC. Their phone joins the company''s 802.1X Wi-Fi with their domain credentials. What is the MOST likely cause?', '[{"text":"The PC''s clock is several minutes fast","is_correct":false},{"text":"The access point''s firmware is out of date","is_correct":false},{"text":"The PC''s DNS cache holds a corrupt entry","is_correct":false},{"text":"The phone keeps retrying the old password","is_correct":true}]', 3, 'Devices that saved the old password, like the phone''s Wi-Fi profile, keep trying it automatically, and each failure counts toward the lockout threshold. Updating the password on the phone, or forgetting and rejoining the network, stops the lockouts. A clock that''s off causes sign-in errors rather than lockouts after a password change, AP firmware doesn''t lock accounts, and a DNS cache problem affects name resolution, not the account.', 2),
  ('5.5', 'Users report that the internet drops for a minute or two several times a day, but the internal file server always stays reachable. During a drop, a continuous ping to the default gateway keeps replying while a ping to a public IP address times out. Where is the problem MOST likely?', '[{"text":"The modem or the ISP connection","is_correct":true},{"text":"The network adapters in the users'' PCs","is_correct":false},{"text":"The office''s internal switch","is_correct":false},{"text":"The DNS cache on each PC","is_correct":false}]', 0, 'Replies from the default gateway show that the PCs, cabling and switch reach the router, while pings to a public IP failing at the same moment point beyond it: to the modem, the router''s WAN link or the ISP''s service. Failing adapters or a failing switch would also cut off the file server and gateway, and DNS isn''t involved when pinging an IP address.', 2),
  ('5.5', 'A user says websites sometimes fail to load with ''server not found,'' then work a minute later. During a failure, the technician can ping 8.8.8.8 and the default gateway, but nslookup times out for every name. What is the MOST likely cause?', '[{"text":"A failing network cable","is_correct":false},{"text":"An expired DHCP lease","is_correct":false},{"text":"An unreliable DNS server","is_correct":true},{"text":"A browser cache that is full","is_correct":false}]', 2, 'Pings to an internet IP address work, so the connection itself is up; only name resolution fails, which points to the configured DNS server. Switching to a reliable DNS server, or fixing the current one, solves it. A bad cable or an expired lease would break the pings too, and a browser cache doesn''t stop nslookup from resolving names.', 2),
  ('5.6', 'A technician adds an optional 500-sheet tray to a network printer. The printer''s configuration page lists the new tray, but the Windows print dialog still offers only the original trays. What should the technician do?', '[{"text":"Reseat the tray with the printer off","is_correct":false},{"text":"Update the printer''s IP address","is_correct":false},{"text":"Restart the Print Spooler service","is_correct":false},{"text":"Enable the tray in the driver''s settings","is_correct":true}]', 3, 'The printer detects the tray, so the gap is in Windows: many drivers keep a list of installed accessories, and the tray must be enabled under installable options on the printer properties'' Device Settings tab, or detected with the driver''s automatic configuration. Reseating isn''t needed when the printer already lists the tray, the IP address doesn''t affect tray choices, and restarting the spooler doesn''t change the driver''s accessory settings.', 2),
  ('5.6', 'After an optional paper tray is installed, the printer''s control panel doesn''t show it, and the printer''s configuration page doesn''t list it either. What should the technician check FIRST?', '[{"text":"That the tray is fully seated on its connector","is_correct":true},{"text":"That the tray is enabled in the Windows driver","is_correct":false},{"text":"That the print queue is empty","is_correct":false},{"text":"That the toner cartridge is full","is_correct":false}]', 0, 'If the printer itself doesn''t see the tray, the problem is physical: the tray has to sit fully on its alignment pins and connector, and manufacturers say to install trays with the printer turned off because it checks for them at startup. Driver settings only matter after the printer detects the tray, and the print queue and toner level don''t affect tray detection.', 2),
  ('5.6', 'A user set up a new wireless printer, but no computer in the office can find it. The printer''s configuration page shows it joined the office''s guest Wi-Fi network, which keeps clients isolated from the main network. What should the technician do?', '[{"text":"Connect the printer to the main office Wi-Fi network","is_correct":true},{"text":"Reinstall the printer''s driver on every computer","is_correct":false},{"text":"Turn on client isolation for the main network too","is_correct":false},{"text":"Give the printer a static IP on the guest network","is_correct":false}]', 0, 'Guest networks usually isolate their clients from the main network, so computers on the office network can''t reach a printer on the guest Wi-Fi. Connecting the printer to the main network puts it where the computers can find it. Reinstalling drivers doesn''t change which network the printer is on, client isolation would block the printer on the main network too, and a static address on the guest network is still isolated.', 2),
  ('5.6', 'The office changed its Wi-Fi passphrase yesterday. Today the wireless printer shows as offline on every computer, while the computers, already updated with the new passphrase, work normally. What should the technician do?', '[{"text":"Replace the printer''s wireless network card","is_correct":false},{"text":"Change the printer''s default paper size setting","is_correct":false},{"text":"Reconnect the printer using the new passphrase","is_correct":true},{"text":"Give every computer a static IP address instead","is_correct":false}]', 2, 'The printer is still using the old passphrase, so it can''t join the network. Reconnecting it with the new passphrase from its control panel or setup tool brings it back online. Its network card isn''t faulty, paper size has nothing to do with connectivity, and the computers'' addressing isn''t the problem.', 1),
  ('5.6', 'Everyone in an office prints through a shared queue on a Windows print server, and the queue has frozen for all users. A technician restarts the Print Spooler service on one user''s PC, but nothing changes. What should the technician do next?', '[{"text":"Restart the Print Spooler on every user''s PC","is_correct":false},{"text":"Restart the Print Spooler on the print server","is_correct":true},{"text":"Reinstall the printer driver on the technician''s PC","is_correct":false},{"text":"Power cycle the switch the printer is connected to","is_correct":false}]', 1, 'A shared queue lives on the print server, so that server''s Print Spooler service holds the stuck jobs; restarting it there, and clearing a stuck job if needed, frees the queue for everyone. Restarting the spooler on client PCs only affects their own local queues, a driver on one PC doesn''t control the server''s queue, and the switch isn''t involved when jobs are stuck in a spooler.', 2),
  ('5.6', 'Restarting the Print Spooler service didn''t free a frozen print queue, so the technician will clear the spool folder (C:\Windows\System32\spool\PRINTERS) by hand. In which order should the steps be done?', '[{"text":"Delete the spool files, then stop and start the Print Spooler","is_correct":false},{"text":"Start the Print Spooler, delete the printer, then stop it","is_correct":false},{"text":"Stop the Print Spooler, delete the spool files, then start it","is_correct":true},{"text":"Stop the Print Spooler, reinstall the driver, then reboot","is_correct":false}]', 2, 'The stuck job''s files stay locked while the spooler runs, so the service must be stopped first; then the files in the spool folder can be deleted, and starting the service again brings up an empty queue. Deleting first fails because the files are in use, stopping the service last leaves printing turned off, and reinstalling the driver doesn''t remove the stuck job.', 2)
) as v(code, question_text, options, correct_index, explanation, difficulty)
join cert_sub_objectives n on n.code = v.code
join cert_domains d on d.id = n.domain_id and d.certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101');

-- The 220-1101 objectives, now unused.
delete from cert_sub_objectives s
using cert_domains d
where s.domain_id = d.id and d.certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101') and s.code like 'v14-%';

do $$
begin
  if exists (select 1 from cert_questions where certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101') and is_active and sub_objective_id is null) then
    raise exception '220-1201: an active question has no objective';
  end if;
  if (select count(*) from cert_questions where certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101') and is_active) <> 651 then
    raise exception '220-1201: expected 651 active questions';
  end if;
end $$;

-- Saved paths move to 220-1201: answers follow their question (or recall deck) to
-- its V15 objective, finished learn stops follow their objective, and what left
-- the exam is dropped. migrateAPlusV14Progress does the same to a device's copy.
with objective_map(old_code, new_code) as (values
  ('1.1', '1.1'),
  ('1.2', '3.1'),
  ('1.3', '1.2'),
  ('1.4', '1.3'),
  ('2.1', '2.1'),
  ('2.2', '2.5'),
  ('2.3', '2.2'),
  ('2.4', '2.3'),
  ('2.5', '2.6'),
  ('2.6', '2.4'),
  ('2.7', '2.7'),
  ('2.8', '2.8'),
  ('3.1', '3.2'),
  ('3.2', '3.3'),
  ('3.3', '3.4'),
  ('3.4', '3.5'),
  ('3.5', '3.6'),
  ('3.6', '3.7'),
  ('3.7', '4.2'),
  ('4.1', '4.2'),
  ('4.2', '4.1'),
  ('5.1', null),
  ('5.2', '5.1'),
  ('5.3', '5.2'),
  ('5.4', '5.3'),
  ('5.5', '5.4'),
  ('5.6', '5.6'),
  ('5.7', '5.5')
),
deck_map(deck, new_code) as (values
  ('ports-protocols', '2.1'),
  ('wireless-standards', '2.2'),
  ('cable-types', '3.2'),
  ('storage-types', '3.4'),
  ('motherboard-components', '3.5'),
  ('printer-types', '3.8'),
  ('troubleshooting-steps', null),
  ('subnet', '2.6')
)
update path_progress p
set cert_slug = 'a-plus-core1-220-1201',
  progress = p.progress || jsonb_build_object(
  'items', coalesce((
    select jsonb_object_agg(k.new_key, k.record)
    from (
      select distinct on (n.new_key) n.new_key, n.record
      from (
        select e.value as record, case
          when e.key !~ '^[aqr]\|[^|]+\|.+$' then e.key
          when e.key like 'q|%' then (
            select 'q|' || s.code || '|' || q.id
            from cert_questions q
            join cert_sub_objectives s on s.id = q.sub_objective_id
            where q.certification_id = (select id from certifications where slug = 'a-plus-core1-220-1101') and q.is_active
              and q.id::text = substring(e.key from '^q\|[^|]+\|(.+)$'))
          when e.key like 'r|%' and exists (select 1 from deck_map d where d.deck = split_part(e.key, '|', 3)) then (
            select 'r|' || d.new_code || '|' || substring(e.key from '^r\|[^|]+\|(.+)$')
            from deck_map d where d.deck = split_part(e.key, '|', 3))
          else (
            select left(e.key, 2) || m.new_code || '|' || substring(e.key from '^[aqr]\|[^|]+\|(.+)$')
            from objective_map m where m.old_code = split_part(e.key, '|', 2))
        end as new_key
        from jsonb_each(coalesce(p.progress -> 'items', '{}'::jsonb)) as e
      ) as n
      where n.new_key is not null
      order by n.new_key, (n.record ->> 't')::numeric desc nulls last
    ) as k
  ), '{}'::jsonb),
  'stops', coalesce((
    select jsonb_object_agg(k.new_key, k.record)
    from (
      select distinct on (n.new_key) n.new_key, n.record
      from (
        select e.value as record, case
          when e.key ~ '^\d+\.\d+$' then (select m.new_code from objective_map m where m.old_code = e.key)
          else e.key
        end as new_key
        from jsonb_each(coalesce(p.progress -> 'stops', '{}'::jsonb)) as e
      ) as n
      where n.new_key is not null
      order by n.new_key, (n.record ->> 'at')::numeric desc nulls last
    ) as k
  ), '{}'::jsonb)
)
where p.cert_slug = 'a-plus-core1-220-1101';

