-- New questions for what 220-1202 added.
insert into cert_questions (certification_id, domain_id, sub_objective_id, question_text, options, correct_index, explanation, difficulty, is_active, is_diagnostic_eligible)
select (select id from certifications where slug = 'a-plus-core2-220-1102'), n.domain_id, n.id, v.question_text, v.options::jsonb, v.correct_index, v.explanation, v.difficulty, true, true
from (values
  ('1.1', 'A file server keeps large archives on a Storage Spaces mirror. The administrator wants the file system itself to detect corrupted data with checksums and repair it from the mirror''s good copy while the volume stays online. Which file system should the volume use?', '[{"text":"NTFS","is_correct":false},{"text":"ReFS","is_correct":true},{"text":"exFAT","is_correct":false},{"text":"FAT32","is_correct":false}]', 1, 'ReFS (Resilient File System) keeps checksums, called integrity streams, and on a Storage Spaces mirror or parity space it repairs corrupted data from the other copy without taking the volume offline. NTFS has no checksums on file data, so it can''t detect silent corruption, and exFAT and FAT32 are simple file systems for removable media with no integrity checking or self-repair.', 2),
  ('1.1', 'A technician building a new Windows workstation asks whether the system drive can be formatted with ReFS for its resiliency features. What should the technician be told?', '[{"text":"ReFS can''t be used for the volume Windows boots from; the system drive must use NTFS","is_correct":true},{"text":"ReFS works on the system drive only when BitLocker is turned off","is_correct":false},{"text":"ReFS is supported on the system drive only in Windows 11 Home, which boots from ReFS by default","is_correct":false},{"text":"ReFS must be on the system drive before TPM 2.0 can be enabled","is_correct":false}]', 0, 'Microsoft lists ReFS as not bootable, so Windows itself goes on an NTFS volume, and ReFS suits data volumes such as file shares, backup targets and virtual machine storage. BitLocker works on both NTFS and ReFS, no edition makes ReFS bootable, and the TPM is a hardware security chip that doesn''t depend on any file system.', 2),
  ('1.1', 'A technician wants to format a 256 GB USB flash drive with ReFS to get its integrity checking. What will the technician find?', '[{"text":"ReFS works on the drive, but only with a 4 KB cluster size and a GPT partition table","is_correct":false},{"text":"ReFS formats the drive and also makes it bootable","is_correct":false},{"text":"ReFS isn''t supported on removable media, so the drive should use exFAT or NTFS","is_correct":true},{"text":"ReFS works on the drive only if it uses MBR partitioning","is_correct":false}]', 2, 'Microsoft lists removable media among the things ReFS doesn''t support, along with booting Windows, disk quotas and shrinking a volume. exFAT suits flash drives shared between Windows and macOS, and NTFS adds permissions and journaling for Windows-only use. No cluster size or partition style makes ReFS work on removable drives, and ReFS volumes aren''t bootable.', 2),
  ('1.1', 'A technician installs Red Hat Enterprise Linux 9 with the default storage layout, then checks the file system type of the root volume. Which file system is the technician MOST likely to see?', '[{"text":"ext4","is_correct":false},{"text":"APFS","is_correct":false},{"text":"ReFS","is_correct":false},{"text":"XFS","is_correct":true}]', 3, 'XFS has been the default file system in Red Hat Enterprise Linux since version 7, when it replaced ext4. It''s a 64-bit journaling file system built for large files and volumes. ext4 is still common, for example as Ubuntu''s default, but isn''t RHEL''s; APFS is Apple''s file system for macOS and iOS; and ReFS is a Microsoft file system that Linux installers don''t use.', 1),
  ('1.1', 'A Linux server''s /data volume uses XFS on an LVM logical volume. The administrator has extended the logical volume and now needs the file system to use the new space. Which command should the administrator run while /data is mounted?', '[{"text":"sudo resize2fs /data","is_correct":false},{"text":"sudo fsck.xfs /dev/vg0/data","is_correct":false},{"text":"sudo mkfs.xfs /dev/vg0/data","is_correct":false},{"text":"sudo xfs_growfs /data","is_correct":true}]', 3, 'xfs_growfs grows a mounted XFS file system into space added to its device. Red Hat documents that an XFS file system can be grown but not reduced, so size it with that in mind. resize2fs resizes ext2, ext3 and ext4; fsck.xfs does nothing and exits, because XFS recovers its journal at mount time (xfs_repair is the real repair tool); and mkfs.xfs creates a new, empty file system, which would destroy the data rather than grow it.', 3),
  ('1.1', 'A user connects an external drive that was formatted with XFS on a Linux server to a Windows 11 PC. The drive doesn''t appear in File Explorer, and Disk Management shows its partition with no recognized file system. What is the MOST likely reason?', '[{"text":"The drive must be defragmented before Windows can read it","is_correct":false},{"text":"Windows can''t read XFS on its own, so it doesn''t recognize the volume","is_correct":true},{"text":"XFS drives can be read in Windows only after BitLocker To Go is enabled","is_correct":false},{"text":"The drive is larger than any Windows file system supports","is_correct":false}]', 1, 'Windows natively reads NTFS, ReFS, FAT32 and exFAT, but not Linux file systems such as XFS or ext4 (WSL 2 can mount them, but File Explorer can''t read them by itself). Copy the files off on a Linux system, and use exFAT for drives shared between operating systems. Defragmenting doesn''t change the file system, BitLocker To Go encrypts drives rather than adding file system support, and NTFS handles far larger volumes than an external drive.', 2),
  ('1.2', 'A developer wants one laptop to start either Windows 11 or Ubuntu, choosing at power-on. Windows 11 is already installed and uses the whole drive. Which approach BEST sets this up?', '[{"text":"Shrink the Windows partition, install Ubuntu into the free space, and pick an OS from the boot menu at startup","is_correct":true},{"text":"Install Ubuntu over the Windows partition, then reinstall Windows into a folder inside Ubuntu''s home directory","is_correct":false},{"text":"Convert the drive from GPT to MBR so both operating systems can share a single partition","is_correct":false},{"text":"Run Ubuntu inside Windows Sandbox and set it to launch automatically at sign-in","is_correct":false}]', 0, 'Multiboot keeps each operating system on its own partition and uses a boot menu to choose one at startup. Shrinking the Windows partition frees space for Ubuntu, whose installer sets up the GRUB menu. Installing over Windows would erase it, and an OS can''t be installed into a folder; changing to MBR doesn''t let two operating systems share a partition; and Windows Sandbox runs only a temporary copy of Windows, not Linux.', 2),
  ('1.2', 'A PC was set up to multiboot Linux and Windows 11. After Windows is reinstalled, the PC starts straight into Windows with no boot menu, though the Linux partition is intact. What is the MOST likely cause?', '[{"text":"Windows Setup converted the Linux partition to NTFS during the reinstall","is_correct":false},{"text":"Clearing the TPM during the reinstall deleted the Linux kernel files","is_correct":false},{"text":"Windows Setup made Windows Boot Manager the default boot entry, so the Linux bootloader''s menu no longer loads","is_correct":true},{"text":"Secure Boot was turned off during the reinstall, so the firmware now hides every operating system except Windows","is_correct":false}]', 2, 'Windows Setup installs Windows Boot Manager, makes it the default and doesn''t add entries for other operating systems, so the GRUB menu that offered Linux stops appearing; that''s also why Windows is usually installed first when multibooting. Putting GRUB first in the firmware''s boot order, or repairing GRUB from a live USB, brings the menu back. Windows doesn''t convert other partitions, clearing a TPM erases its keys rather than files on disk, and turning off Secure Boot lets more boot loaders run, not fewer.', 3),
  ('1.2', 'A company ships new laptops straight from the vendor to remote employees. An employee powers one on, connects to Wi-Fi and signs in with a work account, and the laptop then joins the company directory, enrolls in device management and installs its apps with no technician involved. Which installation type is this?', '[{"text":"Zero-touch deployment","is_correct":true},{"text":"Repair installation","is_correct":false},{"text":"Remote network installation","is_correct":false},{"text":"Recovery partition","is_correct":false}]', 0, 'In a zero-touch deployment, devices configure themselves from the cloud when first started, as Windows Autopilot does: the user connects to a network and signs in, and the rest is automated. A repair installation reinstalls Windows over itself to fix problems, a remote network installation boots a PC from a deployment server to install an OS, and a recovery partition restores a device to its factory image.', 2),
  ('1.2', 'An IT manager wants new Windows laptops to be ready for work without building and maintaining a custom image for every model. How do zero-touch services such as Windows Autopilot achieve this?', '[{"text":"They copy a complete disk image to each laptop from a USB drive that a technician carries to every desk in turn","is_correct":false},{"text":"They take the manufacturer''s preinstalled Windows and apply the company''s settings and apps from the cloud","is_correct":true},{"text":"They require each laptop to boot from the network so that a technician can choose the right image","is_correct":false},{"text":"They install Windows on each laptop from a DVD and an answer file prepared for that model","is_correct":false}]', 1, 'Windows Autopilot starts from the manufacturer''s preinstalled Windows and turns it into a business-ready device by applying settings, policies and apps from cloud services, so there''s no custom image per model to maintain. Copying an image from USB, booting from the network to pick an image and installing from DVD all need a technician to handle each device, which is what zero-touch removes.', 2),
  ('1.3', 'Microsoft''s PC Health Check says a three-year-old desktop can''t run Windows 11 because TPM 2.0 isn''t detected. The motherboard manual says the CPU includes a firmware TPM. What should the technician do FIRST?', '[{"text":"Replace the motherboard with one that has a discrete TPM 2.0 chip","is_correct":false},{"text":"Install the 32-bit edition of Windows 11, which doesn''t need a TPM","is_correct":false},{"text":"Turn off Secure Boot in the UEFI settings so that Windows Setup can detect the TPM chip","is_correct":false},{"text":"Turn on the CPU''s firmware TPM (Intel PTT or AMD fTPM) in the UEFI settings","is_correct":true}]', 3, 'Many CPUs include a firmware TPM 2.0 that is often disabled by default; turning on Intel PTT or AMD fTPM in the UEFI settings usually lets the PC pass the TPM check. Replacing the motherboard is unnecessary until that''s ruled out, Windows 11 has no 32-bit edition, and Secure Boot has nothing to do with detecting the TPM (Windows 11 separately requires firmware that is Secure Boot capable).', 2),
  ('1.3', 'Which of the following BEST describes what a Trusted Platform Module (TPM) provides to Windows 11?', '[{"text":"Firmware that replaces the legacy BIOS and starts the operating system from a GPT-partitioned disk","is_correct":false},{"text":"A hidden partition that holds the Windows Recovery Environment and factory image","is_correct":false},{"text":"A hardware chip that generates and protects keys for features such as BitLocker and Windows Hello","is_correct":true},{"text":"A background service that downloads and installs feature updates for Windows","is_correct":false}]', 2, 'A TPM is a secure crypto-processor that creates and protects keys: BitLocker can seal its encryption key to the TPM, and Windows Hello keys are protected by it. Windows 11 requires TPM 2.0. Firmware that replaces the BIOS and boots from GPT disks is UEFI, the recovery environment lives on a recovery partition, and feature updates come from Windows Update.', 1),
  ('1.3', 'A Windows 10 PC fails the Windows 11 compatibility check because its firmware runs in legacy BIOS (CSM) mode and its system disk uses MBR. The firmware supports UEFI. How can the technician fix this while keeping the existing installation and data?', '[{"text":"Switch the firmware to UEFI mode first, and Windows converts the disk to GPT at the next start","is_correct":false},{"text":"Use Disk Management to convert the system disk to a dynamic disk, then upgrade","is_correct":false},{"text":"Reformat the Windows partition as exFAT, which UEFI requires, then restore the data","is_correct":false},{"text":"Run MBR2GPT to convert the system disk to GPT, then switch the firmware to UEFI mode","is_correct":true}]', 3, 'UEFI starts Windows from a GPT disk, and Microsoft''s MBR2GPT tool converts the system disk from MBR to GPT without deleting data; Microsoft notes the firmware must then be switched to UEFI mode for the PC to start. Switching the firmware first leaves an MBR disk that won''t boot in UEFI mode, and Windows doesn''t convert it. A dynamic disk keeps its partition style, and the Windows volume stays NTFS (only the small EFI system partition is FAT32).', 3),
  ('1.3', 'Which firmware requirement must a PC meet to run Windows 11?', '[{"text":"Legacy BIOS with the Compatibility Support Module turned on","is_correct":false},{"text":"UEFI firmware that is Secure Boot capable","is_correct":true},{"text":"Any firmware, provided the system disk uses MBR","is_correct":false},{"text":"Firmware that can start the PC from optical media","is_correct":false}]', 1, 'Microsoft''s Windows 11 requirements list UEFI firmware that is Secure Boot capable, alongside TPM 2.0. Legacy BIOS and CSM mode don''t meet the requirement, MBR is the older partition style that goes with BIOS booting, and starting from optical media isn''t a requirement at all.', 1),
  ('1.3', 'A small accounting firm is buying laptops that must join its Active Directory domain and be managed with Group Policy. Which is the LEAST expensive Windows 11 edition that meets this need?', '[{"text":"Windows 11 Home","is_correct":false},{"text":"Windows 11 Enterprise","is_correct":false},{"text":"Windows 11 Pro","is_correct":true},{"text":"Windows 11 Pro for Workstations","is_correct":false}]', 2, 'Windows 11 Pro can join an Active Directory domain and includes the Local Group Policy Editor (gpedit.msc) and BitLocker. Home can''t join a domain and has no gpedit.msc. Enterprise and Pro for Workstations can also join a domain, but they cost more and add features the firm doesn''t need.', 1),
  ('1.3', 'A video editor''s new workstation has 256 GB of RAM. Which Windows 11 edition would leave about half of that memory unused?', '[{"text":"Windows 11 Home","is_correct":true},{"text":"Windows 11 Pro","is_correct":false},{"text":"Windows 11 Enterprise","is_correct":false},{"text":"Windows 11 Pro for Workstations","is_correct":false}]', 0, 'Windows 11 Home supports up to 128 GB of RAM, so half of the 256 GB would go unused. Windows 11 Pro supports up to 2 TB, and Enterprise and Pro for Workstations support up to 6 TB, so all three can use the full 256 GB.', 2),
  ('1.3', 'A home user running Windows 11 Home wants BitLocker, and wants to connect to this PC with Remote Desktop from work. What is the simplest way to get both while keeping their apps and files?', '[{"text":"Do a clean install of Windows 11 Enterprise from a USB drive","is_correct":false},{"text":"Turn on Device encryption, and use Quick Assist whenever a remote connection is needed","is_correct":false},{"text":"Install the Media Feature Pack from Settings > Apps > Optional features","is_correct":false},{"text":"Upgrade to Windows 11 Pro with a Pro product key, an in-place edition upgrade","is_correct":true}]', 3, 'Entering a Pro product key (Settings > System > Activation) upgrades Home to Pro in place, keeping apps and files, and Pro adds BitLocker and the ability to host Remote Desktop sessions. A clean install wipes the PC, and Enterprise is sold through business licensing. Device encryption is a simplified form of drive encryption without BitLocker''s management options, and Quick Assist needs someone at the PC to accept each session. The Media Feature Pack only restores media components to N editions.', 2),
  ('1.3', 'A user in Europe bought a PC with Windows 11 Pro N. Videos won''t play in some apps, and the Camera app reports missing media components. What should the technician do?', '[{"text":"Install the Media Feature Pack from Settings > Apps > Optional features","is_correct":true},{"text":"Reinstall Windows 11 Pro N from the recovery partition","is_correct":false},{"text":"Change the edition to Windows 11 Home, which includes the media components","is_correct":false},{"text":"Run sfc /scannow to restore the missing media files","is_correct":false}]', 0, 'N editions ship without Windows Media Player and related technologies such as Media Foundation and several audio and video codecs, which apps like Camera depend on. Microsoft''s Media Feature Pack, added from Settings > Apps > Optional features, restores them. Reinstalling Pro N gives the same result, going from Pro to Home is a downgrade that loses features and needs a reinstall, and sfc repairs damaged system files but can''t add components the edition never included.', 2),
  ('1.5', 'A technician is working at a shared workstation and isn''t sure which account an open command prompt is running as. Which command displays the current domain and user name?', '[{"text":"hostname","is_correct":false},{"text":"whoami","is_correct":true},{"text":"net use","is_correct":false},{"text":"winver","is_correct":false}]', 1, 'whoami shows the domain and user name of the account the prompt runs as, such as CORP\jsmith. hostname shows the computer''s name, net use lists or connects mapped network drives, and winver shows the Windows version and build.', 1),
  ('1.5', 'A user says a share still denies access, though IT added them to the Finance group an hour ago. Which command shows the groups in the user''s current sign-in token, so the technician can see whether Finance is there yet?', '[{"text":"gpupdate /force","is_correct":false},{"text":"whoami /upn","is_correct":false},{"text":"whoami /groups","is_correct":true},{"text":"net user /domain","is_correct":false}]', 2, 'whoami /groups lists the groups in the current access token. A new group membership reaches the token only when the user signs in again, so if Finance is missing, the user should sign out and back in. gpupdate /force refreshes Group Policy but doesn''t show or refresh group membership, whoami /upn shows only the user principal name, and net user /domain lists the domain''s user accounts.', 2),
  ('1.8', 'A Mac app keeps crashing for one user, and the vendor says to delete the app''s preference file for that user only. In which folder should the technician look?', '[{"text":"/Library/Preferences","is_correct":false},{"text":"/Users/<username>/Library/Preferences","is_correct":true},{"text":"/System/Library/Preferences","is_correct":false},{"text":"/Applications/Utilities","is_correct":false}]', 1, 'Each user''s own settings live in the Library folder inside their home folder (/Users/<username>/Library, also written ~/Library), which Finder hides; hold Option and choose Go > Library to open it. /Library holds resources shared by every user on the Mac, /System holds macOS itself on a read-only system volume, and /Applications/Utilities holds tools such as Terminal and Disk Utility.', 2),
  ('1.8', 'Malware on a Mac running a current version of macOS tries to replace files in the /System folder. Why does this fail, even when the malware has an administrator''s password?', '[{"text":"/System is on a separate, read-only system volume, kept apart from the volume that holds user data","is_correct":true},{"text":"/System is encrypted by FileVault, which blocks every write to the startup disk while the Mac is running","is_correct":false},{"text":"/System is synced to iCloud Drive, so any changes are rolled back from the cloud","is_correct":false},{"text":"/System is hidden in Finder, so programs can''t find the files inside it","is_correct":false}]', 0, 'Since macOS Catalina, macOS runs from a dedicated read-only system volume that is separate from the data volume holding users'' files, which keeps critical OS files from being overwritten. FileVault encrypts the disk against offline access but doesn''t make files read-only, iCloud Drive syncs user documents rather than system files, and /System isn''t hidden; even a hidden folder can be opened by path.', 2),
  ('1.8', 'A technician checking a MacBook sees the macOS version shown as 13.3.1 (a). What does the letter in parentheses indicate?', '[{"text":"A beta build from Apple''s developer program is installed on this Mac","is_correct":false},{"text":"The Mac is running a release made only for Apple silicon","is_correct":false},{"text":"A Rapid Security Response has been applied on top of macOS 13.3.1","is_correct":true},{"text":"The installation hasn''t been activated with an Apple ID","is_correct":false}]', 2, 'Apple marked Rapid Security Responses with a letter after the version number, its own example being macOS 13.3.1 (a). RSRs, first delivered for iOS 16.4.1 and macOS 13.3.1, installed urgent security fixes between full software updates. Beta builds are labeled as betas, the letter has nothing to do with Apple silicon, and macOS has no activation step.', 2),
  ('1.8', 'After a Rapid Security Response is applied to an iPhone, a user''s banking app starts crashing, and the bank confirms an incompatibility with the response. What can the technician do?', '[{"text":"Download the previous major version of iOS from the App Store and install it over the current one","is_correct":false},{"text":"Turn off Automatic Updates, which uninstalls every update since the phone was set up","is_correct":false},{"text":"Reset the phone''s network settings, which rolls back the most recent security response","is_correct":false},{"text":"Remove the security response in Settings > General > About, returning to the base iOS version","is_correct":true}]', 3, 'Apple let users remove a Rapid Security Response (Settings > General > About > iOS Version > Remove Security Response), returning the device to the base version; the fix could be reinstalled later or arrive with the next standard update. iOS can''t be rolled back to an earlier major version from the App Store, turning off automatic updates only stops future installs, and resetting network settings doesn''t touch installed software. Starting with iOS 26.1 and macOS 26.1, Apple delivers these quick fixes as Background Security Improvements.', 3),
  ('1.8', 'A Mac user wants the files on their Desktop and in their Documents folder to appear on their iPhone and on a second Mac, and new files there to sync automatically. Which setting should the technician turn on?', '[{"text":"Time Machine, backing up the whole Mac to an external drive every hour","is_correct":false},{"text":"Desktop & Documents Folders, under iCloud Drive in System Settings","is_correct":true},{"text":"FileVault, under Privacy & Security in System Settings","is_correct":false},{"text":"AirDrop, set so that everyone nearby can send files","is_correct":false}]', 1, 'Turning on Desktop & Documents Folders (System Settings > [your name] > iCloud > Drive) moves those folders'' files into iCloud Drive and stores new files there automatically, so they appear on every device signed in to the same Apple Account. Time Machine makes backups rather than syncing, FileVault encrypts the startup disk, and AirDrop sends individual files to nearby devices on demand.', 2),
  ('1.8', 'On a user''s iPhone, messages to a coworker who has an iPhone appear in blue bubbles, but messages to a friend with an Android phone appear in green. What explains the difference?', '[{"text":"Blue ones are iMessages sent over the internet between Apple devices; green ones are SMS, MMS or RCS","is_correct":true},{"text":"Blue ones are encrypted with FileVault on both of the phones, while green ones aren''t encrypted at all","is_correct":false},{"text":"Green ones failed to send and are waiting in a queue until the phone retries them","is_correct":false},{"text":"Blue ones are sent through FaceTime, while green ones are relayed through iCloud Drive","is_correct":false}]', 0, 'iMessage is Apple''s messaging service: it works over Wi-Fi or cellular data between Apple devices, shows blue bubbles and is end-to-end encrypted. Messages to other phones go through the carrier as SMS, MMS or RCS and show green. FileVault encrypts a Mac''s disk, not messages; a message that fails shows a red Not Delivered alert rather than a green bubble; and FaceTime is for calls while iCloud Drive stores files.', 1),
  ('1.8', 'A user copies a paragraph on their iPhone and wants to paste it straight into a document on their Mac without emailing it. Which Continuity feature does this?', '[{"text":"Sidecar","is_correct":false},{"text":"Time Machine","is_correct":false},{"text":"Mission Control","is_correct":false},{"text":"Universal Clipboard","is_correct":true}]', 3, 'Universal Clipboard, part of Continuity, lets you copy text, images and other content on one Apple device and paste it on another nearby device signed in to the same Apple Account. Sidecar uses an iPad as a second display for a Mac, Time Machine backs up a Mac, and Mission Control shows all open windows and desktops on one Mac.', 1),
  ('1.8', 'Handoff and Universal Clipboard have stopped working between a user''s iPad and Mac, which are on the same Wi-Fi network. What should the technician check FIRST?', '[{"text":"That FileVault is turned on for the Mac''s startup disk","is_correct":false},{"text":"That the Mac''s firewall is set to block all incoming connections from other devices","is_correct":false},{"text":"That both devices use the same Apple Account, with Bluetooth and Handoff on","is_correct":true},{"text":"That the iPad is set to install security responses automatically","is_correct":false}]', 2, 'Continuity features such as Handoff and Universal Clipboard need both devices near each other, signed in to the same Apple Account, with Bluetooth, Wi-Fi and Handoff turned on. FileVault encryption doesn''t affect Continuity, blocking all incoming connections is more likely to cause problems than fix them, and update settings control how fixes install.', 2),
  ('1.9', 'A Linux workstation''s secondary data partition, /dev/sdb1, reports file system errors after a power cut. What should the technician do before running fsck on it?', '[{"text":"Mount the partition read-write first, so that fsck can save its repairs to the disk","is_correct":false},{"text":"Unmount the partition, so fsck doesn''t repair a file system that is in use","is_correct":true},{"text":"Run du on the partition, so fsck has free space to work with","is_correct":false},{"text":"Delete the partition''s entry from /etc/fstab permanently","is_correct":false}]', 1, 'fsck checks and repairs Linux file systems, and repairing one while it''s mounted and in use can corrupt it further, so unmount it first (umount /dev/sdb1). Mounting it read-write is exactly what to avoid, du only reports how much space files use, and the fstab entry can stay: it controls mounting at boot and the order of boot-time checks.', 2),
  ('1.9', 'In /etc/fstab, the last field is 1 for the root file system, 2 for a local data volume and 0 for a network share. What do these values control?', '[{"text":"Whether and in what order fsck checks each file system at boot, with 0 meaning never","is_correct":true},{"text":"The order in which the file systems are mounted when the system starts up","is_correct":false},{"text":"How many days pass between the automatic backups that the dump command makes of each one","is_correct":false},{"text":"Which file system is given priority for space when the disk is nearly full","is_correct":false}]', 0, 'The sixth fstab field (fs_passno) tells fsck the order of boot-time checks: 1 for the root file system, 2 for other file systems, and 0 for don''t check, which suits network shares. This field doesn''t set the mount order, the fifth field is a dump flag rather than a backup interval, and fstab has no disk-full priority setting.', 3),
  ('1.9', 'A technician plugs a USB drive into a Linux desktop and needs to attach its partition, /dev/sdc1, to the existing empty directory /mnt/usb. Which command does this?', '[{"text":"sudo fsck /dev/sdc1","is_correct":false},{"text":"sudo mkdir /mnt/usb/sdc1","is_correct":false},{"text":"ln -s /dev/sdc1 /mnt/usb","is_correct":false},{"text":"sudo mount /dev/sdc1 /mnt/usb","is_correct":true}]', 3, 'mount attaches a device''s file system to a directory, the mount point, so its files appear under /mnt/usb; umount detaches it. fsck checks a file system for errors, mkdir creates a directory, and ln -s creates a symbolic link; none of them make the drive''s files accessible.', 1),
  ('1.9', 'After adding a line for /dev/sdb1 to /etc/fstab, an administrator wants to test it without rebooting. Which command mounts everything listed in fstab that isn''t already mounted?', '[{"text":"df -h","is_correct":false},{"text":"sudo umount -a","is_correct":false},{"text":"sudo mount -a","is_correct":true},{"text":"sudo fsck -N","is_correct":false}]', 2, 'mount -a mounts all file systems listed in /etc/fstab, except those marked noauto, so a mistake in the new line shows up now instead of at the next boot. df -h reports free space on file systems that are already mounted, umount -a unmounts file systems, and fsck -N only shows what fsck would do without checking anything.', 2),
  ('1.9', 'A technician needs to install the nmap package on a Fedora workstation. Which command should the technician use?', '[{"text":"sudo dnf install nmap","is_correct":true},{"text":"sudo apt install nmap","is_correct":false},{"text":"sudo dpkg -i nmap","is_correct":false},{"text":"rpm --query nmap","is_correct":false}]', 0, 'dnf is the package manager on Fedora and on Red Hat Enterprise Linux 8 and later, and dnf install downloads a package and its dependencies from the configured repositories. apt is the equivalent on Debian and Ubuntu, dpkg -i installs a local .deb file without resolving dependencies, and rpm --query only checks whether a package is installed.', 1),
  ('1.9', 'After a dnf upgrade on a Red Hat Enterprise Linux 9 workstation, a business application stops working. The technician wants to reverse that whole set of package changes. Which command helps?', '[{"text":"sudo dnf autoremove","is_correct":false},{"text":"sudo dnf history undo","is_correct":true},{"text":"dnf check-update","is_correct":false},{"text":"dnf search","is_correct":false}]', 1, 'dnf records every transaction: dnf history lists them, and dnf history undo with a transaction ID reverses its operations, as long as the older package versions are still available. dnf autoremove removes dependencies nothing needs any more, dnf check-update only reports available updates, and dnf search finds packages by keyword.', 2),
  ('1.9', 'A technician used to Windows runs ping 192.168.1.1 on a Linux workstation, and replies keep scrolling long after the fourth one. What should the technician know?', '[{"text":"The router is flooding the workstation with replies, which means the network is under attack","is_correct":false},{"text":"Linux ping needs -n 4 to send four requests, the same option Windows uses","is_correct":false},{"text":"The workstation''s DNS settings are wrong, so ping keeps retrying the address","is_correct":false},{"text":"Linux ping keeps sending until it''s stopped with Ctrl+C; use -c 4 to send only four","is_correct":true}]', 3, 'On Linux, ping runs until it''s interrupted, then prints round-trip and packet-loss statistics; -c sets how many echo requests to send. Windows sends four by default and uses -n for the count, but on Linux -n means show numeric addresses only. Continuous replies are normal rather than an attack, and the command used an IP address, so DNS isn''t involved.', 2),
  ('1.9', 'From a Linux workstation, a technician wants to check whether an internal web server responds, seeing only its HTTP response headers without downloading the page. Which command does this?', '[{"text":"dig intranet.example.com","is_correct":false},{"text":"traceroute intranet.example.com","is_correct":false},{"text":"curl -I http://intranet.example.com","is_correct":true},{"text":"ping -c 1 intranet.example.com","is_correct":false}]', 2, 'curl transfers data to and from URLs, and -I (--head) fetches only the response headers, showing the status code, such as 200 or 404, and server details. dig queries DNS records, traceroute shows the routers along the path, and ping tests reachability with ICMP; none of them talk HTTP to the web server.', 2),
  ('1.9', 'A technician needs to download a vendor''s install script from https://downloads.example.com/tools/setup.sh into the current directory, keeping its file name. The link redirects to a mirror. Which command works?', '[{"text":"curl https://downloads.example.com/tools/setup.sh","is_correct":false},{"text":"curl -I https://downloads.example.com/tools/setup.sh","is_correct":false},{"text":"curl -L -O https://downloads.example.com/tools/setup.sh","is_correct":true},{"text":"sudo dnf install https://downloads.example.com/tools/setup.sh","is_correct":false}]', 2, '-L makes curl follow the redirect to the mirror, and -O saves the file under its remote name, setup.sh. Without -O (or -o), curl prints what it receives to the terminal instead of saving it, and without -L it stops at the redirect. -I fetches headers only, and dnf installs RPM packages, not shell scripts. Read a downloaded script before running it.', 2),
  ('1.9', 'Users report that a cloud application is slow. Which command, run on a Linux workstation, shows each router between the workstation and the application''s server, with the response time at each hop?', '[{"text":"ping -c 4 app.example.com","is_correct":false},{"text":"traceroute app.example.com","is_correct":true},{"text":"dig app.example.com","is_correct":false},{"text":"ip route show","is_correct":false}]', 1, 'traceroute lists each router (hop) on the path to the destination with round-trip times, so you can see where delay begins. ping reports round-trip time to the destination only, dig looks up DNS records, and ip route show displays the workstation''s own routing table rather than the path across the network.', 1),
  ('1.9', 'A traceroute from a Linux workstation shows only asterisks after the fifth hop, but tracert from a Windows PC on the same network completes. A firewall beyond hop five drops UDP probes but allows ICMP. Which command should the technician try on Linux?', '[{"text":"sudo traceroute -I server.example.com","is_correct":true},{"text":"traceroute -n server.example.com","is_correct":false},{"text":"sudo traceroute -m 5 server.example.com","is_correct":false},{"text":"ping -c 5 server.example.com","is_correct":false}]', 0, 'Linux traceroute sends UDP probes by default, starting at port 33434, while Windows tracert uses ICMP echo requests. traceroute -I switches to ICMP echo probes, which the firewall allows (ICMP probes can need root, hence sudo). -n only skips resolving hop names, -m 5 stops the trace at five hops, and ping tests whether the destination answers but doesn''t show the path.', 3),
  ('1.9', 'A Linux workstation''s /home partition is nearly full. Which command shows the total size of each user''s folder in human-readable units, so the technician can find the largest?', '[{"text":"df -h /home","is_correct":false},{"text":"ls -l /home","is_correct":false},{"text":"top","is_correct":false},{"text":"sudo du -sh /home/*","is_correct":true}]', 3, 'du reports the disk space used by files and directories: -s prints one total per argument and -h uses units such as M and G, so du -sh /home/* totals each home folder. df -h shows used and free space for the whole file system rather than per folder, ls -l shows the directories'' own entries rather than the size of their contents, and top shows running processes.', 1),
  ('1.9', 'df -h shows the file system holding /var at 97% used. What is the BEST next step to find what is using the space?', '[{"text":"Run sudo du -h --max-depth=1 /var and drill into the largest subfolder","is_correct":true},{"text":"Run sudo fsck on the /var file system so it can reclaim the space it''s using","is_correct":false},{"text":"Run df -i to find and remove the unused inodes on the file system","is_correct":false},{"text":"Reboot the workstation, so the kernel clears /var automatically","is_correct":false}]', 0, 'df shows how full a file system is, and du breaks that down by directory: du -h --max-depth=1 /var totals each subfolder one level down, so you can follow the largest, often /var/log or a cache, to the cause. fsck repairs file system errors rather than freeing space, df -i only reports inode usage, and rebooting doesn''t empty /var.', 2),
  ('1.9', 'A Linux workstation must reach a test server called stage01 at 10.0.5.20, which isn''t in DNS. The technician wants this name to work on this workstation only. Which file should be edited?', '[{"text":"/etc/resolv.conf","is_correct":false},{"text":"/etc/fstab","is_correct":false},{"text":"/etc/hosts","is_correct":true},{"text":"/etc/passwd","is_correct":false}]', 2, '/etc/hosts maps host names to IP addresses locally, so a line such as ''10.0.5.20 stage01'' works on this machine without a DNS record. /etc/resolv.conf lists the DNS servers and search domains to use, /etc/fstab lists file systems to mount, and /etc/passwd lists user accounts.', 1),
  ('1.9', 'On a Linux workstation, why can every user read /etc/passwd, while regular users can''t read /etc/shadow?', '[{"text":"/etc/passwd holds the users'' encrypted passwords, which are safe to share; /etc/shadow holds settings for the root account only","is_correct":false},{"text":"/etc/passwd holds account details programs need, like UIDs and home folders; /etc/shadow holds password hashes","is_correct":true},{"text":"/etc/shadow is a backup copy of /etc/passwd that fsck creates after each check","is_correct":false},{"text":"/etc/passwd lists the groups, and /etc/shadow lists the users who belong to each group","is_correct":false}]', 1, '/etc/passwd stores each account''s name, UID, GID, home folder and login shell, which many programs read; its password field normally holds just an x. The password hashes, with password-aging and account-expiry dates, are in /etc/shadow, which regular users mustn''t be able to read, because hashes in a readable file could be copied and cracked offline. /etc/shadow isn''t a backup made by fsck, and groups are defined in /etc/group.', 2),
  ('1.9', 'A Linux workstation reaches websites by IP address but not by name, and ip route shows the correct default gateway. Which file should the technician check next?', '[{"text":"/etc/fstab","is_correct":false},{"text":"/etc/shadow","is_correct":false},{"text":"/etc/passwd","is_correct":false},{"text":"/etc/resolv.conf","is_correct":true}]', 3, '/etc/resolv.conf lists the DNS servers (nameserver lines, up to three) and search domains the system''s resolver uses, so a wrong or missing nameserver breaks name lookups while connections by IP address still work. On many systems a service such as NetworkManager or systemd-resolved writes this file. /etc/fstab controls mounts, /etc/shadow holds password hashes, and /etc/passwd holds account details.', 2),
  ('1.9', 'A technician installs an SSH server on a Linux workstation that uses systemd, and wants the sshd service to start now and at every boot. Which command does both?', '[{"text":"sudo systemctl start sshd","is_correct":false},{"text":"systemctl status sshd","is_correct":false},{"text":"sudo systemctl restart sshd","is_correct":false},{"text":"sudo systemctl enable --now sshd","is_correct":true}]', 3, 'systemctl enable makes a service start at boot, and --now starts it immediately as well. systemctl start runs it only until the next reboot, status shows whether it''s running along with its recent log lines, and restart stops and starts a running service without changing whether it starts at boot.', 2),
  ('1.9', 'On most current Linux distributions, which component does the kernel start first, as process ID 1, to bring up and manage the system''s services?', '[{"text":"GRUB","is_correct":false},{"text":"sudo","is_correct":false},{"text":"systemd","is_correct":true},{"text":"cron","is_correct":false}]', 2, 'systemd is the init system and service manager on most modern distributions: the kernel starts it as PID 1, and it starts and supervises services, controlled with systemctl and logged with journalctl. GRUB is the bootloader that runs before the kernel, sudo runs a single command with elevated privileges, and cron runs scheduled jobs.', 1),
  ('1.9', 'A vendor''s driver supports Linux kernel 6.1 or later. Which command shows the version of the kernel the workstation is running?', '[{"text":"systemctl --version","is_correct":false},{"text":"uname -r","is_correct":true},{"text":"cat /etc/hosts","is_correct":false},{"text":"du -h /boot","is_correct":false}]', 1, 'The kernel is the core of the OS, managing the CPU, memory and hardware through drivers, and uname -r prints the release of the kernel that is running, such as 6.8.0-45-generic. systemctl --version shows the systemd version, /etc/hosts holds local name mappings, and du -h /boot shows how much space the kernel files take, not which one is running.', 2),
  ('1.9', 'When a Linux PC starts, which component shows the menu of installed kernels or operating systems and then loads the chosen kernel into memory?', '[{"text":"The bootloader, such as GRUB","is_correct":true},{"text":"The init system, such as systemd","is_correct":false},{"text":"The /etc/fstab file","is_correct":false},{"text":"The root account","is_correct":false}]', 0, 'The bootloader runs after the firmware (UEFI or BIOS) and loads the kernel and its initial RAM disk; GRUB is the usual Linux bootloader and can offer a menu of kernels or other operating systems. systemd starts after the kernel, /etc/fstab lists file systems to mount once the system is running, and the root account is the superuser rather than part of the boot process.', 1),
  ('1.9', 'After a kernel update, a Linux workstation crashes every time it starts. What is the quickest way to get it running so the technician can investigate?', '[{"text":"Choose the previous kernel from the GRUB boot menu at startup","is_correct":true},{"text":"Run fsck on the boot partition so that it can repair the new kernel","is_correct":false},{"text":"Reinstall the distribution, keeping the /home partition","is_correct":false},{"text":"Edit /etc/resolv.conf to point to a different DNS server","is_correct":false}]', 0, 'Distributions usually keep the previous kernel installed, and the GRUB boot menu (on some distributions under an Advanced options entry) lets you start it, so the system runs on the known-good kernel while you investigate or remove the faulty one. fsck repairs file systems and wouldn''t fix a faulty kernel, reinstalling is a last resort, and DNS settings don''t affect startup.', 3),
  ('1.9', 'A new Linux administrator wants to sign in as root for all daily work to avoid typing sudo. Which response BEST reflects good practice for the root account?', '[{"text":"Share the root password with the help desk team so everyone can fix problems quickly","is_correct":false},{"text":"Rename the root account, which removes UID 0 and its unlimited privileges from it","is_correct":false},{"text":"Use a standard account with sudo for admin commands, and block direct root sign-in, including over SSH","is_correct":true},{"text":"Sign in as root as planned, but turn off the shell history so that the commands typed aren''t recorded","is_correct":false}]', 2, 'root (UID 0) can do anything, so mistakes and malware running as root have no limits. A standard account plus sudo elevates one command at a time and logs who ran what; many distributions, such as Ubuntu, lock root''s password by default, and an SSH server can refuse root sign-ins (PermitRootLogin no). Sharing the root password removes accountability, renaming the account doesn''t change its UID 0 or its power, and turning off history only hides what was done.', 2),
  ('1.10', 'A school is setting up 150 identical lab PCs that all need the same office suite, browser and testing app. Which distribution method gets the applications onto every PC fastest and most consistently?', '[{"text":"Install each application from its downloadable package on each PC by hand, one at a time","is_correct":false},{"text":"Include the applications in a standard image and deploy that image to every PC","is_correct":true},{"text":"Mount each application''s ISO file on each PC and run its setup program","is_correct":false},{"text":"Email the students the download links and have them install the apps","is_correct":false}]', 1, 'With image deployment, the applications are installed once on a reference PC, captured in an image and deployed to every machine, so all 150 get identical, tested installs. Installing packages or mounting ISO files on each PC repeats the same work 150 times and lets machines drift apart, and leaving installs to students gives no control over versions or settings.', 2),
  ('1.10', 'An organization installs its standard applications as part of its Windows image. A critical security update for one of those applications is released. What drawback of this distribution method does the organization now face?', '[{"text":"Applications installed from an image can never be updated after deployment","is_correct":false},{"text":"Applications in an image need no licenses, so the vendor won''t support them","is_correct":false},{"text":"Image deployment works only on PCs that have a dedicated graphics card","is_correct":false},{"text":"The image must be rebuilt and retested, or new PCs get the old version","is_correct":true}]', 3, 'Applications built into an image are frozen at the version captured, so an app update means rebuilding and retesting the image, or pushing the update to PCs separately; otherwise new deployments start out of date. Imaged applications can still be updated after deployment, they still need valid licenses, and imaging has nothing to do with graphics hardware.', 2),
  ('1.10', 'An organization''s standard applications are updated almost every month, and rebuilding its Windows image each time is taking too long. Which change BEST reduces the work while keeping deployments consistent?', '[{"text":"Stop using images and install Windows and every application on each PC by hand from a USB drive instead","is_correct":false},{"text":"Use a thin image with the OS and core settings, and install the apps afterward from current packages","is_correct":true},{"text":"Keep the current image and skip application updates until the next hardware refresh","is_correct":false},{"text":"Add every application to the image, including ones that only one department uses","is_correct":false}]', 1, 'A thin image holds the OS and baseline settings, and applications are added after deployment from up-to-date packages, so an app update changes one package instead of the whole image. A thick image, with the applications built in, needs rebuilding whenever they change. Manual installs lose consistency, skipping updates leaves known vulnerabilities open, and adding every department''s apps makes the image bigger and out of date more often.', 3),
  ('1.10', 'A technician adds a CAD application to the company''s standard image, which is deployed to 120 PCs. The company owns 20 per-device licenses for the application. What is the problem?', '[{"text":"Applications included in an image are covered by the Windows license, so there''s no compliance problem","is_correct":false},{"text":"The imaging tool will stop deploying the image after the twentieth PC","is_correct":false},{"text":"Each PC the image installs the application on needs a license, so 100 PCs would be out of compliance","is_correct":true},{"text":"The application will uninstall itself from the PCs that don''t have a license","is_correct":false}]', 2, 'Putting an application in an image installs it on every PC that receives the image, and with per-device licensing each installation needs a license, so 120 installs against 20 licenses breaks the agreement. Deploy it separately to the 20 licensed PCs, or buy more licenses. The Windows license doesn''t cover other vendors'' software, imaging tools don''t count application licenses, and applications don''t remove themselves.', 2),
  ('1.11', 'A user''s laptop has a small SSD that is nearly full, mostly with files synced by OneDrive. The user wants to keep seeing every file in File Explorer but stop storing most of them on the laptop. What should the technician do?', '[{"text":"Unlink OneDrive from the laptop and delete the local OneDrive folder to recover the space","is_correct":false},{"text":"Turn on Always keep on this device for the whole OneDrive folder","is_correct":false},{"text":"Move the OneDrive folder to the Recycle Bin and empty it","is_correct":false},{"text":"Select the folders and choose Free up space, making them online-only files","is_correct":true}]', 3, 'With OneDrive Files On-Demand, Free up space turns locally available files into online-only files, shown with a cloud icon: they still appear in File Explorer and download when opened, but use no local space. Unlinking and deleting the folder removes the files from view, Always keep on this device does the opposite and stores everything locally, and deleting the folder deletes the files from OneDrive as well.', 2),
  ('1.11', 'A consultant will spend a week at a client site with no internet access and needs a project folder that is stored in OneDrive. Which option should be set on that folder before leaving?', '[{"text":"Always keep on this device","is_correct":true},{"text":"Free up space","is_correct":false},{"text":"Share, with an Anyone link","is_correct":false},{"text":"Version history","is_correct":false}]', 0, 'Always keep on this device downloads the folder''s files and keeps them on the laptop, shown with a solid green circle and white check mark, so they open offline; changes sync when the laptop is back online. Free up space does the opposite, and online-only files can''t be opened without an internet connection. A sharing link and version history don''t make files available offline.', 2),
  ('1.11', 'Before replacing a user''s laptop, a technician wants the user''s Desktop, Documents and Pictures folders to sync to the cloud automatically, so they appear on the new laptop once the user signs in to OneDrive. Which OneDrive setting does this?', '[{"text":"Choose folders, so that only the selected OneDrive folders sync to the new laptop","is_correct":false},{"text":"Free up space on the Desktop, Documents and Pictures folders","is_correct":false},{"text":"Back up the Desktop, Documents and Pictures folders to OneDrive (folder backup)","is_correct":true},{"text":"Turn on File History, saving to an external drive","is_correct":false}]', 2, 'OneDrive''s folder backup, also called Known Folder Move, redirects the Desktop, Documents and Pictures folders into OneDrive, so their contents sync to the cloud and appear on any PC where the user signs in to OneDrive. Choose folders limits which OneDrive folders sync to a device, Free up space makes files online-only, and File History backs up to a local or network drive rather than the cloud.', 2),
  ('1.11', 'A user''s OneDrive holds 900 GB across many folders. On a small second laptop, they want only two project folders to appear and sync, with nothing else from OneDrive shown. Which OneDrive setting should the technician use on that laptop?', '[{"text":"Choose folders, selecting only the two project folders","is_correct":true},{"text":"Always keep on this device, for the whole OneDrive","is_correct":false},{"text":"Back up the Desktop folder to OneDrive","is_correct":false},{"text":"Pause syncing for 24 hours","is_correct":false}]', 0, 'Choose folders (selective sync) controls which OneDrive folders sync to, and appear on, a particular device; the others stay in the cloud and are hidden there. Always keep on this device would download everything, folder backup adds the Desktop to OneDrive rather than limiting what syncs, and pausing sync stops updates only for a while.', 2),
  ('1.11', 'A team emails a budget spreadsheet back and forth, and edits keep getting lost between copies. Everyone has the same cloud productivity suite. What should the technician recommend?', '[{"text":"Save the spreadsheet as a PDF before each person emails it on to the next","is_correct":false},{"text":"Have each person keep their own local copy, then merge all of the copies together at the end of each week","is_correct":false},{"text":"Compress the spreadsheet into a ZIP file so its contents can''t change in transit","is_correct":false},{"text":"Keep one copy in shared cloud storage and share it with edit access, so everyone co-authors it","is_correct":true}]', 3, 'Cloud spreadsheet apps such as Excel for the web and Google Sheets let several people edit one stored copy at the same time, saving changes automatically and keeping version history, so nothing is lost between copies. A PDF can''t be edited as a spreadsheet, weekly merges keep the conflicting copies, and a ZIP file only compresses the attachment.', 1),
  ('1.11', 'An hour ago, a user accidentally deleted half of a shared cloud document, and others have been editing it since. What should the technician do FIRST?', '[{"text":"Restore the user''s PC from last night''s system image to get the document back","is_correct":false},{"text":"Open the document''s version history and copy back the deleted text","is_correct":true},{"text":"Delete the document and ask the user to type the lost text again","is_correct":false},{"text":"Use Free up space on the document to reset it","is_correct":false}]', 1, 'Cloud word processors and storage, such as Word with OneDrive or SharePoint, or Google Docs, keep version history, so an earlier version can be opened and the lost text copied back without undoing others'' later edits. Restoring the PC doesn''t touch the cloud copy, retyping is unnecessary, and Free up space only changes whether a synced file is stored locally.', 2),
  ('1.11', 'A user joins videoconferences in a web browser. Others can see the user''s video but can''t hear them, and the browser shows a crossed-out microphone icon in the address bar. What should the technician check FIRST?', '[{"text":"Whether a videoconferencing license has been assigned to the user''s account in the admin center","is_correct":false},{"text":"The DNS server settings on the network adapter the user''s laptop is using","is_correct":false},{"text":"Whether the meeting organizer has started recording the meeting","is_correct":false},{"text":"The browser''s microphone permission for the site, and Windows'' microphone privacy settings","is_correct":true}]', 3, 'A crossed-out microphone icon means the browser has blocked the site from using the microphone; allow it in the site''s permissions, and check that Windows lets the browser use the microphone (Settings > Privacy & security > Microphone). A licensing problem would stop the user joining at all, a DNS problem would stop the meeting loading, and recording doesn''t mute anyone.', 2),
  ('1.11', 'After a meeting, a presenter wants to send an outside client a slide deck stored in the company''s cloud storage. The client should be able to view the slides but not change them, and the original must stay in the company''s storage. What should the presenter do?', '[{"text":"Share a link to the deck with edit permission","is_correct":false},{"text":"Share a link to the deck with view-only permission","is_correct":true},{"text":"Move the deck into the client''s own cloud account","is_correct":false},{"text":"Create a full company account for the client","is_correct":false}]', 1, 'Cloud presentation tools such as PowerPoint for the web and Google Slides can share a file with view-only permission, so the client always sees the current slides but can''t edit them, and the file stays in the company''s storage. Edit permission would let the client change the deck, moving it hands over the original, and a full company account gives far more access than needed.', 2),
  ('1.11', 'A project team wants quick back-and-forth conversations, with searchable history organized by topic and @mentions to get someone''s attention, instead of long email threads. Which cloud collaboration tool fits BEST?', '[{"text":"An instant messaging platform with team channels, such as Microsoft Teams or Slack","is_correct":true},{"text":"A shared spreadsheet with a row for each question and a column for each person''s answer","is_correct":false},{"text":"A videoconference scheduled every hour, so everyone can talk things through","is_correct":false},{"text":"A shared mailbox that every member of the team can read and reply from","is_correct":false}]', 0, 'Instant messaging platforms with persistent chat and channels give fast conversations, @mentions, presence status and searchable history grouped by team or topic. A spreadsheet holds data rather than conversations, hourly videoconferences interrupt work and leave no searchable text, and a shared mailbox is still email, with the long threads the team wants to avoid.', 1),
  ('1.11', 'A technician is setting up the Outlook desktop app for a new employee whose mailbox is in Microsoft 365. What does the technician normally need to enter?', '[{"text":"The IMAP and SMTP server names, their port numbers and encryption types","is_correct":false},{"text":"The mailbox server''s IP address and the POP3 port number","is_correct":false},{"text":"The user''s email address; after sign-in, Autodiscover finds the settings","is_correct":true},{"text":"The organization''s MX record and its DNS server addresses","is_correct":false}]', 2, 'Cloud email systems such as Microsoft 365 support Autodiscover: enter the email address, sign in (with MFA if required) and Outlook configures itself. Entering IMAP or POP3 servers and ports by hand is for providers without automatic setup and loses calendar and contact sync. MX records tell other mail servers where to deliver the domain''s mail; email clients don''t need them.', 2),
  ('1.11', 'A company is moving its email from an on-premises server to a cloud email provider. Which DNS record must change so that mail from the internet is delivered to the new provider?', '[{"text":"The CNAME record for www","is_correct":false},{"text":"The PTR record for the router''s address","is_correct":false},{"text":"The A record for the web server","is_correct":false},{"text":"The MX records for the domain","is_correct":true}]', 3, 'MX (mail exchanger) records tell sending mail servers which hosts accept email for a domain, so pointing them at the cloud provider routes incoming mail there. Providers also ask for records such as SPF, DKIM and DMARC so receivers can authenticate the domain''s mail. A CNAME for www and an A record for the web server affect the website, and a PTR record maps an IP address back to a name.', 2),
  ('1.11', 'Employees sign in to their domain-joined PCs with Active Directory accounts but have to remember a separate password for the company''s Microsoft 365 apps. What should be deployed so they use the same user name and password for both?', '[{"text":"Identity synchronization, such as Microsoft Entra Connect, syncing AD accounts to the cloud directory","is_correct":true},{"text":"A separate local account on each PC, with its password always set to match the user''s cloud password","is_correct":false},{"text":"A password manager on each PC that stores both of each user''s passwords for them","is_correct":false},{"text":"A Group Policy setting that makes both the AD and cloud passwords never expire","is_correct":false}]', 0, 'Identity synchronization copies on-premises Active Directory users and groups to the cloud identity provider, Microsoft Entra ID for Microsoft 365, and with password hash synchronization users sign in to cloud apps with their AD credentials, so there is one identity to manage. Matching local accounts and password managers still leave two credentials to keep in step, and never-expiring passwords weaken security without linking the accounts.', 2),
  ('1.11', 'An administrator creates a new hire''s account in on-premises Active Directory at 9:05. At 9:10 the new hire can sign in to their domain PC but not to Microsoft 365, which says the account doesn''t exist. Directory sync runs on Microsoft Entra Connect''s default schedule. What is the MOST likely explanation?', '[{"text":"Microsoft 365 accounts must be created by hand in the cloud even when directory sync is used","is_correct":false},{"text":"It hasn''t synced yet: sync runs every 30 minutes by default, or an admin can force one","is_correct":true},{"text":"The new hire''s PC must run gpupdate /force before cloud sign-in can work","is_correct":false},{"text":"The account can''t exist in the cloud directory until a license is assigned to it","is_correct":false}]', 1, 'Microsoft Entra Connect Sync runs a sync cycle every 30 minutes by default, so a new on-premises account appears in the cloud after the next cycle; an administrator can trigger one sooner with Start-ADSyncSyncCycle -PolicyType Delta. Synced accounts aren''t created by hand, Group Policy refreshes don''t sync accounts, and licenses are assigned to accounts that already exist in the cloud directory.', 3),
  ('1.11', 'A new employee can sign in to the Microsoft 365 portal, but Outlook on the web says they have no mailbox and the desktop Office apps won''t activate. The account was synced from Active Directory yesterday. What should the technician check FIRST?', '[{"text":"Whether the user''s PC is running the latest firmware version available from its manufacturer","is_correct":false},{"text":"Whether the user''s new password meets the domain''s complexity requirements","is_correct":false},{"text":"Whether a license that includes Exchange Online and the Office apps is assigned to the user","is_correct":true},{"text":"Whether the user''s account is in the local Administrators group on their PC","is_correct":false}]', 2, 'Syncing or creating an account gives the user an identity, but services such as an Exchange Online mailbox and Office app activation come from the license assigned to that user, in the Microsoft 365 admin center (Users > Active users > Licenses and apps) or through group-based licensing. Firmware, password complexity and local admin rights don''t create mailboxes or activate Office.', 2),
  ('1.11', 'A technician tries to assign a Microsoft 365 license to a user whose account was synced from on-premises Active Directory, and the admin center asks for one more detail before it will assign it. Which detail is it MOST likely to be?', '[{"text":"Usage location","is_correct":true},{"text":"Job title","is_correct":false},{"text":"Manager","is_correct":false},{"text":"Office phone number","is_correct":false}]', 0, 'Microsoft 365 needs a usage location, the country where the user will use the services, before it can assign a license, because services vary by country, and accounts synced from on-premises AD have none by default. Job title, manager and phone number are optional directory details that don''t affect licensing.', 3),
  ('1.11', 'An employee is leaving, and a replacement starts next week. The company''s cloud productivity suite is licensed per user, and the company has exactly as many licenses as staff. Once the departing employee''s data has been handled under company policy, what should the technician do with their license?', '[{"text":"Leave it assigned, because unused licenses move to new users automatically after 90 days","is_correct":false},{"text":"Buy a new license for the replacement and keep the old one assigned","is_correct":false},{"text":"Give the replacement the departed employee''s user name and password","is_correct":false},{"text":"Remove the license from the departed user''s account so it can be assigned to the new hire","is_correct":true}]', 3, 'Per-user subscription licenses are assigned to accounts, so unassigning the license from the departed user''s account frees it for the replacement and the company doesn''t pay for an unused seat. Licenses aren''t reassigned automatically, buying another wastes money, and sharing a former employee''s credentials breaks accountability and most service terms.', 1),
  ('2.1', 'A company replaces employees'' plastic access badges with credentials stored in their smartphones'' digital wallets, and employees tap their phones on the door readers to enter. Which physical access security control is this?', '[{"text":"Key fob","is_correct":false},{"text":"Smart card","is_correct":false},{"text":"Mobile digital key","is_correct":true},{"text":"Access control vestibule","is_correct":false}]', 2, 'A mobile digital key stores an access credential on a smartphone or smartwatch and presents it to a reader over NFC or Bluetooth, much like tapping a card. A key fob is a separate small token carried on a keyring, a smart card is a physical card with an embedded chip, and an access control vestibule is a two-door space that lets one person through at a time.', 1),
  ('2.1', 'An employee who uses a mobile digital key on their phone to enter the office reports the phone stolen. What advantage do mobile digital keys have over traditional metal keys in this situation?', '[{"text":"The phone automatically changes the door''s lock cylinder when it is reported stolen","is_correct":false},{"text":"The stolen phone''s credential can be revoked right away, without rekeying any locks","is_correct":true},{"text":"Mobile digital keys expire every night, so the stolen phone stops opening doors on its own","is_correct":false},{"text":"The building alarm sounds whenever the stolen phone comes near a door reader","is_correct":false}]', 1, 'Mobile credentials are managed centrally, so an administrator can revoke the stolen phone''s key at once and issue a new one to the employee''s replacement phone, while a lost metal key means changing locks. Phones can''t change lock cylinders, mobile keys don''t simply expire each night, and the alarm system doesn''t track where a lost phone is.', 2),
  ('2.1', 'A data center wants to verify people as they walk up to its entrance, without anyone touching or looking into a reader, by comparing each face with an enrolled list of authorized staff. Which biometric technology fits BEST?', '[{"text":"Palm print scanner","is_correct":false},{"text":"Fingerprint scanner","is_correct":false},{"text":"Retina scanner","is_correct":false},{"text":"Facial recognition","is_correct":true}]', 3, 'Facial recognition technology captures a face with a camera and matches it against enrolled templates, so it works without contact and from a short distance as people approach. Palm print and fingerprint scanners need the person to present a hand or finger at the reader, and a retina scanner needs them to look into it at close range.', 2),
  ('2.1', 'A company is replacing badge readers with facial recognition technology (FRT) at its doors. Which concern applies to FRT but NOT to the badge readers?', '[{"text":"Employees can lend their credential to a coworker who isn''t supposed to have access to the building","is_correct":false},{"text":"The credential stops working when the battery in it runs out","is_correct":false},{"text":"Lighting, camera angle and people who look alike can cause false acceptances or false rejections","is_correct":true},{"text":"The credential can be copied with a hidden RFID reader","is_correct":false}]', 2, 'FRT matches a camera image against stored templates, so lighting, angle and lookalikes can cause false matches or rejections, basic systems may be fooled by photos unless they check for liveness, and stored face templates bring privacy obligations; plan a fallback method. Lending a credential, flat batteries and RFID cloning are risks of badges, fobs and phones, which FRT avoids because the face itself is the credential.', 3),
  ('2.1', 'A bank''s phone support line verifies callers by their voiceprint. Which weakness of voice recognition technology should the bank plan for?', '[{"text":"Recordings or AI-cloned voices may fool it, and a cold or noise can cause rejections","is_correct":true},{"text":"It can''t work over a phone line, because it needs a camera to see the caller","is_correct":false},{"text":"It requires every caller to have a smart card reader attached to the phone they call from","is_correct":false},{"text":"It stores each caller''s fingerprints, which raises privacy concerns","is_correct":false}]', 0, 'Voice recognition compares a speaker''s voice with an enrolled voiceprint, so replayed recordings and AI voice clones are a spoofing risk, and illness, noise or a poor line can cause false rejections; pairing it with another factor addresses both. It works on phone audio, needs no camera or smart card reader, and stores voice characteristics rather than fingerprints.', 2),
  ('2.1', 'Which biometric method identifies a person by the distinctive characteristics of how they speak?', '[{"text":"Facial recognition","is_correct":false},{"text":"Voice recognition","is_correct":true},{"text":"Retina scanning","is_correct":false},{"text":"Palm print scanning","is_correct":false}]', 1, 'Voice recognition (speaker recognition) measures vocal characteristics such as pitch, tone and rhythm and matches them against an enrolled voiceprint. Facial recognition uses facial features, retina scanning uses the pattern of blood vessels at the back of the eye, and palm print scanning uses the lines and features of the palm.', 1),
  ('2.1', 'A company''s security policy says: no user or device is trusted because it''s on the corporate network; every request is authenticated, authorized and checked for device health; and access is limited to what each task needs. Which security model does this describe?', '[{"text":"Perimeter-based security","is_correct":false},{"text":"Discretionary access control","is_correct":false},{"text":"Security through obscurity","is_correct":false},{"text":"Zero Trust","is_correct":true}]', 3, 'Zero Trust means never trust, always verify: network location grants no trust, each request is checked against identity, device health and policy, and access follows least privilege. Perimeter-based security trusts whatever is inside the network, discretionary access control lets resource owners set permissions, and security through obscurity relies on hiding how things work.', 2),
  ('2.1', 'An organization adopting a Zero Trust model finds that a sales laptop on the office LAN can reach the HR database server directly. Which change BEST fits Zero Trust?', '[{"text":"Verify each connection to HR systems per user and device, and segment the network","is_correct":true},{"text":"Keep trusting the laptop, because it''s domain-joined and sits inside the corporate firewall","is_correct":false},{"text":"Move the HR database server into the screened subnet so it''s easier to reach","is_correct":false},{"text":"Give every employee a VPN account so that all their traffic is encrypted","is_correct":false}]', 0, 'Zero Trust removes trust based on network location: each access to a resource is verified for that user and device, and segmentation limits which systems can reach each other at all. Trusting the laptop because it''s domain-joined and inside the firewall is the perimeter thinking Zero Trust replaces, a screened subnet is for systems exposed to the internet, and a VPN encrypts traffic but still trusts whoever connects.', 3),
  ('2.1', 'An authenticator app on a user''s phone shows a six-digit code that changes every 30 seconds, calculated from a secret shared at setup and the current time. Which authentication method is this?', '[{"text":"One-time passcode sent by SMS","is_correct":false},{"text":"Security Assertion Markup Language (SAML)","is_correct":false},{"text":"Time-based one-time password (TOTP)","is_correct":true},{"text":"Voice call verification","is_correct":false}]', 2, 'TOTP derives each code from a secret shared at enrollment and the current time, so the app works offline and each code expires after a short window; the phone''s clock must be roughly right. An SMS passcode is generated by the service and texted to the phone, SAML passes sign-in assertions between websites, and a voice call reads a code aloud.', 2),
  ('2.1', 'A company''s MFA sends a one-time passcode (OTP) to each user by text message. Why do security guides rate SMS codes as weaker than an authenticator app or a hardware token?', '[{"text":"SMS codes never expire, so a code stolen from a phone can be reused again and again indefinitely","is_correct":false},{"text":"Texts can be redirected through SIM swapping or intercepted, and are easy to phish","is_correct":true},{"text":"SMS codes are much longer, so users tend to write them down","is_correct":false},{"text":"SMS codes can only be used to sign in on desktop computers","is_correct":false}]', 1, 'An OTP sent by SMS depends on the phone network: attackers can take over a number through SIM swapping or port-out fraud, or trick users into reading a code to them, so an authenticator app, hardware token or passkey is stronger. SMS codes expire after a few minutes, they aren''t longer than app codes, and they work wherever the user signs in.', 2),
  ('2.1', 'Employees sign in once to the company''s identity provider, then open a third-party payroll website without signing in again. Behind the scenes, the identity provider sends the payroll site a signed XML message confirming who the user is. Which standard is being used?', '[{"text":"Kerberos","is_correct":false},{"text":"RADIUS","is_correct":false},{"text":"SAML","is_correct":true},{"text":"TACACS+","is_correct":false}]', 2, 'SAML (Security Assertion Markup Language) is an XML-based standard in which an identity provider sends a signed assertion about a user to a service provider, such as a web app, enabling single sign-on across organizations. Kerberos issues tickets inside a domain such as Active Directory, RADIUS authenticates network access such as Wi-Fi and VPN connections, and TACACS+ authenticates administrators on network devices.', 2),
  ('2.1', 'Users complain that each morning they sign in separately to email, the HR portal, the file share and the ticketing system. Which solution lets them authenticate once and use all four?', '[{"text":"Single sign-on (SSO)","is_correct":true},{"text":"Password expiration","is_correct":false},{"text":"Account lockout policy","is_correct":false},{"text":"Log-in time restrictions","is_correct":false}]', 0, 'SSO lets one authentication to a trusted identity provider grant access to many connected applications, so users sign in once. Password expiration forces periodic changes, an account lockout policy blocks sign-ins after repeated failures, and log-in time restrictions limit when users can sign in; none of them reduce the number of sign-ins.', 1),
  ('2.1', 'A company issues 300 smartphones and must enforce passcodes and encryption, push approved apps, and wipe any phone that is lost. Which solution does all of this from one place?', '[{"text":"Data loss prevention (DLP)","is_correct":false},{"text":"A virtual private network (VPN)","is_correct":false},{"text":"Directory services","is_correct":false},{"text":"Mobile device management (MDM)","is_correct":true}]', 3, 'MDM enrolls devices and lets administrators push configuration and security policies, deploy apps and lock or wipe devices remotely from one console; Microsoft Intune and Jamf are examples. DLP watches for sensitive data leaving the organization, a VPN encrypts network traffic, and directory services store identities rather than configuring phones.', 1),
  ('2.1', 'An employee enrolls a personal phone in the company''s MDM to get work email, then worries that IT can now see personal photos and wipe the whole phone. Which MDM approach BEST addresses this for BYOD?', '[{"text":"Full device enrollment with supervision, applied in the same way to every personal phone in the company","is_correct":false},{"text":"Work-profile or user enrollment, keeping work apps and data separate and wipeable on their own","is_correct":true},{"text":"No MDM at all for personal phones, with unmanaged access to company email instead","is_correct":false},{"text":"A factory reset of the phone before it''s enrolled, so no personal data is on it","is_correct":false}]', 1, 'BYOD-focused enrollment, such as Android''s work profile or Apple''s User Enrollment, separates company apps and data from personal content, so IT manages, and can selectively wipe, only the work side. Full enrollment and supervision suit company-owned devices, unmanaged email access drops the company''s protections, and a factory reset doesn''t keep work and personal data apart afterward.', 2),
  ('2.1', 'A hospital wants to automatically stop emails and file uploads containing patient record numbers or credit card numbers from leaving the organization. Which control does this?', '[{"text":"Mobile device management (MDM)","is_correct":false},{"text":"Data loss prevention (DLP)","is_correct":true},{"text":"Endpoint detection and response (EDR)","is_correct":false},{"text":"Single sign-on (SSO)","is_correct":false}]', 1, 'DLP inspects content in email, uploads, endpoints and cloud storage for patterns such as card numbers or medical record numbers, then blocks, encrypts or flags it according to policy. MDM manages device settings, EDR detects and responds to threats on endpoints, and SSO simplifies signing in.', 1),
  ('2.1', 'An employee tries to copy a spreadsheet of customers'' Social Security numbers to a USB flash drive, and a message says the action is blocked by company policy. What MOST likely blocked it?', '[{"text":"BitLocker To Go","is_correct":false},{"text":"Windows Defender Firewall","is_correct":false},{"text":"An endpoint DLP agent","is_correct":true},{"text":"User Account Control","is_correct":false}]', 2, 'Endpoint DLP runs on the device and can stop sensitive content from being copied to removable media, printed or uploaded, showing a policy message to the user. BitLocker To Go encrypts removable drives rather than inspecting what''s copied, the firewall filters network traffic rather than file copies, and UAC prompts for elevation.', 2),
  ('2.1', 'What is the main purpose of directory services such as Active Directory Domain Services or an LDAP directory?', '[{"text":"To store user, group and computer accounts centrally for authentication and management","is_correct":true},{"text":"To translate host names into IP addresses when users browse the web","is_correct":false},{"text":"To hand out IP addresses and default gateway settings to client devices automatically at startup","is_correct":false},{"text":"To keep backup copies of users'' files at an offsite location for recovery","is_correct":false}]', 0, 'A directory service is a central database of identities and resources, such as users, groups, computers and printers, used for authentication, authorization and management; LDAP is the protocol commonly used to query it. Translating names to addresses is DNS, assigning addresses is DHCP, and offsite file copies are a backup function.', 1),
  ('2.1', 'An application needs to look up user accounts and group memberships in the company directory, and security policy requires those queries to be encrypted. Which protocol and port should the application use?', '[{"text":"LDAP on TCP port 389","is_correct":false},{"text":"Kerberos on port 88","is_correct":false},{"text":"SMB on TCP port 445","is_correct":false},{"text":"LDAPS on TCP port 636","is_correct":true}]', 3, 'LDAP is the protocol for querying directory services, and LDAPS (LDAP over TLS) on TCP port 636 encrypts those queries. Plain LDAP on 389 isn''t encrypted unless it''s upgraded with StartTLS, Kerberos on port 88 issues authentication tickets rather than answering directory lookups, and SMB on 445 is for file and printer sharing.', 2),
  ('2.1', 'An auditor flags that a company''s administrators hold domain admin rights permanently. The company wants admins to request elevated rights when they need them, receive them for a few hours, and have that use recorded. Which approach does this describe?', '[{"text":"Just-in-time access through a privileged access management (PAM) solution","is_correct":true},{"text":"Single sign-on for every administrator account","is_correct":false},{"text":"A shared administrator password, kept in a spreadsheet that only admins can open","is_correct":false},{"text":"Disabling the built-in guest account","is_correct":false}]', 0, 'Just-in-time access grants elevated privileges only when requested and approved, for a limited time, and a PAM solution manages, records and audits that privileged access, so no one holds standing admin rights. SSO only reduces sign-in prompts, a shared password in a spreadsheet removes accountability and is easy to steal, and disabling the guest account doesn''t change what admins can do.', 2),
  ('2.1', 'A company wants new hires'' accounts created automatically from HR records, access granted by job role, and all access removed on the day someone leaves. Which discipline covers this whole account life cycle?', '[{"text":"Data loss prevention (DLP)","is_correct":false},{"text":"Mobile device management (MDM)","is_correct":false},{"text":"Endpoint detection and response (EDR)","is_correct":false},{"text":"Identity and access management (IAM)","is_correct":true}]', 3, 'IAM manages digital identities through their life cycle, from provisioning and role-based access to access reviews and deprovisioning, along with the policies that control what each identity can reach. DLP protects data from leaving the organization, MDM manages devices, and EDR detects threats on endpoints.', 2),
  ('2.2', 'A user asks why IT wants them to sign in to Windows with a Windows Hello PIN instead of their account password. Which statement is TRUE?', '[{"text":"The PIN is stored on Microsoft''s servers, so it can always be recovered if the user forgets it","is_correct":false},{"text":"The PIN is secure only if it is longer than the password it replaces","is_correct":false},{"text":"The PIN is tied to that one device and never sent over the network, so it''s useless elsewhere","is_correct":true},{"text":"The PIN works on any computer the user signs in to, just like the password","is_correct":false}]', 2, 'A Windows Hello PIN unlocks a key protected by the device''s TPM: the PIN stays on the device, isn''t stored on any server and works only where it was set up, while a stolen password can be used from anywhere. The TPM also limits repeated guesses. No server holds the PIN, its protection comes from being tied to the device rather than from length, and Hello has to be set up separately on each device.', 2),
  ('2.2', 'A Windows 11 user with a Microsoft account has set up Windows Hello face and PIN sign-in, and wants to remove the password option from this PC''s sign-in screen. Which setting should the technician turn on?', '[{"text":"Password never expires, in the user''s properties in Local Users and Groups","is_correct":false},{"text":"Only allow Windows Hello sign-in for Microsoft accounts on this device","is_correct":true},{"text":"Dynamic lock, in Settings > Accounts > Sign-in options","is_correct":false},{"text":"The lowest User Account Control level, in Control Panel","is_correct":false}]', 1, 'The setting ''For improved security, only allow Windows Hello sign-in for Microsoft accounts on this device'', under Settings > Accounts > Sign-in options, makes sign-in passwordless for Microsoft accounts on that PC: users sign in with Windows Hello (face, fingerprint or PIN) and the password option goes away on that device. Password never expires keeps the password in use, Dynamic lock locks the PC when a paired phone moves away, and lowering UAC weakens security without changing sign-in.', 2),
  ('2.2', 'A technician tries to join a new Windows 11 Pro PC to the corp.example.com domain and gets an error that a domain controller for the domain could not be contacted. The PC can browse the internet. What is the MOST likely cause?', '[{"text":"The PC is running Windows 11 Pro, which can''t join a domain","is_correct":false},{"text":"The PC''s DNS server is set to a public resolver instead of the company''s AD DNS servers","is_correct":true},{"text":"The domain administrator account being used for the join has been locked out by too many attempts","is_correct":false},{"text":"BitLocker is turned on for the PC''s system drive","is_correct":false}]', 1, 'Domain members find domain controllers through DNS service (SRV) records that only the company''s AD DNS servers hold, so a PC pointed at an ISP or public resolver can browse the web but can''t locate a domain controller. Windows 11 Pro supports domain join (Home doesn''t), a locked-out account produces a credential error once a domain controller is found, and BitLocker doesn''t affect joining a domain.', 2),
  ('2.2', 'A technician must join a Windows 11 Pro desktop to the company''s Active Directory domain. Which of the following is a correct way to do it?', '[{"text":"Sign in to the Microsoft Store with a domain account, then restart the desktop to finish joining","is_correct":false},{"text":"Run gpupdate /force from an elevated command prompt, then restart the desktop to finish joining","is_correct":false},{"text":"Map a network drive to a share on a domain controller, then restart the desktop to finish joining","is_correct":false},{"text":"In System Properties (sysdm.cpl), change Member of to Domain, enter the domain and credentials, then restart","is_correct":true}]', 3, 'In System Properties, Computer Name > Change > Member of: Domain joins the PC once you enter the domain name and an account allowed to join computers, followed by a restart; Settings > Accounts > Access work or school > Connect also offers to join a local Active Directory domain. The Microsoft Store doesn''t join domains, gpupdate refreshes Group Policy on a PC that''s already a member, and mapping a drive just connects to a share.', 1),
  ('2.2', 'A remote employee''s laptop runs Windows 11 Home. The company wants it joined to the Active Directory domain so that Group Policy applies. What must happen first?', '[{"text":"Enable the built-in guest account on the laptop","is_correct":false},{"text":"Install the Media Feature Pack from Optional features","is_correct":false},{"text":"Upgrade the laptop to Windows 11 Pro, or another edition that can join a domain","is_correct":true},{"text":"Rename the laptop''s workgroup so that it exactly matches the domain name, then restart","is_correct":false}]', 2, 'Windows 11 Home can''t join an Active Directory domain, while Pro, Enterprise and Education can, so upgrading the edition with a Pro license enables the domain join option. The guest account and the Media Feature Pack are unrelated, and a workgroup with the same name as the domain is still a workgroup, not domain membership.', 2),
  ('2.2', 'A Group Policy object that installs accounting software is linked to the Accounting OU, but a new accounting PC isn''t getting it. In Active Directory Users and Computers, the PC''s computer object is still in the default Computers container. What should the administrator do?', '[{"text":"Move the computer object into the Accounting OU, then restart the PC","is_correct":true},{"text":"Link the Group Policy object to the user''s mailbox instead of the OU","is_correct":false},{"text":"Delete the computer object and join the PC to a workgroup","is_correct":false},{"text":"Add the PC''s IP address to the Group Policy object''s description","is_correct":false}]', 0, 'Group Policy objects apply to users and computers in the OUs they''re linked to, and new computer accounts go into the Computers container, which isn''t an OU and can''t have policies linked to it. Moving the object into the Accounting OU (drag it, or right-click > Move) brings it into scope, and a restart applies the policy, since software installation policies run at startup. Policies aren''t linked to mailboxes, leaving the domain removes policy entirely, and a description has no effect.', 2),
  ('2.4', 'A client says an ex-partner seems to know where they go and what they text. Their phone has an unfamiliar app with device administrator rights, heavy battery drain and unexplained data use. Which type of malware is MOST likely installed?', '[{"text":"Cryptominer","is_correct":false},{"text":"Ransomware","is_correct":false},{"text":"Boot sector virus","is_correct":false},{"text":"Stalkerware","is_correct":true}]', 3, 'Stalkerware is spyware installed secretly, often by someone close to the victim, to track location, messages, calls and photos; signs include unknown apps with high privileges, battery drain and data use. A cryptominer uses a device''s processor to mine cryptocurrency, ransomware encrypts files for a ransom, and a boot sector virus infects a computer''s boot code.', 2),
  ('2.4', 'A technician finds stalkerware on a client''s phone that an abusive partner installed. Before removing it, what should the technician consider?', '[{"text":"The abuser may notice when it stops reporting, so the client should plan for their safety first","is_correct":true},{"text":"Stalkerware can''t be removed from a phone, so the phone must be physically destroyed right away","is_correct":false},{"text":"The app should stay installed permanently, so that everything it does keeps being logged as evidence","is_correct":false},{"text":"The technician should contact the partner directly and ask them to uninstall the app themselves","is_correct":false}]', 0, 'Whoever installed stalkerware may notice when it stops reporting, which can put the client in more danger, so safety and abuse-support services advise planning before removal, and the client may want evidence preserved. Then remove it, update the OS, change account passwords and check other devices and accounts. It can be removed with security tools or a factory reset, leaving it in place keeps the client watched, and contacting the abuser risks the client''s safety.', 3),
  ('2.4', 'An infection runs malicious PowerShell commands directly in memory, launched from a registry Run key, and never writes an executable file to disk. A signature-based antivirus scan finds nothing. Which type of malware is this?', '[{"text":"Boot sector virus","is_correct":false},{"text":"Fileless malware","is_correct":true},{"text":"Trojan horse","is_correct":false},{"text":"Adware","is_correct":false}]', 1, 'Fileless malware runs in memory and abuses built-in tools such as PowerShell and WMI, often persisting through registry entries or scheduled tasks, so file-scanning antivirus has no malicious file to match. A boot sector virus infects boot code on disk, a Trojan is a malicious program disguised as legitimate software, and adware displays unwanted advertising.', 2),
  ('2.4', 'Which tool is BEST suited to detecting fileless malware on company laptops?', '[{"text":"Traditional antivirus that only scans the files on disk for known malware signatures each night","is_correct":false},{"text":"A disk defragmenter scheduled to run every week on each of the laptops","is_correct":false},{"text":"EDR that watches process behavior, such as an Office app launching encoded PowerShell","is_correct":true},{"text":"A firewall rule on each laptop that blocks outbound traffic on port 80","is_correct":false}]', 2, 'Because fileless malware leaves little or nothing on disk, it''s caught by watching behavior: EDR records process activity and flags patterns such as a document starting obfuscated PowerShell. Signature-only scanning looks for known files, defragmenting rearranges how files are stored, and blocking port 80 stops some unencrypted web traffic but not scripts running in memory.', 2),
  ('2.4', 'After installing a free PDF converter, a user finds a new browser toolbar, a changed search engine and a PC optimizer that nags them to buy a license. The installer had pre-checked boxes for these extras. How are these programs BEST classified?', '[{"text":"Rootkits","is_correct":false},{"text":"Keyloggers","is_correct":false},{"text":"Potentially unwanted programs","is_correct":true},{"text":"Boot sector viruses","is_correct":false}]', 2, 'Potentially unwanted programs (PUPs) are bundled software, such as toolbars, search changers and scareware-style optimizers, that users technically agreed to through pre-checked installer options but don''t want; they hurt performance and privacy without being outright malicious code. Rootkits hide deep in the OS to conceal malware, keyloggers record keystrokes, and boot sector viruses infect boot code.', 1),
  ('2.4', 'A technician wants Windows to block potentially unwanted apps on employees'' PCs, both apps already present and downloads in Microsoft Edge. Where is this set in Windows Security?', '[{"text":"Firewall & network protection > Allow an app through firewall, with each unwanted app removed from the list","is_correct":false},{"text":"Device security > Core isolation > Memory integrity, turned on for all users","is_correct":false},{"text":"Account protection > Dynamic lock, with each employee''s phone paired to their PC","is_correct":false},{"text":"App & browser control > Reputation-based protection > Potentially unwanted app blocking","is_correct":true}]', 3, 'Potentially unwanted app blocking is under App & browser control > Reputation-based protection settings: Block apps has Microsoft Defender detect PUAs already on the PC, and Block downloads stops them as they download in Microsoft Edge. Firewall rules control network traffic, memory integrity protects the Windows kernel from malicious code, and Dynamic lock locks the PC when a paired phone moves away.', 2),
  ('2.4', 'A user''s PC shows pop-up advertisements on the desktop even when no browser is open, and new ads appear every few minutes. Which type of software is MOST likely responsible?', '[{"text":"Ransomware","is_correct":false},{"text":"Adware","is_correct":true},{"text":"Rootkit","is_correct":false},{"text":"Cryptominer","is_correct":false}]', 1, 'Adware displays unwanted advertising, often as pop-ups outside the browser, and frequently arrives bundled with free software; remove it in Settings > Apps and run an anti-malware scan. Ransomware encrypts files and demands payment, a rootkit hides itself and other malware rather than showing ads, and a cryptominer uses the CPU or GPU to mine cryptocurrency.', 1),
  ('2.4', 'A company wants software on every laptop that continuously records process, file and network activity, detects suspicious behavior, and lets analysts cut an infected laptop off from the network with one click. What should it deploy?', '[{"text":"Endpoint detection and response (EDR)","is_correct":true},{"text":"A host-based firewall","is_correct":false},{"text":"Mobile device management (MDM) software","is_correct":false},{"text":"An email security gateway","is_correct":false}]', 0, 'EDR agents collect detailed activity from each endpoint, detect threats by behavior as well as signatures, and provide responses such as isolating the host, stopping processes and reviewing what happened. A host-based firewall filters traffic, MDM configures and manages devices, and an email security gateway filters mail before it reaches users.', 2),
  ('2.4', 'How does endpoint detection and response (EDR) differ from traditional antivirus?', '[{"text":"EDR runs only on network routers and firewalls, while traditional antivirus runs on the endpoints","is_correct":false},{"text":"EDR removes the need for patching and backups, while traditional antivirus still needs both","is_correct":false},{"text":"EDR watches endpoint behavior and supports investigation and response; antivirus mainly blocks known files","is_correct":true},{"text":"EDR scans email before it''s delivered, while traditional antivirus scans web traffic","is_correct":false}]', 2, 'Traditional antivirus focuses on matching files against known signatures; EDR records ongoing activity on the endpoint, spots suspicious behavior such as credential theft or fileless scripts, and gives responders tools to contain and investigate. EDR runs on endpoints such as laptops and servers, it doesn''t replace patching or backups, and scanning email before delivery is an email security gateway''s job.', 2),
  ('2.4', 'A 40-person company has EDR installed but nobody to watch its alerts at night or on weekends. Which offering provides 24/7 monitoring, investigation and response by an outside team of security analysts?', '[{"text":"Managed detection and response (MDR)","is_correct":true},{"text":"Extended detection and response (XDR)","is_correct":false},{"text":"Data loss prevention (DLP)","is_correct":false},{"text":"Remote monitoring and management (RMM)","is_correct":false}]', 0, 'MDR is a managed service: a provider''s analysts watch your detection tools around the clock, investigate alerts, hunt for threats and respond, or guide the response, for you. XDR is a technology platform that still needs people to run it, DLP prevents data leaks, and RMM is software IT providers use to monitor and maintain devices rather than a security monitoring service.', 2),
  ('2.4', 'A small business''s MDR provider calls the owner at 2 a.m.: ransomware behavior was detected on a file server, and the provider has already isolated the server from the network. Which statement BEST describes the value MDR provided?', '[{"text":"A signature update was queued, ready to install at the next scheduled scan","is_correct":false},{"text":"Analysts watched the alerts in real time and contained the threat on its behalf","is_correct":true},{"text":"The MDR provider had been taking a nightly backup of the file server","is_correct":false},{"text":"A firewall rule automatically blocked all of the company''s outbound email that night","is_correct":false}]', 1, 'MDR adds people and process to detection tools: analysts triage alerts 24/7 and, as agreed in advance, act at once, here by isolating the server to stop the ransomware spreading. A queued signature update waits for the next scan, MDR isn''t a backup service (backups are still needed to recover), and blocking outbound email wouldn''t contain ransomware on a file server.', 3),
  ('2.4', 'An analyst wants one platform that links a phishing email, the user''s sign-in from an unusual location and malware behavior on the user''s laptop into a single incident. Which technology does this?', '[{"text":"Endpoint detection and response (EDR)","is_correct":false},{"text":"An email security gateway","is_correct":false},{"text":"Signature-based antivirus","is_correct":false},{"text":"Extended detection and response (XDR)","is_correct":true}]', 3, 'XDR collects and correlates detections across several layers, such as email, identity, endpoints, network and cloud, so related alerts become one incident that shows the whole attack. EDR covers endpoints only, an email security gateway sees only mail, and antivirus scans for known malicious files on one device.', 2),
  ('2.4', 'Which statement BEST compares EDR, XDR and MDR?', '[{"text":"EDR covers endpoints, XDR correlates many sources like email, and MDR is a managed service","is_correct":true},{"text":"EDR, XDR and MDR are three brand names for the same signature-based antivirus product","is_correct":false},{"text":"XDR is a managed service, MDR is a type of next-generation firewall, and EDR filters email","is_correct":false},{"text":"MDR runs only on mobile devices, XDR runs only on servers, and EDR runs only on laptops","is_correct":false}]', 0, 'EDR and XDR are technologies: EDR watches and responds on endpoints, while XDR correlates data from many sources into single incidents. MDR is a managed service in which a provider''s analysts monitor and respond using tools like these. They aren''t one product, MDR isn''t a firewall or limited to mobile devices, and filtering email is a gateway''s job.', 3),
  ('2.4', 'A company wants to stop phishing messages, spam and malicious attachments in mail from the internet before they ever reach users'' inboxes. What should it deploy?', '[{"text":"Endpoint DLP","is_correct":false},{"text":"A web proxy server","is_correct":false},{"text":"Full-disk encryption","is_correct":false},{"text":"An email security gateway","is_correct":true}]', 3, 'An email security gateway sits in the mail flow, often as a cloud service that the domain''s MX records point to, and filters inbound mail for spam, phishing, malicious links and attachments, for example by sandboxing files and checking SPF, DKIM and DMARC. Endpoint DLP controls data leaving devices, a web proxy filters browsing, and disk encryption protects stored data.', 2),
  ('2.4', 'Users notice that links in incoming emails now begin with the address of the company''s mail filtering service, and each link is checked before the user is sent on to the real site. Which tool is doing this?', '[{"text":"The browser''s pop-up blocker, checking each new window","is_correct":false},{"text":"The email security gateway, rewriting links and checking them when they''re clicked","is_correct":true},{"text":"Windows Defender Firewall, inspecting outbound connections","is_correct":false},{"text":"The browser''s secure DNS setting, encrypting each lookup the link triggers before loading it","is_correct":false}]', 1, 'Many email security gateways rewrite links so each click is checked against current threat information at the moment it happens, which catches sites that turn malicious after the email arrives. A pop-up blocker stops pop-up windows, the firewall filters network connections, and secure DNS encrypts name lookups; none of them rewrite links in messages.', 2),
  ('2.5', 'Stickers with QR codes are placed over the real codes on a city''s parking meters. Scanning one opens a convincing payment page that collects card details. What is this attack?', '[{"text":"Vishing","is_correct":false},{"text":"Tailgating","is_correct":false},{"text":"QR code phishing","is_correct":true},{"text":"Evil twin","is_correct":false}]', 2, 'QR code phishing, or quishing, uses a QR code to send victims to a malicious site, here a fake payment page; it works because a code''s destination can''t be seen before scanning. Vishing uses voice calls, tailgating follows someone through a secure door, and an evil twin is a rogue Wi-Fi access point that imitates a legitimate one.', 1),
  ('2.5', 'An email that appears to come from IT says the user''s MFA must be re-registered and asks them to scan a QR code with their phone. Why do attackers often put the link in a QR code rather than a clickable link?', '[{"text":"QR codes install malware on a device just by being displayed on its screen, without any scan","is_correct":false},{"text":"QR codes are encrypted, so nobody can check where one leads until after it has been opened","is_correct":false},{"text":"Filters may miss a link inside an image, and the phone often lacks company web protection","is_correct":true},{"text":"QR codes work only on company-managed phones, which are set to trust messages from IT","is_correct":false}]', 2, 'A QR code is an image, so link scanning in email filters can miss it, and scanning it moves the victim to a personal phone that usually lacks the company''s web filtering and has a small screen that hides a suspicious address. Displaying a code installs nothing, codes aren''t encrypted (any scanner app shows the URL), and they work on any device with a camera.', 2),
  ('2.5', 'An attacker researches a company''s payroll clerk on social media, then emails the clerk a message that names their manager and mentions a recent team event, with a link to a fake benefits portal. Which attack is this?', '[{"text":"Whaling","is_correct":false},{"text":"Spear phishing","is_correct":true},{"text":"Smishing","is_correct":false},{"text":"Dumpster diving","is_correct":false}]', 1, 'Spear phishing targets a specific person or small group with a message personalized from research, which makes it more convincing than mass phishing. Whaling is spear phishing aimed at senior executives, smishing uses text messages, and dumpster diving searches discarded material for information.', 1),
  ('2.5', 'What is the key difference between general phishing and spear phishing?', '[{"text":"Spear phishing is tailored to specific people using details about them, not one lure sent to many","is_correct":true},{"text":"Spear phishing always arrives as a phone call or voicemail, while general phishing always arrives as email","is_correct":false},{"text":"Spear phishing targets only CEOs, while general phishing targets all other employees","is_correct":false},{"text":"Spear phishing never contains links or attachments, while general phishing always does","is_correct":false}]', 0, 'General phishing casts a wide net with one generic message, while spear phishing uses researched details such as names, projects and colleagues to fool particular targets. Phishing by phone is vishing, attacks aimed at executives are called whaling, and spear phishing often includes links or attachments.', 2),
  ('2.5', 'An accounts payable clerk receives an email from what appears to be a long-standing supplier''s address. It says the supplier has changed banks and the next invoice should be paid into a new account. The email has no links or attachments. Which attack is this MOST likely to be?', '[{"text":"Cross-site scripting (XSS)","is_correct":false},{"text":"SQL injection","is_correct":false},{"text":"Evil twin","is_correct":false},{"text":"Business email compromise (BEC)","is_correct":true}]', 3, 'BEC uses a compromised or spoofed business email account to trick staff into wire transfers, payment-detail changes or gift-card purchases, and because it often carries no malware or links, filters may miss it. XSS and SQL injection attack web applications, and an evil twin is a rogue Wi-Fi access point.', 2),
  ('2.5', 'Which control BEST protects a company from business email compromise requests to change a vendor''s payment details?', '[{"text":"Reply to the email and ask the sender to confirm in writing that the change is genuine","is_correct":false},{"text":"Install a pop-up blocker in the finance team''s web browsers","is_correct":false},{"text":"Call the vendor back on a phone number already on file, not one from the email","is_correct":true},{"text":"Require vendors to send payment changes as PDF attachments","is_correct":false}]', 2, 'BEC works when people trust the email itself, so the defense is checking through a separate, known channel, backed by a written procedure for payment changes and MFA on email accounts. Replying goes straight back to the attacker when the account is compromised or spoofed, pop-up blockers don''t affect email, and a PDF can be forged as easily as the message.', 2),
  ('2.5', 'Attackers break into a software vendor''s build system and insert a backdoor into a signed update. Thousands of the vendor''s customers install it through their normal patching. What type of attack is this?', '[{"text":"Zero-day attack on the customers'' browsers","is_correct":false},{"text":"Brute-force attack","is_correct":false},{"text":"Insider threat at each customer","is_correct":false},{"text":"Supply chain attack","is_correct":true}]', 3, 'A supply chain (or pipeline) attack compromises a trusted supplier, such as its build pipeline or update servers, to reach the supplier''s customers through software they trust. The customers'' browsers weren''t exploited, no passwords were guessed, and nobody inside the customer organizations acted maliciously.', 2),
  ('2.5', 'A company wants to reduce its risk from supply chain attacks on the software it buys. Which action helps MOST?', '[{"text":"Turn off all software updates permanently, so that no vendor update can ever carry a backdoor into the network","is_correct":false},{"text":"Vet vendors'' security, use official, signed software, and pilot updates before a wide rollout","is_correct":true},{"text":"Let employees install any software they like, as long as it is free of charge","is_correct":false},{"text":"Rely on each vendor''s marketing materials to judge how secure its products are","is_correct":false}]', 1, 'Vendor security assessments, official sources, checking signatures and hashes, and trying updates on a pilot group before company-wide rollout all reduce exposure to a compromised supplier. Turning off updates leaves known vulnerabilities unpatched, free downloads from anywhere add risk, and marketing claims aren''t evidence of security.', 3),
  ('2.6', 'During SOHO malware removal, a technician finds a rootkit that scans from safe mode and from the preinstallation environment can''t fully remove. What is the BEST next step?', '[{"text":"Back up the user''s data, scanning it for malware, then reimage or reinstall the OS","is_correct":true},{"text":"Re-enable System Restore and return the PC to the user right away","is_correct":false},{"text":"Educate the user about safe browsing habits, then close the support ticket as resolved","is_correct":false},{"text":"Run Disk Cleanup to delete the temporary files where the rootkit hides","is_correct":false}]', 0, 'When scanning and removal can''t guarantee a clean system, which is common with rootkits, CompTIA''s procedure moves to reimaging or reinstalling, which returns the OS to a known-good state once the user''s data is saved and scanned. Re-enabling System Restore comes only after remediation, educating the user is the last step once the system is clean, and Disk Cleanup doesn''t remove rootkits.', 2),
  ('2.6', 'Following CompTIA''s SOHO malware removal procedure, a technician has just reimaged an infected Windows 11 Home PC. What should the technician do NEXT?', '[{"text":"Schedule scans and run updates","is_correct":true},{"text":"Quarantine the infected system","is_correct":false},{"text":"Disable System Restore","is_correct":false},{"text":"Investigate and verify the malware symptoms","is_correct":false}]', 0, 'In CompTIA''s procedure, reimaging or reinstalling is part of remediation; next come scheduling scans and running updates, then enabling System Restore and creating a restore point, and finally educating the user. Investigating symptoms, quarantining the system and disabling System Restore are the first three steps, done before remediation.', 2),
  ('2.7', 'After a breach at a shopping website, attackers sign in to a user''s work email with the same email address and password the user had used on the shopping site. Which practice would have prevented this?', '[{"text":"Changing the password every 30 days","is_correct":false},{"text":"Adding a number to the end of the password","is_correct":false},{"text":"Letting the browser remember the password","is_correct":false},{"text":"Using a different password for every account","is_correct":true}]', 3, 'Attackers take credentials leaked from one site and try them on others (credential stuffing), so a unique password for every account keeps a breach in one place from opening the rest. Changing the password regularly or adding a number doesn''t help if the same password is reused everywhere, and having the browser remember it doesn''t make it unique.', 1),
  ('2.7', 'A help desk wants to stop users from choosing a new password that matches one of their last several passwords. Which Windows password policy setting does this?', '[{"text":"Minimum password age","is_correct":false},{"text":"Enforce password history","is_correct":true},{"text":"Password must meet complexity requirements","is_correct":false},{"text":"Account lockout threshold","is_correct":false}]', 1, 'Enforce password history remembers a set number of previous passwords and blocks their reuse. Minimum password age stops users cycling through quick changes to get back to an old password but doesn''t block reuse on its own, complexity requires a mix of character types, and the lockout threshold limits failed sign-in attempts.', 2),
  ('2.7', 'Windows'' Password must meet complexity requirements policy is enabled. Which new password would be accepted for the account jsmith, whose display name is John Smith?', '[{"text":"jsmith2026!","is_correct":false},{"text":"summerharbor","is_correct":false},{"text":"Harbor7-Lantern","is_correct":true},{"text":"SMITH-2026","is_correct":false}]', 2, 'The policy rejects passwords containing the account name, or any part of the display name three or more characters long, and requires characters from three of five categories: uppercase, lowercase, digits, symbols and other Unicode letters. Harbor7-Lantern uses four categories and no part of the name; jsmith2026! contains the account name, summerharbor uses only lowercase letters, and SMITH-2026 contains Smith from the display name.', 2),
  ('2.7', 'A security policy requires passwords to include uppercase and lowercase letters, numbers and symbols. Why does current guidance, such as NIST''s, put more weight on password length than on these complexity rules?', '[{"text":"Longer passwords are always easier for users to remember than shorter, complex ones","is_correct":false},{"text":"Each added character multiplies the possibilities, while forced complexity breeds patterns","is_correct":true},{"text":"Windows doesn''t support complexity rules at all, so password length is the only option left","is_correct":false},{"text":"Symbols can''t be typed on phone keyboards, so complex passwords lock mobile users out","is_correct":false}]', 1, 'Length grows the number of possible passwords fastest, and forced complexity often leads to predictable substitutions like Password1! that cracking tools try early, so NIST''s guidance favors long passphrases checked against lists of breached passwords over composition rules. Long passwords aren''t always easier to remember, Windows does support complexity rules, and symbols can be typed on phones.', 3),
  ('2.7', 'A user has more than 80 online accounts and admits to reusing a few passwords. Which recommendation BEST lets them use a strong, unique password everywhere?', '[{"text":"Use a password manager, protected by a strong master password and MFA","is_correct":true},{"text":"Write the passwords in a notebook kept in a locked drawer beside the PC","is_correct":false},{"text":"Use one very long password for every account","is_correct":false},{"text":"Keep the passwords in a text file on the desktop","is_correct":false}]', 0, 'A password manager generates and stores a long, random, unique password for every account in an encrypted vault, so the user remembers only one strong master password, ideally protected with MFA. A notebook by the PC can be read by anyone nearby, one shared password means one breach exposes every account, and a text file isn''t encrypted.', 1),
  ('2.7', 'A user''s password manager doesn''t offer to fill in their bank password on a page that looks exactly like the bank''s sign-in page. What is the MOST likely reason, and what should the user do?', '[{"text":"The password manager''s vault is corrupted, so the user should type the password in by hand","is_correct":false},{"text":"The bank has changed its logo, so the user should update the saved entry with the new design","is_correct":false},{"text":"The page''s domain doesn''t match the saved one, a sign of phishing, so don''t enter the password","is_correct":true},{"text":"The browser cache is full, so the user should clear it and then try the page again","is_correct":false}]', 2, 'Password managers fill credentials only on the domain saved with them, so a lookalike domain gets no offer, which is a useful warning sign of phishing; typing the password by hand would hand it to the attacker. A corrupted vault, a new logo or a full cache wouldn''t explain a manager that works everywhere else declining this one page.', 3),
  ('2.7', 'A contractor will work at the company until June 30. Which setting makes sure the contractor''s domain account stops working after that date, even if nobody remembers to disable it?', '[{"text":"A password expiration policy of 90 days","is_correct":false},{"text":"An account lockout policy for failed attempts","is_correct":false},{"text":"Restricted log-in hours on the account","is_correct":false},{"text":"An account expiration date on the user account","is_correct":true}]', 3, 'An account expiration date, set on the Account tab in Active Directory Users and Computers or with net user''s /expires option, disables sign-in automatically from that date, so temporary accounts don''t linger. Password expiration only forces a new password, lockout reacts to failed attempts, and log-in hours limit the time of day.', 2),
  ('2.7', 'A technician creates a local account called intern on a kiosk PC for a summer intern and wants it to expire automatically. Which command sets an expiration date?', '[{"text":"net accounts /maxpwage:30","is_correct":false},{"text":"whoami /user","is_correct":false},{"text":"net user intern /active:yes","is_correct":false},{"text":"net user intern /expires:08/31/2026","is_correct":true}]', 3, 'net user with /expires sets the date an account expires (by default accounts never expire), with the date format following the system''s region settings. net accounts /maxpwage sets the maximum password age for every account rather than ending one, whoami /user shows the current user''s SID, and /active:yes enables an account rather than expiring it.', 2),
  ('2.7', 'A hardening checklist for reception PCs says to reduce their attack surface, and an audit finds several services running that the PCs never use. Which action follows the checklist?', '[{"text":"Set every service''s startup type to Automatic, so that all of them are monitored and kept running","is_correct":false},{"text":"In services.msc, stop the services the PCs don''t need and set their startup type to Disabled","is_correct":true},{"text":"Remove the Windows Update service so that updates can''t change the PCs","is_correct":false},{"text":"Turn off Microsoft Defender Antivirus to free up memory for other services","is_correct":false}]', 1, 'Every running service is potential attack surface, especially one that listens on the network, so services a machine doesn''t need should be stopped and disabled. Setting all services to Automatic adds attack surface, removing Windows Update leaves the PCs unpatched, and turning off antivirus removes protection.', 2),
  ('2.7', 'An audit finds the vsftpd FTP server running on a Linux workstation, though nobody uses FTP on it. Which command stops the service now and keeps it from starting at boot?', '[{"text":"sudo systemctl enable vsftpd","is_correct":false},{"text":"sudo systemctl reload vsftpd","is_correct":false},{"text":"sudo systemctl disable --now vsftpd","is_correct":true},{"text":"systemctl status vsftpd","is_correct":false}]', 2, 'systemctl disable --now stops the service immediately and removes it from startup. An FTP server sends credentials in plain text, so an unused one is pure attack surface. enable would start it at every boot, reload rereads its configuration, and status only reports whether it''s running.', 2),
  ('2.8', 'An administrator wants every company iPhone to get the same Wi-Fi settings, VPN, email account and passcode rules without setting up each phone by hand. What should be deployed through the MDM?', '[{"text":"A configuration profile","is_correct":true},{"text":"A Rapid Security Response","is_correct":false},{"text":"A jailbreak","is_correct":false},{"text":"A factory reset","is_correct":false}]', 0, 'A configuration profile is a file (.mobileconfig on Apple devices) that bundles settings such as Wi-Fi, VPN, email, certificates and restrictions; MDM installs it on every enrolled device so they''re all set up the same way. Rapid Security Responses were Apple''s quick security fixes, a jailbreak removes iOS security restrictions, and a factory reset erases the device.', 2),
  ('2.8', 'A user''s personal iPhone sends all web traffic through an unknown VPN and lists an unfamiliar profile under Settings > General > VPN & Device Management. The user installed it from a free streaming website. What should the technician do?', '[{"text":"Leave the profile installed, because configuration profiles can''t change any network settings on a phone","is_correct":false},{"text":"Install a second configuration profile that overrides the settings of the first","is_correct":false},{"text":"Remove the profile, which removes its settings, then change the passwords used on the phone","is_correct":true},{"text":"Turn on Low Power Mode, which disables every VPN configuration on the phone","is_correct":false}]', 2, 'Configuration profiles can install VPNs, proxies and root certificates that let an attacker intercept traffic, so a profile from an untrusted website should be removed (select it under VPN & Device Management and remove it), which removes its settings too; passwords used while it was active may be exposed. Profiles can change network settings, a second profile doesn''t cancel the first, and Low Power Mode doesn''t disable VPN configurations.', 3),
  ('2.8', 'A company''s phones get OS updates promptly, but a security review finds many of their apps months out of date. Which step BEST closes this gap?', '[{"text":"Block the app store on the phones so that installed apps can never change","is_correct":false},{"text":"Ask users to delete and reinstall every one of their apps once a year","is_correct":false},{"text":"Update only the apps that users report as broken or crashing","is_correct":false},{"text":"Turn on automatic app updates, or have the MDM require current app versions","is_correct":true}]', 3, 'Patch management on mobile devices covers apps as well as the OS: automatic updates from the App Store or Google Play, or app versions enforced through MDM, close known app vulnerabilities quickly. Blocking the store freezes vulnerable versions, yearly reinstalls leave months of exposure, and waiting for breakage ignores the security fixes users never notice.', 1),
  ('2.8', 'An Android user installed a navigation app as an APK file from a website. Months later, the Google Play version has security fixes, but the user''s copy has never updated. What is the MOST likely reason?', '[{"text":"Apps sideloaded from outside the store generally don''t get its automatic updates","is_correct":true},{"text":"Android doesn''t allow navigation apps to update while location services are on","is_correct":false},{"text":"The phone''s content filter is blocking the update from downloading from Google Play","is_correct":false},{"text":"The app needs an Apple configuration profile installed before it can update","is_correct":false}]', 0, 'App stores update the apps they installed; an APK sideloaded from a website generally isn''t kept current by Google Play, so it stays on an old, vulnerable version. Reinstalling it from the official store restores automatic updates and Play Protect scanning. Location services don''t block updates, content filters block sites and categories rather than updates, and configuration profiles are an Apple mechanism.', 2),
  ('2.8', 'A school issues tablets to students and must block adult and gambling websites on them, including when they''re used on home Wi-Fi. Which mobile security control does this?', '[{"text":"Device encryption turned on for every tablet''s storage","is_correct":false},{"text":"Content filtering applied to the tablets, for example through MDM","is_correct":true},{"text":"Remote wipe set up for any tablet that is lost or stolen","is_correct":false},{"text":"A locator application installed on every student''s tablet by the school","is_correct":false}]', 1, 'Content filtering blocks websites and apps by category or list; applied on the device, through MDM or a filtering app, it works on any network rather than only behind the school''s firewall. Device encryption protects stored data, remote wipe erases a lost device, and a locator app finds it.', 1),
  ('2.8', 'A parent wants their child''s iPhone to block adult websites in Safari without buying third-party software. Which built-in feature should the technician set up?', '[{"text":"VPN & Device Management, with a new VPN configuration added for Safari","is_correct":false},{"text":"Location Services, turned off for Safari in Privacy & Security settings","is_correct":false},{"text":"Screen Time''s Content & Privacy Restrictions, set to Limit Adult Websites","is_correct":true},{"text":"Software Update, with automatic downloads and installs turned on","is_correct":false}]', 2, 'Screen Time''s Content & Privacy Restrictions include a Web Content setting that can limit adult websites or allow only listed sites, a content filter built into iOS. VPN & Device Management lists profiles and VPN configurations, Location Services controls access to location, and Software Update installs iOS updates.', 2),
  ('2.9', 'A medical clinic is replacing 30 PCs whose drives hold patient records. Which disposal plan BEST meets its regulatory and environmental requirements?', '[{"text":"Delete the patient folders from each drive, then donate the PCs to a local school or charity","is_correct":false},{"text":"Quick format each drive, then put the PCs out with the regular office trash","is_correct":false},{"text":"Keep the old PCs in a locked storage closet until someone decides what to do","is_correct":false},{"text":"Hire a certified vendor to destroy the drives, issue certificates and recycle the rest","is_correct":true}]', 3, 'Health data regulations require patient information to be made unreadable before disposal, and many jurisdictions'' e-waste laws keep electronics out of regular trash, so a certified vendor''s destruction certificates and recycling document compliance with both. Deleting folders or quick formatting leaves recoverable data, the trash breaks e-waste rules, and storing PCs indefinitely leaves the data at risk without solving anything.', 2),
  ('2.9', 'Why should a company check data retention requirements before wiping and recycling its old file servers?', '[{"text":"Data retention rules require every drive to be degaussed twice before it can be recycled","is_correct":false},{"text":"Some records may legally need keeping for years, so preserve them before destroying the drives","is_correct":true},{"text":"Retention requirements apply only to paper records, so the old file servers need no check at all","is_correct":false},{"text":"Recycling vendors refuse to accept any drive that still holds data, so it must be empty","is_correct":false}]', 1, 'Regulations cover keeping data as well as destroying it: tax, healthcare, financial or legal-hold rules can require records to be kept for years, so they must be migrated or archived before the hardware is sanitized. Retention rules don''t prescribe degaussing, they apply to electronic records too, and certified recyclers routinely take drives in order to destroy them.', 2),
  ('2.10', 'A technician is hardening a SOHO router. Which configuration BEST secures access to the router''s management interface?', '[{"text":"Turn off WAN-side management, allow HTTPS admin access from the LAN only, and change the default password","is_correct":true},{"text":"Turn on remote management over HTTP on the WAN port, so the owner can fix problems from anywhere","is_correct":false},{"text":"Keep the default admin password, since it''s printed on the router, and hide the SSID instead","is_correct":false},{"text":"Allow Telnet and HTTP management from any address on the internet, as long as every sign-in attempt is logged","is_correct":false}]', 0, 'Securing management access means limiting who can reach the admin interface and protecting the session: turn off management from the internet side, use HTTPS or SSH rather than HTTP or Telnet, limit access to the LAN or specific addresses, and replace default credentials. Remote HTTP management exposes an unencrypted login page to the internet, hiding the SSID doesn''t protect the admin page, and Telnet sends credentials in plain text.', 2),
  ('2.10', 'A small office''s owner wants to manage the office router from home. Which approach allows this while keeping management access secure?', '[{"text":"Forward port 80 on the router to its own admin page so the owner can reach it from home","is_correct":false},{"text":"Connect to the office over a VPN, then manage the router at its internal address","is_correct":true},{"text":"Turn on remote management with the default credentials so the vendor can help as well","is_correct":false},{"text":"Turn on UPnP so the router opens its admin page to the owner automatically","is_correct":false}]', 1, 'A VPN authenticates and encrypts the connection into the office network, so the router''s admin page never has to face the internet. Forwarding port 80 publishes an unencrypted login page to anyone, default credentials are widely known, and UPnP lets devices open ports on their own, which adds risk rather than securing access.', 3),
  ('2.10', 'A café owner wants to offer customers Wi-Fi without giving them any access to the point-of-sale system and office PC on the same router. Which configuration BEST does this?', '[{"text":"A separate guest network with client isolation, so guests reach only the internet","is_correct":true},{"text":"The main Wi-Fi password, given to customers and changed every month","is_correct":false},{"text":"SSID broadcast turned off on the main network, so that customers can''t find or join it","is_correct":false},{"text":"UPnP turned on, so that customers'' devices can connect without a password","is_correct":false}]', 0, 'A guest network puts visitors on a separate SSID and network segment that reaches the internet but not internal devices, and client isolation stops guests reaching each other. Sharing the main password puts customers on the same network as the point-of-sale system, a hidden SSID is still easy to find, and UPnP doesn''t control who can join; it lets devices open ports on the router, which adds risk.', 2),
  ('2.11', 'A browser downloaded a security update in the background several days ago, but the user hasn''t closed the browser in weeks. What should the technician tell the user?', '[{"text":"Nothing is needed, because a downloaded update protects the browser immediately","is_correct":false},{"text":"Clear the browser cache, which applies any downloaded updates","is_correct":false},{"text":"Restart the browser to apply the update; until then the old version keeps running","is_correct":true},{"text":"Turn off automatic updates to avoid interruptions in the future","is_correct":false}]', 2, 'Browsers such as Chrome and Edge download updates automatically but finish applying them only when the browser restarts, so one left open for weeks keeps running the vulnerable version. Browsers are a common target for drive-by attacks, which is why patching them matters. Clearing the cache doesn''t install anything, and turning off updates leaves known vulnerabilities open.', 1),
  ('2.11', 'Which page shows the installed version of Microsoft Edge, checks for updates and installs any that are available?', '[{"text":"edge://extensions (Extensions)","is_correct":false},{"text":"edge://settings/privacy (Privacy, search, and services)","is_correct":false},{"text":"edge://flags (Experiments)","is_correct":false},{"text":"edge://settings/help (About Microsoft Edge)","is_correct":true}]', 3, 'About Microsoft Edge (edge://settings/help) shows the version, checks for updates and offers to restart the browser when one is ready to apply. edge://extensions manages extensions, the Privacy, search, and services page covers tracking prevention, clearing browsing data and secure DNS, and edge://flags holds experimental features.', 2),
  ('2.11', 'A company requires all web traffic to go through its filtering proxy, proxy.corp.example.com on port 8080, and a new laptop can''t reach external websites. Where should the technician set the proxy so Edge and Chrome on Windows 11 use it?', '[{"text":"Settings > Network & internet > Proxy, with the address and port or a setup script","is_correct":true},{"text":"On each browser''s extensions page, by installing the company''s proxy extension","is_correct":false},{"text":"In the hosts file, by mapping each external website to the proxy''s IP address","is_correct":false},{"text":"In Device Manager, in the advanced properties of the network adapter''s driver","is_correct":false}]', 0, 'Edge and Chrome on Windows use the system proxy settings, set in Settings > Network & internet > Proxy with a manual server and port or an automatic configuration (PAC) script, often pushed by Group Policy. Extensions aren''t the standard way to set a proxy, the hosts file only maps names to addresses, and the adapter''s driver settings control hardware features.', 2),
  ('2.11', 'After a user installed a free VPN download, all their browser traffic goes through an unknown proxy server and they see certificate warnings on banking sites. What should the technician do?', '[{"text":"Accept the certificate warnings, since using any proxy server always causes them","is_correct":false},{"text":"Clear the browser cache and keep using the proxy, since the user installed it on purpose","is_correct":false},{"text":"Switch the browser to private-browsing mode, which always bypasses the proxy server","is_correct":false},{"text":"Remove the proxy setting and the software, then scan and check for added root certificates","is_correct":true}]', 3, 'Malware and shady VPN apps can set a proxy to intercept traffic; certificate warnings appear when it presents certificates the browser doesn''t trust, and some also install a root certificate to hide this. Removing the proxy setting and the software, then scanning, restores direct, trusted connections. Accepting the warnings invites interception, clearing the cache leaves the proxy in place, and private browsing uses the same proxy settings.', 3),
  ('2.11', 'A user often works on public Wi-Fi and wants to stop others on the network from seeing or tampering with the website names the browser looks up. Which browser setting helps?', '[{"text":"Private-browsing mode","is_correct":false},{"text":"The pop-up blocker","is_correct":false},{"text":"Use secure DNS (DNS over HTTPS)","is_correct":true},{"text":"Clear cookies and site data on exit","is_correct":false}]', 2, 'Secure DNS sends the browser''s name lookups to a resolver over HTTPS (DNS over HTTPS), encrypting them so others on the network can''t read or change them. Private browsing only avoids keeping history and cookies on the device, a pop-up blocker blocks new windows, and clearing site data on exit removes stored data.', 2),
  ('2.11', 'A company blocks malicious and banned sites with its internal DNS servers. Users who turned on secure DNS with a public provider in their browsers are no longer filtered. What should the administrator do?', '[{"text":"Block all traffic on port 53 at the firewall, which stops DNS over HTTPS lookups","is_correct":false},{"text":"Use browser policies to turn secure DNS off or point it at the company''s resolver","is_correct":true},{"text":"Have users clear their browser cache at the end of every working day","is_correct":false},{"text":"Disable private-browsing mode in every browser through Group Policy","is_correct":false}]', 1, 'DNS over HTTPS sends lookups over HTTPS, on port 443, to whichever resolver the browser is set to, bypassing internal DNS filtering; managed browser policies for Chrome and Edge can turn secure DNS off or require the company''s resolver. Blocking port 53 doesn''t affect DNS over HTTPS, clearing the cache doesn''t change where lookups go, and private browsing doesn''t control DNS.', 3),
  ('2.11', 'An old internal web app depends on an ActiveX control that current browsers don''t support. Which response BEST balances keeping the app working with security?', '[{"text":"Install an old, unpatched browser that still runs ActiveX and make it the default on every PC","is_correct":false},{"text":"Turn off all of Chrome''s security features so the control can load","is_correct":false},{"text":"Download the control''s installer from a file-sharing website","is_correct":false},{"text":"Open only that site in Microsoft Edge''s Internet Explorer mode, and plan to replace the app","is_correct":true}]', 3, 'Plug-ins and controls run code inside the browser, and legacy ones are a large attack surface, which is why modern browsers dropped them. Edge''s IE mode can run a legacy site that needs ActiveX controls, limited to the sites listed, while the app is replaced. An unpatched default browser exposes every site visit, turning off security features helps attackers, and file-sharing sites are a common source of malware.', 3),
  ('2.11', 'Which statement BEST describes the difference between browser plug-ins and extensions?', '[{"text":"Plug-ins are always safe to install, because only the browser''s own vendor can publish them","is_correct":false},{"text":"Plug-ins render content types the browser can''t, like Flash; extensions add features to the browser","is_correct":true},{"text":"Extensions can be installed only by administrators, while anyone can install plug-ins","is_correct":false},{"text":"Plug-ins and extensions are two names for exactly the same thing in every browser","is_correct":false}]', 1, 'Plug-ins were add-ons that let browsers render content types they couldn''t handle themselves, such as Flash or Java applets, and most legacy plug-ins are no longer supported. Extensions add functions such as ad blocking or password filling and, depending on their permissions, can read page content. Plug-ins often came from third parties, users can usually install extensions unless policy blocks them, and the two aren''t the same thing.', 1),
  ('2.11', 'A user''s browser now uses an unfamiliar search engine and injects ads into every page. An extension installed last week asked for permission to read and change all data on all websites. What should the technician do FIRST?', '[{"text":"Remove the suspicious extension, reset the search engine and scan the PC","is_correct":true},{"text":"Back up the user''s files and reinstall Windows from scratch on the PC","is_correct":false},{"text":"Clear the browser history and leave the extension installed as it is","is_correct":false},{"text":"Tell the user to browse only in private-browsing mode from now on","is_correct":false}]', 0, 'Extensions with broad site permissions can hijack searches, inject ads and read page data, so remove the suspicious one (chrome://extensions or edge://extensions), restore the default search engine and run an anti-malware scan. Reinstalling Windows is excessive before simpler fixes, clearing history doesn''t remove the extension, and private browsing changes only what''s saved for a session while the extension stays installed.', 2),
  ('2.11', 'A company wants employees to use only approved browser extensions from official sources. Which approach BEST enforces this?', '[{"text":"A request that employees read reviews before they install any extension","is_correct":false},{"text":"The browser''s pop-up blocker, turned on for every single website that employees visit","is_correct":false},{"text":"Browser policies, through Group Policy or MDM, allowing only listed extensions","is_correct":true},{"text":"A rule that extensions may be installed only in private-browsing windows","is_correct":false}]', 2, 'Chrome and Edge support enterprise policies that block every extension except an approved list, or force-install approved ones, enforced through Group Policy or MDM. Reviews are easily faked, the pop-up blocker is unrelated, and private browsing doesn''t restrict what can be installed.', 2),
  ('2.11', 'A company uses a dedicated password manager and doesn''t want passwords saved in web browsers. Which browser feature should be turned off, ideally through policy?', '[{"text":"The pop-up blocker for unwanted windows","is_correct":false},{"text":"Secure DNS for encrypted name lookups","is_correct":false},{"text":"Tracking prevention, which blocks third-party trackers","is_correct":false},{"text":"The built-in offer to save passwords and fill them in","is_correct":true}]', 3, 'Browser feature management lets administrators turn individual features on or off: disabling the built-in password saving stops credentials being stored in browser profiles, which may sync to personal accounts, outside the company''s approved tool. The pop-up blocker, secure DNS and tracking prevention protect users and should stay on.', 2),
  ('2.11', 'A user wants websites to stop asking for their location, and wants the camera and microphone blocked for every site except the company''s videoconferencing site. Where should the technician set this?', '[{"text":"The browser''s site permissions for location, camera and microphone","is_correct":true},{"text":"The browser''s pop-up blocker, with the videoconferencing site added as an exception","is_correct":false},{"text":"Clear browsing data, removing cookies and cached images for every site","is_correct":false},{"text":"Private-browsing mode, used for every site except the videoconferencing one","is_correct":false}]', 0, 'Browsers let you allow or block features such as camera, microphone, location and notifications for all sites or for each site (Site settings in Chrome, Cookies and site permissions in Edge). The pop-up blocker only handles new windows, clearing browsing data removes history and cookies, and private browsing doesn''t keep permission choices after the session.', 2),
  ('3.2', 'An iPhone user taps Get on a large game in the App Store, but the download fails right away. The phone shows 900 MB free, and the game needs 3 GB. What should the technician do?', '[{"text":"Reset all of the phone''s settings, then try the download again","is_correct":false},{"text":"Free up storage by offloading unused apps or deleting large files","is_correct":true},{"text":"Turn off Wi-Fi and download the game over Bluetooth instead","is_correct":false},{"text":"Sign out of iCloud, sign back in, then try the download again","is_correct":false}]', 1, 'Not enough storage is one of the most common reasons an app won''t install; offloading unused apps or deleting large media in Settings > General > iPhone Storage frees the space. Resetting settings and signing out of iCloud don''t create space, and apps can''t be downloaded over Bluetooth.', 1),
  ('3.2', 'A company app won''t install on an older Android phone, and Google Play says the device isn''t compatible. The phone has plenty of free storage. What is the MOST likely cause?', '[{"text":"The phone''s screen is set not to rotate automatically when it is turned","is_correct":false},{"text":"Bluetooth is turned off in the phone''s quick settings panel","is_correct":false},{"text":"The app needs a newer Android version or hardware feature than the phone has","is_correct":true},{"text":"The phone''s battery is below 50 percent, so large installs are blocked","is_correct":false}]', 2, 'Apps declare a minimum OS version and the hardware features they need, and the store blocks installation on devices that don''t meet them; the fix is an OS update if one exists, or a supported device. Screen rotation, Bluetooth and battery level don''t affect whether an app is compatible.', 2),
  ('3.2', 'An employee''s company-managed iPad has no App Store icon, and the employee can''t install any apps. Storage and the iPadOS version are fine. What should the technician check?', '[{"text":"Restrictions set in Screen Time or by the MDM that don''t allow installing apps","is_correct":true},{"text":"Whether the iPad is connected to a 5 GHz Wi-Fi network rather than a 2.4 GHz one","is_correct":false},{"text":"Whether the iPad installs security responses automatically","is_correct":false},{"text":"Whether the screen brightness is set to adjust automatically","is_correct":false}]', 0, 'Screen Time''s Content & Privacy Restrictions and MDM restrictions can block app installation, which hides the App Store; the MDM administrator or the Screen Time settings must allow it, or the app can be pushed through MDM instead. The Wi-Fi band, update settings and screen brightness don''t stop apps installing.', 2),
  ('3.4', 'A Windows 11 PC keeps showing notifications in the corner of the screen saying ''Virus detected! Renew your protection now''. They name a website as the sender, not Windows Security, and a full malware scan finds nothing. What is the MOST likely cause and fix?', '[{"text":"A rootkit is hiding in the boot sector, so the PC must be reimaged","is_correct":false},{"text":"A website was allowed to send browser notifications; revoke its permission in the browser","is_correct":true},{"text":"Windows Security has found a real infection, so the user should pay for the renewal","is_correct":false},{"text":"The Windows Update service has failed, so it should be restarted","is_correct":false}]', 1, 'Scam sites trick users into clicking Allow on a notification prompt, then push fake alerts that look like OS notifications but name the site or browser as the sender; removing the site from the browser''s notification permissions stops them. A clean scan and the website sender point away from a rootkit or real infection, the alerts don''t come from Windows Security, and they have nothing to do with Windows Update.', 2),
  ('3.4', 'A PC shows unwanted pop-up notifications advertising system cleanup deals, from an app the user doesn''t remember installing. Which step BEST addresses both the symptom and its cause?', '[{"text":"Turn on Do not disturb permanently, so that the notifications no longer appear","is_correct":false},{"text":"Turn off Windows Defender Firewall, so that the app can no longer reach its advertising servers","is_correct":false},{"text":"Uninstall the app, run an anti-malware scan and check the browsers'' notification permissions","is_correct":true},{"text":"Clear the Windows event logs, so that the app''s records are removed from the PC","is_correct":false}]', 2, 'Unwanted OS notifications often come from PUPs or adware installed alongside other software, or from abused browser permissions, so remove the program, scan for anything left behind and check the browsers. Do not disturb only hides the symptom, turning off the firewall reduces protection, and clearing event logs destroys troubleshooting evidence.', 2),
  ('3.4', 'A PC''s Windows updates keep failing. The Windows Update service is disabled again each time the technician sets it back to Manual, and Microsoft Defender''s real-time protection is off. What should the technician suspect?', '[{"text":"A full system drive, which makes Windows disable services automatically","is_correct":false},{"text":"Windows'' built-in option that pauses updates for up to five weeks","is_correct":false},{"text":"An expired Microsoft 365 license on the user''s account","is_correct":false},{"text":"Malware that disables updates and protection so it can stay on the system","is_correct":true}]', 3, 'Malware often blocks OS updates and turns off antivirus so it can''t be patched out or detected; services that keep being disabled after you fix them, along with disabled protection, point to an infection, so follow the malware removal procedure. A full drive causes update failures but doesn''t disable services, pausing updates doesn''t disable the service, and Microsoft 365 licensing doesn''t control Windows Update.', 2),
  ('3.4', 'Windows Update fails on a PC with errors about corrupted components, and a malware scan is clean. Which is the BEST next step?', '[{"text":"Run chkdsk /f on the C: drive, then format the drive and reinstall the update from scratch","is_correct":false},{"text":"Run DISM /Online /Cleanup-Image /RestoreHealth, then sfc /scannow, then retry the update","is_correct":true},{"text":"Delete the C:\\Windows\\System32 folder, then restart and retry the update","is_correct":false},{"text":"Run whoami /priv to check permissions, then retry the update","is_correct":false}]', 1, 'DISM repairs the Windows component store that updates depend on, using Windows Update as its source by default, and sfc /scannow then repairs protected system files from that store; once both succeed, retry the update. Formatting the drive destroys the installation, deleting System32 breaks Windows, and whoami /priv only lists the current user''s privileges.', 3),
  ('3.4', 'A user''s browser has become very slow, and the laptop''s fan runs constantly while the browser is open, even with a single news site showing. Which tool helps identify the cause FIRST?', '[{"text":"Disk Defragment (dfrgui.exe), run on the browser''s drive","is_correct":false},{"text":"ipconfig /flushdns, to clear cached DNS lookups","is_correct":false},{"text":"The browser''s own task manager (Shift+Esc in Chrome and Edge)","is_correct":true},{"text":"The Security log in Event Viewer (eventvwr.msc)","is_correct":false}]', 2, 'A browser''s task manager lists each tab, extension and process with its CPU and memory use, which quickly reveals a cryptojacking script, a runaway tab or a malicious extension behind the slowdown. Defragmenting doesn''t affect the browser''s CPU use, flushing DNS clears cached name lookups, and the Security log records sign-ins and audit events rather than browser resource use.', 2),
  ('3.4', 'A browser''s task manager shows an extension called PDF Helper using 80% of the CPU at all times, even when no PDFs are open. What is the MOST likely explanation?', '[{"text":"The browser''s cache has grown too large for the drive it''s on","is_correct":false},{"text":"The DNS server the PC uses has started responding slowly","is_correct":false},{"text":"The browser''s secure DNS setting has been turned off","is_correct":false},{"text":"A malicious extension mining cryptocurrency or committing ad fraud","is_correct":true}]', 3, 'An extension using heavy CPU while idle is doing hidden work, such as cryptomining or click fraud, which degrades browser performance; remove it and scan the PC. A large cache uses disk space rather than constant CPU, and DNS problems or settings slow page loading rather than making an extension use CPU.', 2),
  ('3.4', 'A user can''t open any documents on their PC or on a mapped network share. The files have a new extension, and each folder contains a text file with payment instructions. What should the technician do FIRST?', '[{"text":"Disconnect the PC from the network, then follow the incident response process","is_correct":true},{"text":"Pay the ransom, so that the files are decrypted as quickly as possible","is_correct":false},{"text":"Rename the files back to their original extensions, then reopen them","is_correct":false},{"text":"Run Disk Cleanup to delete the text files with the payment instructions","is_correct":false}]', 0, 'Files that won''t open, a new extension and payment notes are signs of ransomware, which can keep encrypting any share it can reach, so isolating the PC limits the damage before incident response and restoring from clean backups. Paying guarantees nothing and funds the attackers, renaming doesn''t decrypt anything, and deleting the notes destroys evidence without fixing the files.', 2),
  ('4.1', 'A company''s contract with its managed service provider says critical incidents get a response within 1 hour and a resolution within 4 hours, with service credits if these targets are missed. What is this document?', '[{"text":"An external service-level agreement (SLA)","is_correct":true},{"text":"An acceptable use policy (AUP)","is_correct":false},{"text":"A non-disclosure agreement (NDA)","is_correct":false},{"text":"A standard operating procedure (SOP)","is_correct":false}]', 0, 'An SLA sets measurable service commitments, such as response and resolution times for each priority, and the remedies when they''re missed; one with an outside provider is an external SLA. An AUP governs how users may use systems, an NDA protects confidential information, and an SOP gives step-by-step instructions for a task.', 1),
  ('4.1', 'The IT department agrees with the sales department that failed laptops will be repaired or replaced by the next business day. Which type of agreement is this?', '[{"text":"An external SLA","is_correct":false},{"text":"A mutual non-disclosure agreement","is_correct":false},{"text":"An internal SLA","is_correct":true},{"text":"An end-user license agreement","is_correct":false}]', 2, 'An internal SLA sets service expectations between departments of the same organization, here IT and sales. An external SLA is made with an outside provider or customer, an MNDA protects information both parties share, and an EULA sets the terms for using software.', 2),
  ('4.1', 'A high-priority ticket will breach its SLA resolution time in 30 minutes, and the assigned technician is still waiting on a part. What should happen, following good ticketing practice?', '[{"text":"Close the ticket now and reopen it later, which resets the SLA timer","is_correct":false},{"text":"Lower the ticket''s severity so that the SLA target no longer applies","is_correct":false},{"text":"Leave the ticket as it is until the part arrives, then update it","is_correct":false},{"text":"Escalate it per the escalation procedure, update the user and record progress","is_correct":true}]', 3, 'SLAs drive ticket priority and escalation: when a deadline is at risk, escalate, keep the user informed and record progress so the response is visible and accountable. Closing and reopening a ticket or lowering its severity to dodge an SLA falsifies the records, and waiting silently guarantees the breach without warning anyone.', 3),
  ('4.1', 'Before upgrading a database server, a technician wants to see which applications and services depend on it. Which asset management resource records configuration items and the relationships between them?', '[{"text":"A knowledge base article written about the server","is_correct":false},{"text":"A configuration management database (CMDB)","is_correct":true},{"text":"An incident report","is_correct":false},{"text":"An acceptable use policy","is_correct":false}]', 1, 'A CMDB stores configuration items, such as hardware, software and services, with their details and the relationships between them, so you can see what depends on a server before changing it. Knowledge base articles document fixes and how-tos, an incident report records what happened in an incident, and an AUP sets rules for using systems.', 2),
  ('4.2', 'Adding a user to an existing security group follows a documented, low-risk procedure that was approved in advance. Which type of change is this?', '[{"text":"Normal change","is_correct":false},{"text":"Emergency change","is_correct":false},{"text":"Change freeze","is_correct":false},{"text":"Standard change","is_correct":true}]', 3, 'A standard change is routine, low-risk and pre-approved, so it follows its documented procedure without going to the change board each time. A normal change needs assessment and approval before it''s scheduled, an emergency change is an urgent fix with fast-tracked approval, and a change freeze is a period when changes aren''t allowed.', 1),
  ('4.2', 'A critical vulnerability in the company''s VPN appliances is being actively exploited, and the vendor has released a patch. Which type of change should be used to apply it?', '[{"text":"Standard change","is_correct":false},{"text":"Emergency change","is_correct":true},{"text":"Normal change, scheduled for next quarter","is_correct":false},{"text":"No change request, because security patches are exempt","is_correct":false}]', 1, 'An emergency change handles an urgent risk or outage that can''t wait for the normal schedule: it gets fast-tracked approval, often from a smaller emergency change board, and is fully documented afterward. A standard change is only for pre-approved routine work, waiting a quarter leaves the exploit open, and security patches still go through change management.', 2),
  ('4.2', 'A team plans to migrate the company''s file server to a new storage system. The change isn''t routine and carries moderate risk. How should it be handled?', '[{"text":"As a standard change, because file servers count as standard equipment","is_correct":false},{"text":"As an emergency change, so that the migration can start immediately","is_correct":false},{"text":"As a normal change, with a request, risk analysis, rollback plan and board approval","is_correct":true},{"text":"With no change request at all, because it''s only an infrastructure upgrade, not an app change","is_correct":false}]', 2, 'A normal change is any change that is neither pre-approved nor urgent, and it goes through the full process: request form, risk analysis, rollback plan, change board approval and scheduling. Standard changes are pre-approved routine tasks, emergency changes are for urgent fixes only, and infrastructure work still needs change management.', 2),
  ('4.2', 'A retailer allows planned changes only on Sundays from 1 a.m. to 5 a.m., and blocks all non-emergency changes from mid-November to early January. What are these two controls?', '[{"text":"A maintenance window and a change freeze","is_correct":true},{"text":"A rollback plan and a backup plan","is_correct":false},{"text":"Sandbox testing and peer review","is_correct":false},{"text":"End-user acceptance and risk analysis","is_correct":false}]', 0, 'A maintenance window is a set, low-impact time when approved changes may be made, and a change freeze blocks non-emergency changes during critical business periods such as holiday sales. Rollback and backup plans cover recovery from a failed change, sandbox testing and peer review check a change before it goes live, and end-user acceptance and risk analysis evaluate it.', 2),
  ('4.2', 'Before a firewall change goes to the change board, a second engineer checks the proposed rules and implementation steps for mistakes. Which part of the change management process is this?', '[{"text":"End-user acceptance","is_correct":false},{"text":"Sandbox testing","is_correct":false},{"text":"Change freeze","is_correct":false},{"text":"Peer review","is_correct":true}]', 3, 'Peer review has another qualified person check a change''s plan or configuration, catching errors before implementation. End-user acceptance confirms with users after the change that it works for them, sandbox testing tries the change in an isolated environment, and a change freeze blocks changes for a period.', 2),
  ('4.2', 'A change request for a database upgrade includes a rollback plan that reinstalls the old version. The change board also asks for a backup plan. What should the backup plan cover?', '[{"text":"A second change board that can approve the change if the first one refuses it","is_correct":false},{"text":"A list of the users to notify by email once the change has been completed","is_correct":false},{"text":"A verified backup of the data, taken first, in case the change or rollback damages it","is_correct":true},{"text":"The date and time of the next maintenance window, in case this one runs over","is_correct":false}]', 2, 'A rollback plan undoes the change itself, for example by reinstalling the previous version, while a backup plan protects the data with a verified backup taken beforehand, so it can be restored if the change or the rollback goes wrong. Approvals, notifications and scheduling are separate parts of the change process.', 3),
  ('4.3', 'A user overwrote an important spreadsheet this morning and wants yesterday''s version back, but also wants to keep today''s version in case some of today''s edits are needed. Which recovery option should the technician choose?', '[{"text":"Restore to an alternative location, so both versions exist","is_correct":true},{"text":"Restore in place, overwriting the current file","is_correct":false},{"text":"Run a new full backup instead of restoring","is_correct":false},{"text":"Restore the whole drive from the oldest backup that''s available","is_correct":false}]', 0, 'Restoring to an alternative location puts the backup copy in a different folder or under a different name, leaving the current file untouched so the user can compare and combine them. An in-place restore would overwrite today''s version, a new full backup doesn''t bring back yesterday''s file, and restoring the whole drive from an old backup would roll back everything else too.', 2),
  ('4.3', 'Ransomware encrypted a file share, and the technician has a clean backup from last night. The encrypted files are worthless, and users need the share back at its usual path as quickly as possible. Which recovery method fits BEST once the infection is removed?', '[{"text":"Alternative-location recovery to a USB drive on the technician''s desk","is_correct":false},{"text":"In-place (overwrite) recovery to the original location","is_correct":true},{"text":"A differential backup of the encrypted files","is_correct":false},{"text":"Restoring only the ransom note files","is_correct":false}]', 1, 'In-place recovery writes the backed-up files over the originals at their usual location, which suits files that are destroyed or worthless and need to be back where users expect them; remove the malware first so the restored files aren''t encrypted again. Restoring to a USB drive leaves the share unusable, backing up the encrypted files saves nothing useful, and ransom notes should be removed rather than restored.', 2),
  ('4.3', 'A file server''s motherboard failed, and a replacement server with a different name is ready. The technician restores the backed-up shares onto the new server. Which type of recovery is this?', '[{"text":"In-place recovery","is_correct":false},{"text":"Alternative location recovery","is_correct":true},{"text":"Synthetic full backup","is_correct":false},{"text":"Incremental backup","is_correct":false}]', 1, 'Restoring data to a different server, folder or drive than the one it came from is alternative location recovery, used here because the original server can''t run. In-place recovery writes back to the original location, overwriting what''s there, and synthetic full and incremental are types of backup, not ways of restoring.', 1),
  ('4.4', 'A technician sets up a training room where power and network cables would cross a walkway to the instructor''s desk. Which action BEST follows safe cable management?', '[{"text":"Tape the cables loosely across the walkway with masking tape","is_correct":false},{"text":"Run the cables under the carpet so nobody can see them","is_correct":false},{"text":"Coil the extra cable on the floor behind the door","is_correct":false},{"text":"Route the cables along the walls or under a floor cable cover","is_correct":true}]', 3, 'Cable management keeps cables out of walkways, routing them along walls, in raceways or under rated floor covers, to prevent trips and damage. Loosely taped cables are still a trip hazard, cables under carpet can be damaged and overheat unseen, and coils on the floor are another trip hazard.', 1),
  ('4.4', 'While tidying a network rack, a technician bundles the patch cables. Which practice is BEST?', '[{"text":"Use hook-and-loop ties, label both ends of each cable, and keep bends gentle","is_correct":true},{"text":"Pull plastic zip ties as tight as possible, so that the bundles can''t move or sag","is_correct":false},{"text":"Bundle the power cords tightly together with the network cables","is_correct":false},{"text":"Leave the cables loose and unlabeled so they''re easier to trace","is_correct":false}]', 0, 'Hook-and-loop ties hold bundles without crushing cables and are easy to reopen, labels make tracing quicker, and gentle bends avoid damaging copper pairs and fiber. Over-tightened zip ties can deform cables and hurt performance, bundling power cords tightly with data cables can cause interference, and loose cables tangle, block airflow and make tracing harder.', 2),
  ('4.6', 'A technician suspects an attacker is active on a workstation and must preserve evidence. Which of these should be collected FIRST?', '[{"text":"The files on the hard drive","is_correct":false},{"text":"Last month''s backup tapes","is_correct":false},{"text":"The contents of RAM, including running processes","is_correct":true},{"text":"Logs stored on the company''s remote logging server","is_correct":false}]', 2, 'The order of volatility says to collect the most short-lived evidence first, and memory, with running processes and network connections, is lost as soon as the system powers off. Files on disk persist, and remote logs and archived backups last longer still, so they''re collected later.', 2),
  ('4.6', 'List these from MOST to LEAST volatile: (1) disk contents, (2) RAM, (3) archived backup media, (4) temporary file systems.', '[{"text":"1, 2, 4, 3","is_correct":false},{"text":"4, 2, 3, 1","is_correct":false},{"text":"2, 1, 4, 3","is_correct":false},{"text":"2, 4, 1, 3","is_correct":true}]', 3, 'Following the order of volatility in RFC 3227: memory is lost at power-off, temporary file systems are cleared on restart or cleanup, disk contents persist but change as the system runs, and archived backup media change least. The other orders put longer-lasting evidence ahead of more volatile evidence.', 3),
  ('4.6', 'A company pays once for a version of a design application and may keep using that version indefinitely, but new major versions must be bought separately. Which license type is this?', '[{"text":"Subscription license","is_correct":false},{"text":"Perpetual license","is_correct":true},{"text":"Open-source license","is_correct":false},{"text":"Personal-use license","is_correct":false}]', 1, 'A perpetual license is a one-time purchase of the right to use a particular version indefinitely; upgrades or support often cost extra. A subscription license works only while payments continue, an open-source license grants rights to use, modify and share the source code, and a personal-use license limits use to non-commercial purposes.', 1),
  ('4.6', 'A company holds perpetual licenses for an accounting application and has stopped paying for the vendor''s maintenance plan. What is the MOST likely result?', '[{"text":"The application stops working at the end of the current month","is_correct":false},{"text":"The licenses automatically turn into open-source licenses","is_correct":false},{"text":"It can keep using its licensed version but gets no new versions or support","is_correct":true},{"text":"The company must uninstall the application from every PC immediately","is_correct":false}]', 2, 'With a perpetual license, the right to use the purchased version continues without further payment, while a maintenance or support plan is what typically provides updates, new versions and help; the company should still watch for that version reaching end of support. A subscription would stop working when payments stop, licenses don''t turn into open-source ones, and nothing requires removing a perpetually licensed version.', 2),
  ('4.6', 'Before a contract technician starts work on a law firm''s servers, the firm asks the technician to sign a document promising not to disclose any client information they see. What is this document?', '[{"text":"A non-disclosure agreement (NDA)","is_correct":true},{"text":"A service-level agreement (SLA)","is_correct":false},{"text":"An end-user license agreement (EULA)","is_correct":false},{"text":"An acceptable use policy (AUP)","is_correct":false}]', 0, 'An NDA is a legal agreement to keep specified information confidential, common for contractors who may see sensitive data. An SLA sets service levels, a EULA sets the terms for using software, and an AUP governs how users may use an organization''s systems.', 1),
  ('4.6', 'Two companies are exploring a joint project, and each will share confidential pricing and technical designs with the other. Which agreement fits BEST?', '[{"text":"A one-way NDA signed only by the smaller company","is_correct":false},{"text":"An internal service-level agreement","is_correct":false},{"text":"A mutual non-disclosure agreement (MNDA)","is_correct":true},{"text":"An open-source license","is_correct":false}]', 2, 'A mutual NDA binds both parties to protect each other''s confidential information, which suits a two-way exchange. A one-way NDA protects only one side''s information, an internal SLA sets service levels within one organization, and an open-source license governs how software may be used rather than confidentiality.', 2),
  ('4.9', 'A technician manages Linux virtual machines on a KVM host and wants to open a VM''s graphical console from a workstation, with USB redirection and audio. Which remote access protocol is designed for this?', '[{"text":"SSH","is_correct":false},{"text":"WinRM","is_correct":false},{"text":"SFTP","is_correct":false},{"text":"SPICE","is_correct":true}]', 3, 'SPICE (Simple Protocol for Independent Computing Environments) gives remote access to virtual machines'' displays, with features such as USB device sharing, audio and folder sharing; clients such as remote-viewer connect to the hypervisor rather than to the guest OS. SSH gives a text shell, WinRM runs remote management commands on Windows, and SFTP transfers files.', 2),
  ('4.9', 'A VM''s network adapter is misconfigured, so RDP and SSH connections to the guest OS fail, but the technician can still see and use the VM''s console through SPICE. Why does SPICE still work?', '[{"text":"SPICE reaches the VM''s display through the hypervisor, not the guest''s network","is_correct":true},{"text":"SPICE switches to the guest''s wireless adapter whenever the wired one fails","is_correct":false},{"text":"SPICE tunnels through the guest''s RDP service using a different port number","is_correct":false},{"text":"SPICE connects only to a guest operating system that has been shut down","is_correct":false}]', 0, 'With SPICE, the hypervisor serves the VM''s display, keyboard and mouse, so the console works even when the guest''s own networking is broken, which makes it ideal for fixing that network. RDP and SSH are services inside the guest that need its networking. SPICE doesn''t use the guest''s adapters or its RDP service, and it shows the running VM, including startup and shutdown.', 3),
  ('4.9', 'An administrator wants to run PowerShell commands on 50 remote Windows servers from one console using Invoke-Command. Which Windows service must be configured on the servers for this?', '[{"text":"Remote Desktop Services","is_correct":false},{"text":"Windows Remote Management (WinRM)","is_correct":true},{"text":"SPICE","is_correct":false},{"text":"Simple Network Management Protocol (SNMP)","is_correct":false}]', 1, 'PowerShell remoting runs over WinRM, Microsoft''s implementation of the WS-Management protocol; Enable-PSRemoting or winrm quickconfig starts the service, creates a listener and opens the firewall. Remote Desktop gives a full graphical session on one server at a time, SPICE is for virtual machine consoles, and SNMP monitors devices rather than running commands.', 2),
  ('4.9', 'By default, which TCP ports do WinRM listeners use for HTTP and HTTPS?', '[{"text":"3389 and 3390","is_correct":false},{"text":"5985 and 5986","is_correct":true},{"text":"22 and 443","is_correct":false},{"text":"5900 and 5901","is_correct":false}]', 1, 'Since WinRM 2.0, the default listener ports are 5985 for HTTP and 5986 for HTTPS; with Kerberos or NTLM authentication the messages are encrypted even over HTTP, and HTTPS adds certificate-based verification of the server. 3389 is RDP, 22 is SSH and 443 is HTTPS for websites, and 5900 and up are commonly used by VNC.', 2),
  ('4.10', 'A technician asks a public AI chatbot for a Windows command, and it confidently gives a command-line switch that doesn''t exist. What is this AI limitation called?', '[{"text":"Bias","is_correct":false},{"text":"Plagiarism","is_correct":false},{"text":"Hallucination","is_correct":true},{"text":"Data privacy","is_correct":false}]', 2, 'A hallucination is output that sounds confident and plausible but is false, such as an invented command switch, citation or setting; check AI-generated commands against vendor documentation before running them. Bias is skew learned from training data, plagiarism is passing off others'' work as your own, and data privacy concerns how personal information is handled.', 1),
  ('4.10', 'An AI tool that screens help desk job applicants consistently ranks candidates from some schools lower, because most of the company''s past hires came from other schools. Which AI limitation does this show?', '[{"text":"Bias","is_correct":true},{"text":"Hallucination","is_correct":false},{"text":"Plagiarism","is_correct":false},{"text":"Data security","is_correct":false}]', 0, 'Bias occurs when a model reflects skew in its training data or design and produces unfair results for some groups, here repeating past hiring patterns. A hallucination is invented false content, plagiarism is presenting others'' work as your own, and data security is about protecting data from unauthorized access.', 2),
  ('4.10', 'An AI assistant summarizes a 40-page vendor contract for a manager. Which practice BEST addresses the accuracy limitations of AI?', '[{"text":"Ask the AI to rate its own confidence, and accept the summary if it''s above 90%","is_correct":false},{"text":"Use the summary as it is, because the AI has read every page of the contract","is_correct":false},{"text":"Ask the AI the same question again until two of its answers match each other","is_correct":false},{"text":"Have a person check key points, such as dates and amounts, against the contract","is_correct":true}]', 3, 'AI output can omit, misread or invent details, so a person checks it against the source, especially figures and commitments. A model''s rating of its own confidence isn''t a reliable measure, reading every page doesn''t guarantee a correct summary, and two matching answers can both be wrong.', 2),
  ('4.10', 'A help desk technician wants to paste a customer''s ticket, including the customer''s name, address and account number, into a free public AI chatbot to draft a reply. What is the MAIN concern?', '[{"text":"Hallucination: the chatbot can''t read street addresses or account numbers correctly","is_correct":false},{"text":"Bias: the chatbot gives some customers better replies than it gives others","is_correct":false},{"text":"Application integration: the chatbot can''t connect to the ticketing system","is_correct":false},{"text":"Data privacy: public AI services may keep or train on prompts, exposing personal data","is_correct":true}]', 3, 'Pasting personal data into a public AI tool sends it outside the company''s control, where the provider may keep it or use it to train models, which can breach privacy law and policy; remove the personal details or use an approved private AI tool. Hallucination, bias and integration are real AI topics, but none is the main risk of sharing this data.', 2),
  ('4.10', 'A company wants employees to use generative AI with internal documents, without that data leaving the company''s control or being used to train the provider''s models. Which option fits BEST?', '[{"text":"A private AI deployment, such as an enterprise service or a self-hosted model","is_correct":true},{"text":"A free public chatbot, used with each employee''s own personal account","is_correct":false},{"text":"Any AI browser extension that offers to summarize documents for free","is_correct":false},{"text":"A public AI service, used over a VPN so the traffic is hidden from everyone else","is_correct":false}]', 0, 'Private AI runs in an environment the organization controls or contracts for, such as an enterprise service with data protection terms or a self-hosted model, so prompts and documents stay within its security boundary and aren''t used to train public models. Free public chatbots and unvetted extensions may keep or share data, and a VPN protects traffic in transit but doesn''t change what the AI provider does with the data.', 2),
  ('4.10', 'A company''s internal AI assistant answers questions from the company''s own policy documents rather than from the open internet. What is an advantage of controlling the data source this way?', '[{"text":"The assistant can no longer make mistakes of any kind in its answers","is_correct":false},{"text":"The assistant no longer needs any security controls or access rules","is_correct":false},{"text":"Answers come from vetted company information, and access to it can be governed","is_correct":true},{"text":"The assistant can now answer questions on any topic, not just company ones","is_correct":false}]', 2, 'The data source an AI draws on shapes its answers: grounding a private assistant in approved internal documents keeps answers relevant and lets the company control and audit what data it uses. It can still make mistakes, it still needs security controls because it holds sensitive data, and a narrow source limits it to those topics.', 2),
  ('4.10', 'A company turns on an AI assistant integrated with its email, documents and chat. Soon after, an employee asks it about salaries and gets details from an HR spreadsheet the employee could technically open but was never meant to see. What does this reveal?', '[{"text":"The assistant broke into the HR system''s database to find the salary data","is_correct":false},{"text":"It uses each user''s existing permissions, so overshared files become easy to find","is_correct":true},{"text":"The assistant is hallucinating, and the salary details it gave are invented","is_correct":false},{"text":"AI integrations always bypass the permissions that are set on files","is_correct":false}]', 1, 'AI assistants built into productivity apps can surface anything the user already has access to, so oversharing that went unnoticed becomes easy to find; review and tighten permissions and data labels before turning on the integration. The assistant didn''t break in, the data is real rather than invented, and these integrations respect the user''s existing permissions rather than bypassing them.', 3),
  ('4.10', 'Which example BEST describes AI application integration?', '[{"text":"An AI feature in a word processor that drafts and rewrites text in the document","is_correct":true},{"text":"A user copying a paragraph from a website and pasting it into a document","is_correct":false},{"text":"A spreadsheet macro scheduled to run every night and email a report","is_correct":false},{"text":"A printer driver that saves any document as a PDF file instead of printing","is_correct":false}]', 0, 'Application integration means AI capabilities are built into the tools people already use, such as drafting in a word processor, summarizing a videoconference or analyzing a spreadsheet, using the app''s own context. Copying text, scheduled macros and printer drivers involve no AI.', 1),
  ('4.10', 'A company publishes a document stating which AI tools employees may use, what kinds of data they may enter into them, and that AI output must be reviewed before it is used. What is this?', '[{"text":"A service-level agreement","is_correct":false},{"text":"A non-disclosure agreement","is_correct":false},{"text":"A change freeze","is_correct":false},{"text":"An appropriate use policy for AI","is_correct":true}]', 3, 'An appropriate use policy for AI, often part of the acceptable use policy, sets which tools are approved, what data may be shared with them and how their output must be checked and disclosed. An SLA sets service levels, an NDA protects confidential information, and a change freeze pauses changes.', 1),
  ('4.10', 'A technician uses an AI tool to write a knowledge base article and publishes it under their own name without review or disclosure. Parts of it closely match a vendor''s copyrighted documentation. Which concern does this raise MOST directly?', '[{"text":"Data source","is_correct":false},{"text":"Bias","is_correct":false},{"text":"Plagiarism","is_correct":true},{"text":"Application integration","is_correct":false}]', 2, 'Presenting AI-generated text as your own original work, especially when it reproduces someone else''s material, is plagiarism and may also infringe copyright; policies typically require reviewing AI output, citing sources and disclosing AI help. Data source, bias and application integration are AI concepts, but none describes passing off others'' work.', 2),
  ('4.10', 'A training team may use AI to help write course material. Which practice BEST avoids plagiarism?', '[{"text":"Use the AI''s output word for word, because AI-generated text is always original","is_correct":false},{"text":"Review and rework AI drafts, cite sources, and disclose AI help as policy requires","is_correct":true},{"text":"Remove every citation from the material, so that the content looks original","is_correct":false},{"text":"Run the AI''s text through a second AI tool, so it is paraphrased automatically","is_correct":false}]', 1, 'AI can reproduce or closely paraphrase existing work, so drafts need human review, checking, citation and disclosure in line with policy. AI text isn''t guaranteed to be original, removing citations is itself plagiarism, and automated paraphrasing hides the source instead of crediting it.', 2),
  ('4.10', 'A junior technician wants to run a PowerShell script that an AI chatbot wrote to clean up user profiles on every company PC. What should happen first?', '[{"text":"Run it on all of the PCs at once, so the cleanup finishes as quickly as possible","is_correct":false},{"text":"Review it, check its cmdlets against documentation, and test it in a sandbox","is_correct":true},{"text":"Ask the chatbot whether the script is safe, and run it if the answer is yes","is_correct":false},{"text":"Rename the script from .ps1 to .bat so that it runs faster on older PCs","is_correct":false}]', 1, 'AI can produce scripts with invented parameters or destructive logic, so a person reviews them, checks them against documentation and tests them in a sandbox before change approval and rollout. Running it everywhere risks mass damage, the chatbot can''t vouch for its own output, and renaming a PowerShell script to .bat just stops it working.', 2),
  ('4.10', 'Before approving a public AI service for staff, a security team reviews its terms of service. Which question is MOST important for data security?', '[{"text":"Whether the AI service can answer questions in more than one language","is_correct":false},{"text":"Whether the AI service''s apps offer a dark mode for use at night","is_correct":false},{"text":"Whether prompts and files are kept, used for training or seen by the provider","is_correct":true},{"text":"How many images the AI service can generate for each user per minute at peak times","is_correct":false}]', 2, 'With a public AI service, the provider holds whatever users submit, so data security depends on its retention, training, access and encryption terms. Language support, interface themes and image speed don''t affect where company data goes or who can see it.', 3),
  ('4.10', 'A technician asks an AI chatbot for the latest firmware version for a vendor''s router, and it names a version that is two releases old. Which limitation does this show, and what should the technician do?', '[{"text":"Accuracy: the model''s knowledge may be out of date, so check the vendor''s website","is_correct":true},{"text":"Bias: the model prefers older firmware, so ask the question again","is_correct":false},{"text":"Plagiarism: the model copied the version number, so cite the chatbot","is_correct":false},{"text":"Data privacy: the model is hiding the newest version, so ask again in private browsing","is_correct":false}]', 0, 'AI models are trained on data up to a point in time and may not know about recent releases, so answers about current versions can be wrong; check the authoritative source, the vendor''s own site. This isn''t bias, citing the chatbot doesn''t make a wrong answer right, and private browsing doesn''t change what the model knows.', 2)
) as v(code, question_text, options, correct_index, explanation, difficulty)
join cert_sub_objectives n on n.code = v.code
join cert_domains d on d.id = n.domain_id and d.certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102');

-- The 220-1102 objectives, now unused.
delete from cert_sub_objectives s
using cert_domains d
where s.domain_id = d.id and d.certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102') and s.code like 'v14-%';

do $$
begin
  if exists (select 1 from cert_questions where certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102') and is_active and sub_objective_id is null) then
    raise exception '220-1202: an active question has no objective';
  end if;
  if (select count(*) from cert_questions where certification_id = (select id from certifications where slug = 'a-plus-core2-220-1102') and is_active) <> 719 then
    raise exception '220-1202: expected 719 active questions';
  end if;
end $$;

-- Saved paths move to 220-1202: answers follow their question (or recall deck) to
-- its V15 objective, finished learn stops follow their objective, and what left
-- the exam is dropped. migrateAPlusV14Progress does the same to a device's copy.
